/* AQA GCSE Chemistry — grade-separated exam-style practice questions.
   Each question: { g: grade 4-9, marks, q, scheme: [mark points], answer } */
export default {
  subjectId: "chemistry",
  sections: {
    "1. Atomic structure & periodic table": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is an element?", scheme: ["A substance made of only one type of atom"], answer: "A substance made of only one type of atom." },
      { g: 4, marks: 1, q: "What is a compound?", scheme: ["Two or more elements chemically bonded/joined together"], answer: "Two or more elements chemically bonded together." },
      { g: 4, marks: 1, q: "What is a mixture?", scheme: ["Two or more substances not chemically joined"], answer: "Two or more substances that are not chemically joined." },
      { g: 4, marks: 1, q: "Name the three sub-atomic particles in an atom.", scheme: ["Protons, neutrons and electrons"], answer: "Protons, neutrons and electrons." },
      { g: 4, marks: 1, q: "What is the charge on a proton?", scheme: ["Positive (+1)"], answer: "Positive (+1)." },
      { g: 4, marks: 1, q: "What is the charge on an electron?", scheme: ["Negative (−1)"], answer: "Negative (−1)." },
      { g: 4, marks: 1, q: "Where in the atom are the protons and neutrons found?", scheme: ["In the nucleus"], answer: "In the nucleus." },
      { g: 4, marks: 1, q: "Where are the electrons found in an atom?", scheme: ["In shells / energy levels around the nucleus"], answer: "In shells (energy levels) around the nucleus." },
      { g: 4, marks: 1, q: "What does the atomic (proton) number tell you?", scheme: ["The number of protons"], answer: "The number of protons in the atom." },
      { g: 4, marks: 1, q: "What does the mass number tell you?", scheme: ["The total number of protons and neutrons"], answer: "The total number of protons and neutrons." },
      { g: 4, marks: 1, q: "What is an isotope?", scheme: ["Atoms of the same element with different numbers of neutrons"], answer: "Atoms of the same element with the same protons but different numbers of neutrons." },
      { g: 4, marks: 1, q: "Who arranged an early periodic table leaving gaps for undiscovered elements?", scheme: ["(Dmitri) Mendeleev"], answer: "Mendeleev." },
      { g: 4, marks: 1, q: "What are the vertical columns of the periodic table called?", scheme: ["Groups"], answer: "Groups." },
      { g: 4, marks: 1, q: "What are the horizontal rows of the periodic table called?", scheme: ["Periods"], answer: "Periods." },
      { g: 4, marks: 1, q: "What are Group 1 elements called?", scheme: ["The alkali metals"], answer: "The alkali metals." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "State the relative charges and masses of the three sub-atomic particles.", scheme: ["Proton: +1 charge, mass 1", "Neutron: 0 charge, mass 1; electron: −1 charge, very small mass (1/2000)"], answer: "Proton: +1, mass 1; neutron: 0, mass 1; electron: −1, mass about 1/2000." },
      { g: 5, marks: 2, q: "Explain why an atom has no overall charge.", scheme: ["Equal numbers of protons and electrons", "Their + and − charges cancel out"], answer: "An atom has equal numbers of protons and electrons, so the positive and negative charges cancel out." },
      { g: 5, marks: 1, q: "What are Group 7 elements called?", scheme: ["The halogens"], answer: "The halogens." },
      { g: 5, marks: 1, q: "What are Group 0 elements called?", scheme: ["The noble gases"], answer: "The noble gases." },
      { g: 5, marks: 1, q: "Write the electronic structure of an atom with 11 electrons.", scheme: ["2, 8, 1"], answer: "2, 8, 1." },
      { g: 5, marks: 1, q: "Why are the noble gases unreactive?", scheme: ["They have a full (stable) outer shell of electrons"], answer: "Because they have a full, stable outer shell of electrons." },
      { g: 5, marks: 1, q: "What does an element's group number tell you about its electrons?", scheme: ["The number of electrons in the outer shell"], answer: "The number of electrons in its outer shell." },
      { g: 5, marks: 1, q: "How many electrons fill the first electron shell?", scheme: ["2"], answer: "2." },
      { g: 5, marks: 1, q: "How many electrons fill the second and third shells?", scheme: ["8"], answer: "8 each." },
      { g: 5, marks: 1, q: "Why did Mendeleev leave gaps in his periodic table?", scheme: ["For elements not yet discovered (so he could predict their properties)"], answer: "For elements that had not yet been discovered, so he could predict their properties." },
      { g: 5, marks: 1, q: "Where are metals found in the periodic table?", scheme: ["On the left and in the centre"], answer: "On the left-hand side and in the centre." },
      { g: 5, marks: 2, q: "Give two physical properties of most metals.", scheme: ["Any two: shiny, conduct electricity/heat, malleable, high melting point, strong"], answer: "They are shiny and conduct electricity (also malleable with high melting points)." },
      { g: 5, marks: 1, q: "What is relative atomic mass?", scheme: ["The average mass of an element's atoms compared with 1/12 of a carbon-12 atom (allowing for isotopes)"], answer: "The average mass of an element's atoms, taking into account the abundance of its isotopes, compared with 1/12 of a carbon-12 atom." },
      { g: 5, marks: 1, q: "How is the modern periodic table ordered?", scheme: ["By increasing atomic (proton) number"], answer: "In order of increasing atomic (proton) number." },
      { g: 5, marks: 1, q: "Write the electronic structure of a chlorine atom (17 electrons).", scheme: ["2, 8, 7"], answer: "2, 8, 7." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "An atom has atomic number 17 and mass number 35. State its numbers of protons, neutrons and electrons.", scheme: ["17 protons and 17 electrons", "18 neutrons (35 − 17)"], answer: "17 protons, 17 electrons and 18 neutrons." },
      { g: 6, marks: 2, q: "Explain why isotopes of an element have the same chemical properties.", scheme: ["They have the same number of electrons", "So the same number of outer-shell electrons, which controls reactions"], answer: "Isotopes have the same number of electrons, and it is the outer-shell electrons that determine chemical properties, so they react the same." },
      { g: 6, marks: 2, q: "Chlorine is 75% chlorine-35 and 25% chlorine-37. Calculate its relative atomic mass.", scheme: ["(35 × 75 + 37 × 25) ÷ 100", "= 35.5"], answer: "(35 × 75 + 37 × 25) ÷ 100 = 3550 ÷ 100 = 35.5." },
      { g: 6, marks: 2, q: "Explain why elements in the same group have similar chemical properties.", scheme: ["They have the same number of electrons in their outer shell", "So they react in similar ways"], answer: "They have the same number of outer-shell electrons, so they react in similar ways." },
      { g: 6, marks: 2, q: "Explain the trend in reactivity going down Group 1.", scheme: ["Reactivity increases down the group", "Outer electron is further from the nucleus/more shielded, so lost more easily"], answer: "Reactivity increases down Group 1 because the outer electron is further from the nucleus and more shielded, so it is lost more easily." },
      { g: 6, marks: 2, q: "Explain the trend in reactivity going down Group 7.", scheme: ["Reactivity decreases down the group", "Larger atom, so it is harder to attract/gain an extra electron"], answer: "Reactivity decreases down Group 7 because the atoms get bigger, so it is harder to attract an extra electron into the outer shell." },
      { g: 6, marks: 2, q: "Explain why Group 0 elements are inert (unreactive).", scheme: ["Full outer shells of electrons", "So they do not need to gain or lose electrons"], answer: "They have full outer shells, so they do not need to gain or lose electrons and are unreactive." },
      { g: 6, marks: 3, q: "Describe what happens when a Group 1 metal is added to water.", scheme: ["Fizzes / moves on the surface", "Produces hydrogen gas", "Forms a metal hydroxide (an alkaline solution)"], answer: "It fizzes and moves on the surface, giving off hydrogen gas and forming an alkaline metal hydroxide solution." },
      { g: 6, marks: 2, q: "How could you separate a mixture, and why is this possible?", scheme: ["By a physical method (e.g. filtration, distillation, evaporation)", "Because the substances are not chemically bonded"], answer: "By a physical method such as filtration or distillation, because the substances in a mixture are not chemically bonded." },
      { g: 6, marks: 2, q: "Describe how the alpha-scattering experiment changed the plum pudding model.", scheme: ["Most alpha particles passed straight through (mostly empty space)", "A few were deflected/bounced back → small, dense, positive nucleus"], answer: "Most alpha particles passed straight through, showing the atom is mostly empty space, but a few were deflected or bounced back, showing there is a small, dense, positively charged nucleus." },
      { g: 6, marks: 2, q: "State the electronic structure of chlorine and explain which group it is in.", scheme: ["2, 8, 7", "7 outer electrons → Group 7"], answer: "2, 8, 7 — it has 7 electrons in its outer shell, so it is in Group 7." },
      { g: 6, marks: 2, q: "Explain the difference between an element and a compound, with an example of each.", scheme: ["Element: one type of atom (e.g. oxygen, O2)", "Compound: two or more elements chemically bonded (e.g. water, H2O)"], answer: "An element contains only one type of atom, such as oxygen, while a compound is two or more elements chemically bonded, such as water." },
      { g: 6, marks: 2, q: "Explain why relative atomic mass is usually not a whole number.", scheme: ["It is an average of the isotopes' masses", "Weighted by their abundances"], answer: "Because it is an average of the masses of the element's isotopes, weighted by how common each one is." },
      { g: 6, marks: 2, q: "Describe the trend in melting points going down Group 1.", scheme: ["Melting point decreases down the group", "(Metallic bonding gets weaker as atoms get bigger)"], answer: "The melting point decreases down Group 1, as the metallic bonding gets weaker with larger atoms." },
      { g: 6, marks: 2, q: "Explain why the alkali metals are stored under oil.", scheme: ["They are very reactive", "Oil stops them reacting with air/water (oxygen and water vapour)"], answer: "They are so reactive that they are stored under oil to stop them reacting with the oxygen and water vapour in the air." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Describe how the model of the atom developed from Dalton to Bohr.", scheme: ["Dalton: atoms as tiny solid spheres", "Thomson: plum pudding — electrons in a ball of positive charge", "Rutherford: nuclear model — small dense positive nucleus, mostly empty space", "Bohr: electrons orbit the nucleus in fixed shells/energy levels"], answer: "Dalton described atoms as tiny solid spheres; Thomson's plum pudding model had electrons in a ball of positive charge; Rutherford's nuclear model placed a small dense positive nucleus in mostly empty space; and Bohr showed the electrons orbit in fixed shells." },
      { g: 7, marks: 3, q: "Explain how the results of the alpha-scattering experiment provided evidence for the nuclear model.", scheme: ["Most particles passed straight through → atom is mostly empty space", "Some deflected → nucleus is positively charged", "Few bounced back → nucleus is small and dense/has most of the mass"], answer: "Most alpha particles passed straight through, showing the atom is mostly empty space; some were deflected, showing the nucleus is positive; and a few bounced back, showing it is very small, dense and contains most of the mass." },
      { g: 7, marks: 3, q: "An element has isotopes of mass 63 (69%) and 65 (31%). Calculate its relative atomic mass.", scheme: ["(63 × 69 + 65 × 31) ÷ 100", "= (4347 + 2015) ÷ 100", "= 63.6"], answer: "(63 × 69 + 65 × 31) ÷ 100 = 6362 ÷ 100 = 63.6." },
      { g: 7, marks: 3, q: "Explain, in terms of electrons, why reactivity increases down Group 1.", scheme: ["Atoms get bigger down the group", "Outer electron is further from the nucleus and more shielded", "So less strongly held → lost more easily → more reactive"], answer: "Going down the group the atoms get bigger, so the single outer electron is further from the nucleus and more shielded by inner shells. It is therefore held less strongly and lost more easily, making the metals more reactive." },
      { g: 7, marks: 3, q: "Explain what happens in a halogen displacement reaction and give an example.", scheme: ["A more reactive halogen displaces a less reactive halogen from its salt", "e.g. chlorine + potassium bromide → potassium chloride + bromine", "Because chlorine is more reactive than bromine"], answer: "A more reactive halogen displaces a less reactive one from a solution of its salt; for example chlorine displaces bromine from potassium bromide, forming potassium chloride and bromine, because chlorine is more reactive." },
      { g: 7, marks: 3, q: "Compare the properties of the transition metals with the Group 1 metals.", scheme: ["Transition metals are harder, stronger, denser, higher melting points", "Less reactive than Group 1", "Form coloured compounds / have variable charges / act as catalysts (any relevant)"], answer: "Transition metals are harder, stronger, denser and have higher melting points than the soft Group 1 metals, and they are much less reactive. They also form coloured compounds, have ions with different charges and act as catalysts." },
      { g: 7, marks: 3, q: "Explain why the modern periodic table is arranged by atomic number, using potassium and argon as an example.", scheme: ["Argon has a greater relative atomic mass than potassium", "Ordering by mass would put them in the wrong groups", "Ordering by atomic (proton) number places them correctly by properties"], answer: "Argon has a higher relative atomic mass than potassium, so ordering by mass would place them in the wrong groups. Ordering by atomic number puts each element with others of similar properties, correctly placing argon in Group 0 and potassium in Group 1." },
      { g: 7, marks: 3, q: "Write the electronic structures of the first three Group 1 elements and state what they have in common.", scheme: ["Lithium 2,1; sodium 2,8,1; potassium 2,8,8,1", "All have one electron in the outer shell"], answer: "Lithium is 2,1; sodium is 2,8,1; potassium is 2,8,8,1 — all have a single electron in their outer shell." },
      { g: 7, marks: 3, q: "Explain how the discovery of the proton (atomic number) improved Mendeleev's table.", scheme: ["Elements could be ordered by atomic number instead of mass", "This explained the order and fixed pairs that seemed out of place", "Confirmed the arrangement by properties"], answer: "Once atomic number was known, elements could be ordered by the number of protons rather than by mass, which explained the arrangement and corrected pairs like argon and potassium that seemed out of order by mass." },
      { g: 7, marks: 3, q: "Predict and explain whether bromine will displace chlorine from sodium chloride.", scheme: ["No, it will not react", "Bromine is less reactive than chlorine", "A less reactive halogen cannot displace a more reactive one"], answer: "No reaction happens, because bromine is less reactive than chlorine and a less reactive halogen cannot displace a more reactive one from its salt." },
      { g: 7, marks: 3, q: "Explain why atoms react to gain a full outer shell, using Group 1 and Group 7 as examples.", scheme: ["A full outer shell is stable (like noble gases)", "Group 1 lose 1 electron to empty the outer shell", "Group 7 gain 1 electron to fill the outer shell"], answer: "Atoms react to achieve a stable, full outer shell like the noble gases. Group 1 metals lose their single outer electron, while Group 7 non-metals gain one electron to complete their outer shell." },
      { g: 7, marks: 3, q: "Describe how you could show that reactivity increases down Group 1 (safely).", scheme: ["Add small pieces of lithium, sodium and potassium to water (behind a screen)", "Observe how vigorously each reacts", "Potassium reacts most vigorously, showing greatest reactivity"], answer: "Add small pieces of lithium, sodium then potassium to water behind a safety screen and observe how vigorous each reaction is; the reactions get more violent down the group, with potassium the most reactive." },
      { g: 7, marks: 3, q: "Explain why the noble gases were not part of Mendeleev's original table but fitted in later.", scheme: ["They had not been discovered / are very unreactive so hard to find", "When discovered, they fitted a new group (Group 0)", "Their properties matched a repeating pattern"], answer: "The noble gases had not yet been discovered because they are so unreactive; when they were found, they fitted neatly into a new Group 0, matching the repeating pattern of the table." },
      { g: 7, marks: 3, q: "Explain the link between an element's period and its electronic structure.", scheme: ["The period number equals the number of occupied electron shells", "e.g. period 3 elements have 3 shells", "Across a period the outer shell fills up"], answer: "The period number tells you how many electron shells are occupied — for example period 3 elements have three shells — and across a period the outer shell gradually fills with electrons." },
      { g: 7, marks: 3, q: "Sodium has the electronic structure 2,8,1. Explain how this relates to its position in the periodic table.", scheme: ["3 shells → period 3", "1 outer electron → Group 1", "So it is a reactive alkali metal"], answer: "It has three occupied shells, so it is in period 3, and one electron in its outer shell, so it is in Group 1 — a reactive alkali metal." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain fully how experimental evidence led scientists to replace the plum pudding model with the nuclear model.", scheme: ["Plum pudding: electrons spread in positive charge", "Alpha scattering: most passed through → mostly empty space (not solid)", "Some deflected → concentrated positive charge (nucleus)", "Few bounced back → nucleus small, dense, holds most of the mass"], answer: "The plum pudding model had electrons spread through a ball of positive charge. In the alpha-scattering experiment most particles passed straight through, showing the atom is mostly empty space rather than solid; some were deflected, showing a concentrated positive charge; and a few bounced back, showing this nucleus is small, dense and holds most of the mass — so the nuclear model replaced it." },
      { g: 8, marks: 3, q: "An element has three isotopes: mass 24 (79%), 25 (10%) and 26 (11%). Calculate its relative atomic mass.", scheme: ["(24×79 + 25×10 + 26×11) ÷ 100", "= (1896 + 250 + 286) ÷ 100", "= 24.3"], answer: "(24 × 79 + 25 × 10 + 26 × 11) ÷ 100 = 2432 ÷ 100 = 24.3." },
      { g: 8, marks: 4, q: "Explain, using atomic structure, why Group 1 metals get more reactive down the group but Group 7 non-metals get less reactive.", scheme: ["Group 1 lose an electron: bigger atom → outer electron lost more easily → more reactive", "Group 7 gain an electron: bigger atom → weaker attraction for the incoming electron → less reactive", "Both due to increasing atomic size and shielding"], answer: "Both trends come from atoms getting bigger with more shielding down a group. Group 1 metals react by losing their outer electron, which becomes easier as the atom grows, so they get more reactive. Group 7 non-metals react by gaining an electron, which becomes harder as the atom grows and attracts it less strongly, so they get less reactive." },
      { g: 8, marks: 4, q: "Compare the properties of the alkali metals and the transition metals, giving reasons.", scheme: ["Alkali metals: soft, low density, low melting points, very reactive, form +1 ions/white compounds", "Transition metals: hard, dense, high melting points, less reactive", "Form ions with different charges", "Form coloured compounds and act as catalysts"], answer: "Alkali metals are soft, low-density metals with low melting points that are very reactive and form +1 ions and white compounds. Transition metals are hard, dense and have high melting points, are much less reactive, form ions with different charges, and make coloured compounds and useful catalysts." },
      { g: 8, marks: 4, q: "Explain fully what happens, in terms of electrons and ions, when chlorine reacts with sodium bromide solution.", scheme: ["Chlorine is more reactive than bromine, so it displaces it", "Chlorine gains electrons to form chloride ions (Cl⁻)", "Bromide ions lose electrons to form bromine (Br₂)", "Products: sodium chloride and bromine"], answer: "Chlorine is more reactive than bromine, so it displaces it: chlorine atoms gain electrons to become chloride ions, while bromide ions lose electrons to form bromine molecules, giving sodium chloride solution and bromine." },
      { g: 8, marks: 4, q: "Evaluate the contributions of Mendeleev and later scientists to the development of the periodic table.", scheme: ["Mendeleev ordered by mass but left gaps and swapped some elements by properties", "He predicted undiscovered elements, later confirmed", "Discovery of isotopes explained mass anomalies", "Discovery of protons (atomic number) gave the correct ordering"], answer: "Mendeleev ordered elements by mass but left gaps and reordered some by their properties, successfully predicting undiscovered elements. Later the discovery of isotopes explained why ordering by mass sometimes failed, and the discovery of the proton allowed elements to be arranged correctly by atomic number." },
      { g: 8, marks: 3, q: "Explain why isotopes of an element have the same chemical properties but can have different physical properties.", scheme: ["Same number of electrons → same chemical reactions", "Different numbers of neutrons → different masses", "So physical properties like density/melting point can differ slightly"], answer: "Isotopes have the same number of electrons, so they react chemically in the same way, but they have different numbers of neutrons and therefore different masses, which can slightly change physical properties such as density." },
      { g: 8, marks: 3, q: "Explain how an element's electronic structure determines both its group and its reactivity.", scheme: ["Number of outer-shell electrons = group number", "This controls how it reacts (gain/lose electrons to fill the shell)", "Distance of outer electrons from the nucleus affects how easily they are lost/gained"], answer: "The number of electrons in the outer shell gives the group number and controls how the element reacts, since atoms react to fill or empty their outer shell. How far these electrons are from the nucleus then affects how reactive the element is." },
      { g: 8, marks: 3, q: "Analyse why the melting points of the Group 1 metals decrease down the group.", scheme: ["Metallic bonding: attraction between positive ions and delocalised electrons", "Atoms get bigger down the group", "Attraction between ions and electrons weakens → lower melting point"], answer: "Group 1 metals are held by metallic bonding between positive ions and delocalised electrons. As you go down the group the atoms get bigger, so this attraction weakens and less energy is needed to melt them, lowering the melting point." },
      { g: 8, marks: 3, q: "Explain why noble gases exist as single atoms while other elements form molecules or bond.", scheme: ["Noble gases have full outer shells", "So they are stable and do not need to gain, lose or share electrons", "Other atoms bond to achieve a full outer shell"], answer: "Noble gases already have full, stable outer shells, so they do not need to gain, lose or share electrons and exist as single atoms, whereas other atoms bond to achieve a full outer shell." },
      { g: 8, marks: 3, q: "A student says 'the mass number equals the mass of the atom in grams'. Explain why this is wrong.", scheme: ["Mass number is just the count of protons + neutrons (relative)", "Not a real mass in grams", "The actual mass of an atom is extremely small"], answer: "The mass number is simply the number of protons plus neutrons, a relative figure, not a mass in grams; the true mass of a single atom is extremely tiny." },
      { g: 8, marks: 4, q: "Explain how the electronic structures of Group 7 elements explain their reactions with metals.", scheme: ["Group 7 have 7 outer electrons", "They gain one electron to complete the outer shell", "Forming −1 ions (halide ions)", "React with metals to form ionic salts"], answer: "Group 7 elements have seven outer electrons and gain one more to complete their outer shell, forming negative halide ions. When they react with metals, the metal loses electrons and the halogen gains them, forming ionic salts." },
      { g: 8, marks: 3, q: "Explain why relative atomic masses are essential for chemical calculations.", scheme: ["They let us compare masses of atoms/amounts of substances", "Used to work out amounts (moles) and reacting masses", "Because we cannot weigh single atoms"], answer: "Because we cannot weigh single atoms, relative atomic masses let us compare the masses of different atoms and calculate amounts of substance (moles) and reacting masses in reactions." },
      { g: 8, marks: 3, q: "Explain why elements in Group 0 have very low boiling points that increase down the group.", scheme: ["They are single atoms with only weak forces between them", "Little energy needed to separate them → low boiling points", "Forces increase with bigger atoms → boiling point rises down the group"], answer: "Noble gases exist as single atoms with only weak forces between them, so little energy is needed to separate them, giving low boiling points; the forces increase as the atoms get bigger, so the boiling point rises down the group." },
      { g: 8, marks: 4, q: "Explain how you could use the periodic table to predict the properties of an unfamiliar Group 1 element (e.g. rubidium).", scheme: ["It is below potassium, so more reactive than potassium", "Lower melting point than the ones above it", "Reacts vigorously with water to give hydrogen and an alkali", "Forms a +1 ion / white compounds"], answer: "As rubidium is below potassium in Group 1, you can predict it is even more reactive than potassium, has a lower melting point, reacts vigorously with water to give hydrogen and an alkaline hydroxide, and forms a +1 ion with white compounds." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain fully how the model of the atom developed, describing the evidence that led to each change.", scheme: ["Dalton: atoms as solid indivisible spheres", "Thomson discovered electrons → plum pudding model", "Rutherford's alpha scattering → nuclear model (empty space, dense positive nucleus)", "Bohr: electrons in fixed shells (explained stability/spectra)", "Chadwick: discovery of the neutron", "Each stage driven by new experimental evidence"], answer: "Dalton pictured atoms as solid, indivisible spheres. Thomson discovered electrons, giving the plum pudding model. Rutherford's alpha-scattering experiment then showed the atom is mostly empty space with a small dense positive nucleus, replacing it with the nuclear model. Bohr proposed that electrons orbit in fixed shells, explaining the atom's stability, and Chadwick later discovered the neutron. Each change was driven by new experimental evidence." },
      { g: 9, marks: 6, q: "Explain how atomic structure accounts for the reactivity trends in Group 1, Group 7 and Group 0.", scheme: ["Group 1: lose 1 outer electron; easier down the group (bigger atom, more shielding) → more reactive", "Group 7: gain 1 electron; harder down the group (weaker attraction) → less reactive", "Group 0: full outer shells → very unreactive", "Reactivity depends on how easily the outer shell is filled/emptied", "Atomic size and shielding are the key factors"], answer: "Reactivity depends on how easily an atom fills or empties its outer shell. Group 1 metals lose one electron, which becomes easier down the group as atoms get bigger and more shielded, so they get more reactive. Group 7 non-metals gain one electron, which becomes harder down the group as the nucleus attracts it less, so they get less reactive. Group 0 elements have full outer shells and so are very unreactive." },
      { g: 9, marks: 5, q: "An element has isotopes of mass 69 (60.1%) and 71 (39.9%). Calculate its relative atomic mass and explain what an isotope is.", scheme: ["(69 × 60.1 + 71 × 39.9) ÷ 100", "= (4146.9 + 2832.9) ÷ 100 = 69.8", "Isotopes: same element, same protons/electrons, different neutrons"], answer: "Relative atomic mass = (69 × 60.1 + 71 × 39.9) ÷ 100 = 6979.8 ÷ 100 = 69.8. Isotopes are atoms of the same element with the same number of protons and electrons but different numbers of neutrons, and so different masses." },
      { g: 9, marks: 6, q: "Explain why the periodic table is such a powerful tool for predicting the properties of elements.", scheme: ["Ordered by atomic number so patterns repeat", "Groups have the same outer electrons → similar properties", "Trends within groups (reactivity, melting point) let you predict unknowns", "Position shows metal/non-metal and likely bonding/ion", "Mendeleev even predicted undiscovered elements", "So properties can be predicted from position"], answer: "Because it is ordered by atomic number, the periodic table shows repeating patterns: elements in the same group share the same number of outer electrons and so have similar properties, and there are clear trends within groups such as reactivity and melting point. This means the properties of an unfamiliar element, and even undiscovered ones as Mendeleev showed, can be predicted from its position." },
      { g: 9, marks: 6, q: "Compare and contrast the alkali metals, the halogens and the transition metals in terms of structure, reactivity and properties.", scheme: ["Alkali metals: Group 1, 1 outer electron, soft, very reactive, +1 ions", "Halogens: Group 7, 7 outer electrons, non-metals, reactive, −1 ions, molecules", "Transition metals: hard, dense, high m.p., less reactive, variable charges, coloured compounds, catalysts", "Reactivity increases down Group 1 but decreases down Group 7", "All positions explained by electronic structure"], answer: "Alkali metals (Group 1) have one outer electron, are soft and very reactive, and form +1 ions, with reactivity increasing down the group. Halogens (Group 7) are reactive non-metals with seven outer electrons that form −1 ions and diatomic molecules, with reactivity decreasing down the group. Transition metals are hard, dense, high-melting and much less reactive, forming ions of different charges, coloured compounds and useful catalysts. All these differences follow from their electronic structures." },
      { g: 9, marks: 5, q: "Explain fully, using electron transfer, what happens when chlorine is bubbled through potassium iodide solution.", scheme: ["Chlorine is more reactive than iodine → displacement", "Chlorine gains electrons to form chloride ions (Cl₂ + 2e⁻ → 2Cl⁻)", "Iodide ions lose electrons to form iodine (2I⁻ → I₂ + 2e⁻)", "Solution turns brown (iodine formed)", "Products: potassium chloride and iodine"], answer: "Chlorine is more reactive than iodine, so it displaces it. Chlorine gains electrons to form chloride ions while iodide ions lose electrons to form iodine, turning the solution brown. The products are potassium chloride and iodine." },
      { g: 9, marks: 6, q: "Evaluate how experimental evidence has shaped our model of the atom, and explain why models can change.", scheme: ["Each model based on the evidence available at the time", "New experiments (cathode rays, alpha scattering, spectra) revealed more detail", "Models were revised or replaced, not simply 'wrong'", "Shows science is provisional and evidence-led", "Current model still a simplification", "Justified conclusion about the nature of scientific models"], answer: "Each atomic model reflected the evidence available at the time: Thomson's discovery of electrons, Rutherford's alpha scattering and later spectral evidence each revealed more detail, so models were revised rather than simply being wrong. This shows scientific models are provisional and evidence-led, and even the current model is a simplification that could change with new evidence." },
      { g: 9, marks: 5, q: "Explain why ordering the periodic table by atomic number, rather than atomic mass, resolved the problems in Mendeleev's table.", scheme: ["Some pairs (e.g. Ar/K, Te/I) are out of order by mass", "Ordering by mass would put them in the wrong groups", "Atomic number (protons) always increases correctly", "Places elements with similar outer electrons together", "Isotopes explain why mass order failed"], answer: "Ordering by mass placed some pairs such as argon and potassium in the wrong groups, because isotopes make average masses uneven. Atomic number always increases in the right order and groups elements by their outer-shell electrons, so ordering by proton number resolved these anomalies." },
      { g: 9, marks: 6, q: "Explain how electronic structure links an element's position in the periodic table, its reactivity and the type of ion it forms.", scheme: ["Number of shells = period", "Outer electrons = group", "Metals lose electrons → positive ions; non-metals gain → negative ions", "Reactivity depends on how easily electrons are lost/gained (atomic size, shielding)", "Group 0 full shell → no ions, unreactive", "Position therefore predicts ion charge and reactivity"], answer: "The number of occupied shells gives the period and the number of outer electrons gives the group. Metals on the left lose electrons to form positive ions and non-metals on the right gain electrons to form negative ions, with the charge set by how many electrons must be lost or gained. How easily this happens — controlled by atomic size and shielding — sets the reactivity, while Group 0 elements have full shells and form no ions." },
      { g: 9, marks: 5, q: "Design an experiment to compare the reactivity of lithium, sodium and potassium safely, and justify your method.", scheme: ["Add equal-sized small pieces of each metal to water behind a safety screen", "Same volume/temperature of water each time", "Observe/measure how vigorously each reacts (fizzing, movement, flame)", "Keep pieces small for safety", "Justify: controlling variables makes it a fair comparison; screen for safety"], answer: "Add equal-sized small pieces of lithium, sodium and potassium to the same volume of water behind a safety screen, keeping the water's temperature and amount the same, and compare how vigorously each reacts. Small pieces and the screen keep it safe, and controlling the other variables makes the comparison of reactivity fair." },
      { g: 9, marks: 6, q: "Explain fully why elements in the same group have similar chemical properties but show gradual trends in reactivity and physical properties.", scheme: ["Same number of outer-shell electrons → react the same way", "So similar chemical properties", "But atoms get larger down the group (more shells)", "Changes how strongly outer electrons are held", "This causes trends in reactivity and melting point", "Illustrate with a group example"], answer: "Elements in a group have the same number of outer-shell electrons, so they react in the same way and share chemical properties. However, going down the group the atoms gain extra shells and get larger, changing how strongly the outer electrons are held, which produces gradual trends — for example increasing reactivity and decreasing melting point in Group 1." },
      { g: 9, marks: 5, q: "Explain how the concept of isotopes and relative atomic mass underpins chemical calculations such as finding amounts of substance.", scheme: ["Elements are mixtures of isotopes of different mass", "Relative atomic mass is the weighted average", "Used as the mass of one mole of atoms", "Lets chemists convert between mass and moles", "So reacting masses and formulae can be calculated"], answer: "Because elements are mixtures of isotopes with different masses, the relative atomic mass is a weighted average that represents the mass of one mole of atoms. This lets chemists convert between mass and moles and so calculate reacting masses, formulae and yields." },
      { g: 9, marks: 6, q: "Explain how atomic size and shielding together control the reactivity of both Group 1 and Group 7 elements.", scheme: ["Down a group atoms get bigger (more shells)", "Inner shells shield outer electrons from the nucleus", "Group 1: outer electron easier to lose → more reactive down the group", "Group 7: harder to attract an electron → less reactive down the group", "Both trends explained by the same two factors", "Nuclear attraction on outer electrons weakens down a group"], answer: "Going down a group atoms gain more shells and get bigger, and inner electrons shield the outer ones from the nucleus, so the nucleus attracts the outer electrons less strongly. In Group 1 this makes the outer electron easier to lose, increasing reactivity down the group, while in Group 7 it makes it harder to attract an extra electron, decreasing reactivity down the group — the same two factors explain both trends." },
      { g: 9, marks: 5, q: "Evaluate the claim that 'Mendeleev's periodic table was correct'.", scheme: ["Strengths: grouped by properties, left gaps, predicted new elements accurately", "Reordered some elements against mass order", "Limitations: no noble gases, no explanation for the order (no atomic number/electrons known)", "Isotopes not known", "Conclusion: remarkably successful but incomplete/refined later"], answer: "Mendeleev's table was remarkably successful: he grouped elements by properties, left gaps and accurately predicted undiscovered elements, even reordering some against their mass. However, it lacked the noble gases, could not explain why the order worked (atomic number and electrons were unknown) and did not account for isotopes. So it was a major achievement but incomplete and later refined." },
      { g: 9, marks: 6, q: "Explain, using electronic structure and the periodic table, why sodium and chlorine react together vigorously to form sodium chloride.", scheme: ["Sodium 2,8,1 has 1 outer electron to lose", "Chlorine 2,8,7 needs 1 electron to fill its shell", "Sodium loses its electron to chlorine → Na⁺ and Cl⁻", "Both achieve full stable outer shells", "Opposite charges attract → ionic bond", "Reaction releases energy, so it is vigorous"], answer: "Sodium (2,8,1) has one outer electron to lose and chlorine (2,8,7) needs one to complete its shell. Sodium transfers its outer electron to chlorine, forming Na⁺ and Cl⁻ ions that both have full, stable outer shells. The oppositely charged ions attract in an ionic bond, and because both reach a stable arrangement the reaction releases energy and is vigorous." },
    ],

    "2. Bonding, structure & properties": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is ionic bonding?", scheme: ["The transfer of electrons between a metal and a non-metal, forming ions"], answer: "The transfer of electrons from a metal to a non-metal, forming charged ions." },
      { g: 4, marks: 1, q: "What is covalent bonding?", scheme: ["The sharing of electrons between non-metal atoms"], answer: "The sharing of pairs of electrons between non-metal atoms." },
      { g: 4, marks: 1, q: "What is metallic bonding?", scheme: ["Attraction between positive metal ions and delocalised electrons"], answer: "The attraction between positive metal ions and a sea of delocalised electrons." },
      { g: 4, marks: 1, q: "What is an ion?", scheme: ["A charged atom (one that has lost or gained electrons)"], answer: "An atom that has lost or gained electrons and so has a charge." },
      { g: 4, marks: 1, q: "What charge do metal ions have?", scheme: ["Positive"], answer: "Positive." },
      { g: 4, marks: 1, q: "What charge do simple non-metal ions usually have?", scheme: ["Negative"], answer: "Negative." },
      { g: 4, marks: 1, q: "Name the three states of matter.", scheme: ["Solid, liquid and gas"], answer: "Solid, liquid and gas." },
      { g: 4, marks: 1, q: "Does diamond conduct electricity?", scheme: ["No"], answer: "No." },
      { g: 4, marks: 1, q: "Does graphite conduct electricity?", scheme: ["Yes"], answer: "Yes." },
      { g: 4, marks: 1, q: "What is an alloy?", scheme: ["A mixture of a metal with one or more other elements"], answer: "A mixture of a metal with one or more other elements." },
      { g: 4, marks: 1, q: "Why can metals conduct electricity?", scheme: ["They have delocalised (free) electrons that carry charge"], answer: "Because they have delocalised electrons that are free to move and carry charge." },
      { g: 4, marks: 1, q: "What holds the ions together in an ionic compound?", scheme: ["Strong electrostatic forces of attraction"], answer: "Strong electrostatic forces of attraction between oppositely charged ions." },
      { g: 4, marks: 1, q: "Name a giant covalent substance.", scheme: ["Diamond / graphite / silicon dioxide (any one)"], answer: "Diamond (or graphite or silicon dioxide)." },
      { g: 4, marks: 1, q: "What is a polymer?", scheme: ["A large molecule made of many repeating units (monomers)"], answer: "A large molecule made from many small repeating units called monomers." },
      { g: 4, marks: 1, q: "Are ionic compounds solid, liquid or gas at room temperature?", scheme: ["Solid"], answer: "Solid." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "State two properties of ionic compounds.", scheme: ["High melting/boiling point", "Conduct electricity when molten or dissolved"], answer: "They have high melting points and conduct electricity when molten or dissolved." },
      { g: 5, marks: 1, q: "What type of structure does sodium chloride have?", scheme: ["A giant ionic lattice"], answer: "A giant ionic lattice." },
      { g: 5, marks: 2, q: "State two properties of small (simple) covalent molecules.", scheme: ["Low melting/boiling points", "Do not conduct electricity"], answer: "They have low melting and boiling points and do not conduct electricity." },
      { g: 5, marks: 1, q: "Why don't simple molecules conduct electricity?", scheme: ["They have no overall charge / no free electrons or ions"], answer: "Because they have no overall charge and no free electrons or ions to carry it." },
      { g: 5, marks: 1, q: "Describe the structure of diamond.", scheme: ["Giant covalent; each carbon bonded to 4 others"], answer: "A giant covalent structure where each carbon atom is covalently bonded to four others." },
      { g: 5, marks: 2, q: "Describe the structure of graphite.", scheme: ["Layers of carbon atoms, each bonded to 3 others", "Delocalised electrons between the layers"], answer: "Layers of carbon atoms, each bonded to three others, with delocalised electrons between the layers." },
      { g: 5, marks: 1, q: "Why is graphite soft and slippery?", scheme: ["The layers can slide over each other (weak forces between layers)"], answer: "Because the layers can slide over one another, as the forces between the layers are weak." },
      { g: 5, marks: 1, q: "What is graphene?", scheme: ["A single layer of graphite (one atom thick)"], answer: "A single layer of graphite, one atom thick." },
      { g: 5, marks: 2, q: "State two properties of metals.", scheme: ["Any two: conduct electricity/heat, malleable, high melting point, strong/shiny"], answer: "They conduct electricity and heat and are malleable (also strong with high melting points)." },
      { g: 5, marks: 1, q: "Why are alloys usually harder than the pure metal?", scheme: ["Different-sized atoms distort the layers so they cannot slide easily"], answer: "The different-sized atoms distort the regular layers so they cannot slide over each other easily." },
      { g: 5, marks: 1, q: "Name a fullerene.", scheme: ["Buckminsterfullerene (C60) / carbon nanotubes"], answer: "Buckminsterfullerene (C60), or carbon nanotubes." },
      { g: 5, marks: 1, q: "Give one use of nanoparticles.", scheme: ["Any one: sunscreens, catalysts, medicine, electronics"], answer: "In sunscreens (also as catalysts, in medicine and in electronics)." },
      { g: 5, marks: 1, q: "Define a giant ionic lattice.", scheme: ["A regular repeating 3D arrangement of oppositely charged ions"], answer: "A regular, repeating three-dimensional arrangement of oppositely charged ions." },
      { g: 5, marks: 1, q: "In a chlorine molecule (Cl₂), how are the atoms held together?", scheme: ["By a shared pair of electrons (single covalent bond)"], answer: "By a shared pair of electrons — a single covalent bond." },
      { g: 5, marks: 1, q: "Why do ionic compounds not conduct electricity when solid?", scheme: ["The ions are fixed in place and cannot move"], answer: "Because the ions are fixed in the lattice and cannot move to carry charge." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why ionic compounds conduct electricity when molten but not when solid.", scheme: ["When molten the ions are free to move and carry charge", "When solid the ions are held in fixed positions"], answer: "When molten (or dissolved) the ions are free to move and carry the charge, but in the solid the ions are fixed in place so they cannot." },
      { g: 6, marks: 2, q: "Explain how an ionic bond forms in sodium chloride.", scheme: ["Sodium transfers its outer electron to chlorine", "Forms Na⁺ and Cl⁻ ions that attract by electrostatic forces"], answer: "Sodium transfers its single outer electron to chlorine, forming a positive Na⁺ ion and a negative Cl⁻ ion that attract each other by strong electrostatic forces." },
      { g: 6, marks: 2, q: "Explain why simple molecular substances have low boiling points.", scheme: ["The forces between molecules (intermolecular forces) are weak", "Only a little energy is needed to overcome them (not the covalent bonds)"], answer: "The weak intermolecular forces between the molecules need only a little energy to overcome, so the boiling point is low; the strong covalent bonds inside the molecules are not broken." },
      { g: 6, marks: 2, q: "Explain why diamond is very hard.", scheme: ["Giant covalent structure", "Many strong covalent bonds throughout"], answer: "Diamond has a giant covalent structure with each carbon held by four strong covalent bonds, so it is very hard." },
      { g: 6, marks: 3, q: "Diamond and graphite are both carbon. Explain why graphite conducts electricity but diamond does not.", scheme: ["In diamond each carbon uses all 4 electrons in bonds → none free", "In graphite each carbon bonds to only 3 others", "The 4th electron is delocalised and can carry charge"], answer: "In diamond each carbon forms four bonds, using all its outer electrons, so none are free to move. In graphite each carbon bonds to only three others, leaving one delocalised electron per atom that can move and carry charge." },
      { g: 6, marks: 2, q: "Explain why metals are malleable (can be bent and shaped).", scheme: ["The layers of positive ions can slide over each other", "The delocalised electrons hold the structure together"], answer: "The layers of metal ions can slide over one another, while the delocalised electrons keep holding the structure together, so metals can be bent and shaped." },
      { g: 6, marks: 2, q: "Explain why metals conduct electricity.", scheme: ["They contain delocalised electrons", "These are free to move through the structure and carry charge"], answer: "Metals contain delocalised electrons that are free to move through the structure and carry electrical charge." },
      { g: 6, marks: 3, q: "Describe metallic bonding.", scheme: ["Giant structure of positive metal ions", "Arranged in regular layers", "In a 'sea' of delocalised electrons, with strong electrostatic attraction between them"], answer: "Metallic bonding is a giant structure of positive metal ions arranged in regular layers surrounded by a sea of delocalised electrons, with strong electrostatic attraction between the ions and the electrons." },
      { g: 6, marks: 2, q: "Explain why graphite is used as a lubricant.", scheme: ["Its layers can slide over each other", "Because the forces between layers are weak"], answer: "Its layers can slide over each other easily because the forces between the layers are weak, so it acts as a lubricant." },
      { g: 6, marks: 2, q: "Explain why nanoparticles are useful as catalysts.", scheme: ["They have a very large surface area to volume ratio", "So more area for reactions to happen on / more effective"], answer: "Nanoparticles have a very large surface area to volume ratio, giving more surface for reactions, which makes them very effective catalysts." },
      { g: 6, marks: 2, q: "Explain why ionic compounds have high melting points.", scheme: ["Strong electrostatic forces between the oppositely charged ions", "A lot of energy is needed to break them"], answer: "There are strong electrostatic forces of attraction between the many oppositely charged ions, and a lot of energy is needed to break them, so the melting point is high." },
      { g: 6, marks: 2, q: "Explain why a polymer is solid at room temperature while a small molecule like methane is a gas.", scheme: ["Polymers are very large molecules with strong intermolecular forces between chains", "Small molecules have weak intermolecular forces → gas"], answer: "Polymer molecules are very large, so the intermolecular forces between the long chains are strong enough to make them solid, whereas small molecules like methane have only weak forces and are gases." },
      { g: 6, marks: 2, q: "Explain the properties that make graphene useful.", scheme: ["One atom thick / very light and strong", "Conducts electricity (delocalised electrons)"], answer: "Graphene is just one atom thick, very light yet strong, and conducts electricity because of its delocalised electrons." },
      { g: 6, marks: 2, q: "Explain why solid ionic compounds are brittle.", scheme: ["When a layer shifts, like charges become aligned", "They repel and the crystal shatters"], answer: "When a force shifts the layers, ions of the same charge line up and repel each other, so the crystal shatters — making it brittle." },
      { g: 6, marks: 2, q: "Use the particle model to explain the difference between a solid and a gas.", scheme: ["Solid: particles close together in fixed positions, strong forces, vibrate", "Gas: particles far apart, random/fast movement, very weak forces"], answer: "In a solid the particles are close together in fixed positions with strong forces, only vibrating, while in a gas the particles are far apart, move quickly and randomly, and have very weak forces between them." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Describe the structure and bonding in sodium chloride and relate it to two of its properties.", scheme: ["Giant ionic lattice of Na⁺ and Cl⁻ ions", "Strong electrostatic forces in all directions", "High melting point — lots of energy to break the forces", "Conducts when molten/dissolved — ions free to move"], answer: "Sodium chloride is a giant ionic lattice of Na⁺ and Cl⁻ ions held by strong electrostatic forces in all directions. This gives it a high melting point because a lot of energy is needed to break these forces, and it conducts electricity when molten or dissolved because the ions are then free to move." },
      { g: 7, marks: 4, q: "Explain fully why diamond and graphite have such different properties despite both being carbon.", scheme: ["Diamond: each C bonded to 4 others, rigid 3D network → hard, no free electrons → doesn't conduct", "Graphite: each C bonded to 3, in layers → layers slide (soft) → one delocalised electron per atom → conducts"], answer: "In diamond each carbon is bonded to four others in a rigid three-dimensional network, making it very hard, and with no free electrons it does not conduct. In graphite each carbon bonds to only three others in layers that can slide (making it soft), and the spare delocalised electron on each atom lets it conduct electricity." },
      { g: 7, marks: 3, q: "Explain why the melting point of an ionic compound depends on the charges on its ions.", scheme: ["Higher charges → stronger electrostatic attraction", "More energy needed to overcome the forces", "So higher melting point (e.g. MgO higher than NaCl)"], answer: "Ions with higher charges attract each other more strongly, so more energy is needed to overcome the forces and the melting point is higher — for example magnesium oxide (2+ and 2−) melts at a much higher temperature than sodium chloride (1+ and 1−)." },
      { g: 7, marks: 3, q: "Compare the structure and bonding of diamond, graphite and graphene.", scheme: ["All giant covalent carbon", "Diamond: each C to 4 others, 3D → hard, insulator", "Graphite: each C to 3, layers, conducts", "Graphene: a single layer of graphite, strong and conducts"], answer: "All three are giant covalent forms of carbon. In diamond each carbon bonds to four others in 3D, making it hard and an insulator; in graphite each bonds to three in layers, so it conducts and is soft; graphene is a single layer of graphite, which is very strong and also conducts." },
      { g: 7, marks: 3, q: "Explain how metallic bonding accounts for both the electrical conductivity and the malleability of metals.", scheme: ["Delocalised electrons move → carry charge (conductivity)", "Layers of ions can slide over each other (malleability)", "Electrons still hold the structure together"], answer: "The delocalised electrons are free to move and carry charge, giving conductivity, while the regular layers of positive ions can slide over each other with the electrons still holding them together, giving malleability." },
      { g: 7, marks: 3, q: "Explain why nanoparticles can have different properties from the same material in bulk, and give one risk.", scheme: ["Very high surface area to volume ratio", "So they can be more reactive/effective in small amounts", "Risk: possible harm to health/environment as effects are not fully known"], answer: "Nanoparticles have a much larger surface area to volume ratio than the bulk material, so they can be more reactive or effective in tiny amounts, but a risk is that their effects on health and the environment are not fully understood." },
      { g: 7, marks: 3, q: "Predict the formula of the ionic compound formed between magnesium (2+) and chloride (1−) ions, and explain.", scheme: ["Mg²⁺ needs two Cl⁻ to balance the charge", "So the formula is MgCl₂", "Total charge must be zero"], answer: "A magnesium ion is 2+ and each chloride ion is 1−, so two chloride ions are needed to balance the charge, giving the formula MgCl₂." },
      { g: 7, marks: 3, q: "Explain why simple molecular substances do not conduct electricity but ionic solutions do.", scheme: ["Simple molecules have no overall charge / no free ions or electrons", "Ionic compounds dissolved in water release ions", "These ions are free to move and carry charge"], answer: "Simple molecules have no overall charge and no free charged particles, so they cannot conduct. When an ionic compound dissolves, its ions become free to move and can carry charge, so the solution conducts." },
      { g: 7, marks: 3, q: "Explain the structure of buckminsterfullerene (C60) and give a use.", scheme: ["A hollow ball/cage of 60 carbon atoms", "Simple molecular (weak forces between molecules)", "Use: drug delivery / lubricants / catalysts (any one)"], answer: "Buckminsterfullerene is a hollow ball-shaped molecule of 60 carbon atoms, with weak forces between the molecules; it can be used for drug delivery (also as a lubricant or catalyst)." },
      { g: 7, marks: 3, q: "Explain why polymers generally have higher melting points than small molecules.", scheme: ["Polymer molecules are much larger/longer", "So there are more/stronger intermolecular forces between chains", "More energy needed to separate them"], answer: "Polymer molecules are much larger, so there are stronger intermolecular forces between the long chains, and more energy is needed to separate them, giving higher melting points than small molecules." },
      { g: 7, marks: 3, q: "Explain, using the particle model, what happens to the particles when a solid melts and then boils.", scheme: ["Melting: particles gain energy, forces weaken, break free of fixed positions → liquid", "Boiling: particles gain more energy, overcome forces between them → gas (spread out)"], answer: "When a solid melts, the particles gain energy and vibrate more until they break free of their fixed positions to form a liquid; when it boils, they gain enough energy to overcome the forces between them and spread far apart as a gas." },
      { g: 7, marks: 3, q: "Explain why graphite is used to make electrodes for electrolysis.", scheme: ["It conducts electricity (delocalised electrons)", "It has a very high melting point / is unreactive", "So it withstands the conditions of electrolysis"], answer: "Graphite conducts electricity because of its delocalised electrons, and it has a very high melting point and is fairly unreactive, so it can withstand the conditions inside an electrolysis cell." },
      { g: 7, marks: 3, q: "Explain why the giant covalent structure of silicon dioxide gives it a high melting point and makes it an insulator.", scheme: ["Giant covalent lattice with many strong covalent bonds", "Lots of energy to break them → high melting point", "No free electrons/ions → does not conduct"], answer: "Silicon dioxide is a giant covalent lattice held by many strong covalent bonds, so a great deal of energy is needed to break them, giving a high melting point, and with no free electrons or ions it does not conduct electricity." },
      { g: 7, marks: 3, q: "Explain why an alloy such as steel is harder than pure iron.", scheme: ["Steel contains atoms of a different size (e.g. carbon)", "These distort the regular layers of iron atoms", "So the layers cannot slide easily → harder"], answer: "Steel contains carbon atoms of a different size to the iron atoms, and these distort the regular layers so they cannot slide over each other easily, making the steel harder than pure iron." },
      { g: 7, marks: 3, q: "Explain why models such as dot-and-cross and ball-and-stick are useful but have limitations.", scheme: ["Useful: show which electrons are shared/transferred or the arrangement of atoms", "Limitation: don't show the true 3D shape/sizes or that electrons are not really dots", "Ball-and-stick exaggerates gaps between atoms"], answer: "Dot-and-cross diagrams usefully show which electrons are transferred or shared, and ball-and-stick shows the arrangement of atoms, but they are limited because they don't show the true sizes and 3D shapes, electrons are not really dots, and ball-and-stick wrongly suggests large gaps between atoms." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain fully how the bonding and structure of ionic compounds gives rise to their main properties.", scheme: ["Giant lattice of oppositely charged ions", "Strong electrostatic forces in all directions → high melting/boiling points", "Solid: ions fixed → doesn't conduct", "Molten/dissolved: ions free to move → conducts"], answer: "Ionic compounds form giant lattices of oppositely charged ions held by strong electrostatic forces acting in all directions. Breaking these forces needs a lot of energy, giving high melting and boiling points. In the solid the ions are fixed so it doesn't conduct, but when molten or dissolved the ions are free to move and it conducts electricity." },
      { g: 8, marks: 4, q: "Compare and explain the properties of diamond, graphite, graphene and fullerenes.", scheme: ["Diamond: 4 bonds each, hard, insulator, high m.p.", "Graphite: 3 bonds, layers slide (soft), conducts", "Graphene: single layer, strong, conducts", "Fullerenes: molecular cages/tubes, used for drug delivery/nanotech"], answer: "Diamond has each carbon bonded to four others, making it hard, high-melting and an insulator. Graphite bonds each carbon to three in sliding layers, so it is soft and conducts. Graphene is a single strong, conducting layer. Fullerenes are molecular cages or tubes used in drug delivery and nanotechnology. Their differences all come from how the carbon atoms are arranged and bonded." },
      { g: 8, marks: 4, q: "Explain how metallic bonding accounts for the electrical conductivity, malleability and high melting points of metals.", scheme: ["Delocalised electrons move → conduct electricity (and heat)", "Layers of ions slide → malleable", "Strong attraction between ions and electrons → high melting point"], answer: "Metals have delocalised electrons that move freely to conduct electricity and heat. Their regular layers of ions can slide over one another, making them malleable, while the strong electrostatic attraction between the positive ions and the delocalised electrons means a lot of energy is needed to melt them, giving high melting points." },
      { g: 8, marks: 3, q: "Explain why magnesium oxide has a much higher melting point than sodium chloride.", scheme: ["MgO has 2+ and 2− ions; NaCl has 1+ and 1−", "Higher charges → stronger electrostatic attraction", "More energy needed to break the bonds → higher melting point"], answer: "Magnesium oxide contains 2+ and 2− ions, whereas sodium chloride has only 1+ and 1− ions. The higher charges give much stronger electrostatic attraction, so more energy is needed to break the bonds and the melting point is higher." },
      { g: 8, marks: 4, q: "Evaluate the use of nanoparticles in products such as sunscreens, considering benefits and risks.", scheme: ["Benefits: large surface area → effective in small amounts; better UV protection/less visible", "Fewer materials used", "Risks: may be absorbed/harm cells; effects on health/environment not fully known", "Justified conclusion"], answer: "Nanoparticles have a huge surface area to volume ratio, so small amounts are very effective — giving better, less visible UV protection while using less material. However, they might be absorbed into the body or damage cells, and their long-term effects on health and the environment are not fully known, so their benefits must be weighed against these uncertainties." },
      { g: 8, marks: 3, q: "Explain how you could use physical properties to decide whether a substance is ionic, simple molecular or giant covalent.", scheme: ["High m.p. + conducts when molten/dissolved → ionic", "Low m.p. + doesn't conduct → simple molecular", "Very high m.p. + doesn't conduct (except graphite) → giant covalent"], answer: "If it has a high melting point and conducts when molten or dissolved, it is ionic; if it has a low melting point and does not conduct, it is simple molecular; if it has a very high melting point and does not conduct (unless it is graphite), it is giant covalent." },
      { g: 8, marks: 3, q: "Explain why substances made of small molecules have low melting points, referring clearly to which forces are broken.", scheme: ["Only the weak intermolecular forces between molecules are overcome when melting", "The strong covalent bonds within molecules are NOT broken", "Little energy needed → low melting point"], answer: "When these substances melt, only the weak intermolecular forces between the molecules are overcome, not the strong covalent bonds inside the molecules. As only a little energy is needed, the melting point is low." },
      { g: 8, marks: 4, q: "Explain the limitations of the simple particle model of the states of matter.", scheme: ["Assumes particles are solid spheres with no forces between them", "Ignores the actual forces (which do exist)", "Assumes no space within particles / doesn't show different particle types", "So it is a simplification"], answer: "The simple particle model treats particles as solid spheres with nothing between them and ignores the forces that actually act between particles and their different sizes and types. It is therefore a simplification that does not fully represent real matter." },
      { g: 8, marks: 3, q: "Explain why alloys are usually more useful than pure metals, using an example.", scheme: ["Alloys are harder/stronger than the pure metal", "Different-sized atoms distort the layers so they can't slide", "e.g. steel (iron + carbon) is stronger than pure iron"], answer: "Alloys are usually harder and stronger than pure metals because the different-sized atoms distort the layers so they cannot slide over each other — for example steel, an alloy of iron and carbon, is much stronger than pure iron." },
      { g: 8, marks: 3, q: "Explain the relationship between the size of a molecule and its boiling point.", scheme: ["Larger molecules have stronger intermolecular forces", "So more energy is needed to separate them", "Boiling point increases with molecule size"], answer: "Larger molecules have stronger intermolecular forces between them, so more energy is needed to separate them and the boiling point increases as the molecules get bigger." },
      { g: 8, marks: 3, q: "Analyse this data and identify the type of structure: melting point 801 °C, conducts when dissolved but not when solid.", scheme: ["High melting point → giant structure with strong bonds", "Conducts when dissolved but not solid → free ions when dissolved", "So it is an ionic compound"], answer: "The high melting point shows a giant structure with strong bonds, and conducting only when dissolved shows it releases free-moving ions — so it is an ionic compound." },
      { g: 8, marks: 3, q: "Explain why graphene is considered a promising material for electronics and composites.", scheme: ["One atom thick but very strong/light", "Excellent electrical conductor (delocalised electrons)", "So useful in small, strong, conductive components/composites"], answer: "Graphene is only one atom thick yet extremely strong and light and conducts electricity very well because of its delocalised electrons, making it promising for small, strong, conductive electronic components and composite materials." },
      { g: 8, marks: 4, q: "Explain how the structure of a thermosoftening polymer differs from a giant covalent structure, and how this affects melting.", scheme: ["Thermosoftening polymer: separate long chains with weak intermolecular forces between them", "Melts easily as only these weak forces are overcome", "Giant covalent: continuous network of strong covalent bonds", "Very high melting point as covalent bonds must break"], answer: "A thermosoftening polymer is made of separate long chains held together by weak intermolecular forces, so it melts easily when only these weak forces are overcome. A giant covalent structure is one continuous network of strong covalent bonds, so it has a very high melting point because the covalent bonds themselves must be broken." },
      { g: 8, marks: 3, q: "Explain why ionic compounds are brittle and shatter when hit, in terms of ions.", scheme: ["A blow shifts the layers of ions", "Ions of the same charge become aligned", "They repel strongly, so the lattice splits/shatters"], answer: "A blow can shift the layers of ions so that ions of the same charge line up; these repel each other strongly, so the lattice splits and the crystal shatters, making ionic compounds brittle." },
      { g: 8, marks: 3, q: "Explain how graphite's structure allows it to act as both a lubricant and an electrical conductor.", scheme: ["Layers held by weak forces slide over each other → lubricant", "Each carbon has one delocalised electron that can move → conducts", "Both properties come from the layered structure"], answer: "Graphite's layers are held together by weak forces, so they slide over each other and it acts as a lubricant, while each carbon atom has a delocalised electron that is free to move and carry charge, so it also conducts electricity — both properties come from its layered structure." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain how the three types of chemical bonding arise from electron arrangements, and how each leads to characteristic properties.", scheme: ["Ionic: metal loses, non-metal gains electrons → ions in a lattice → high m.p., conducts when molten/dissolved", "Covalent: non-metals share electrons → molecules or giant lattices", "Simple molecular: low m.p., non-conductor; giant covalent: high m.p.", "Metallic: ions + delocalised electrons → conduct, malleable, high m.p.", "Each property linked to the bonding", "Clear structure–property links"], answer: "In ionic bonding a metal loses electrons and a non-metal gains them, forming ions in a giant lattice with high melting points that conduct when molten or dissolved. In covalent bonding non-metals share electrons, forming either small molecules (low melting point, non-conducting) or giant covalent lattices (very high melting point). In metallic bonding positive ions sit in a sea of delocalised electrons, giving conduction, malleability and high melting points. Each property follows directly from the bonding and structure." },
      { g: 9, marks: 6, q: "Compare all the forms of carbon studied (diamond, graphite, graphene, fullerenes and nanotubes) and explain a use of each linked to its structure.", scheme: ["Diamond: 4 bonds, hard → cutting tools", "Graphite: 3 bonds, layers/delocalised e⁻ → electrodes/lubricant", "Graphene: single strong conducting layer → electronics", "Fullerenes (C60): cages → drug delivery", "Nanotubes: strong, conduct → composites/electronics", "Each use linked to its structure"], answer: "Diamond's four-bond network makes it hard, so it is used in cutting tools. Graphite's sliding layers and delocalised electrons make it a lubricant and electrode material. Graphene is a single strong, conducting layer used in electronics. Fullerenes such as C60 are hollow cages used to deliver drugs, and nanotubes are strong and conducting, used in composites and electronics — each use following from its structure." },
      { g: 9, marks: 6, q: "Explain fully why ionic compounds only conduct electricity when molten or in solution, referring to ion movement.", scheme: ["Conduction needs charged particles free to move", "In the solid, ions are locked in fixed positions in the lattice", "So no charge can flow", "When molten/dissolved, the lattice breaks up", "Ions become free to move", "Positive and negative ions move to the electrodes, carrying charge"], answer: "Conducting electricity needs charged particles that are free to move. In a solid ionic compound the ions are locked in fixed positions within the lattice, so no charge can flow. When it melts or dissolves, the lattice breaks up and the ions become free to move, so the positive and negative ions can move towards the electrodes and carry the charge." },
      { g: 9, marks: 6, q: "Explain how and why the charge and size of ions determine the strength of an ionic lattice and hence its melting point.", scheme: ["Melting point depends on the strength of electrostatic attraction", "Higher ionic charge → stronger attraction → higher melting point", "Smaller ions → charges closer → stronger attraction", "e.g. MgO (2+,2−, small) very high; NaCl lower", "More energy needed to overcome stronger forces"], answer: "The melting point depends on how strong the electrostatic attraction between the ions is. Ions with higher charges attract more strongly, and smaller ions bring the charges closer together, both increasing the attraction. So magnesium oxide, with small 2+ and 2− ions, has a very high melting point, while sodium chloride, with singly charged ions, is lower — more energy is needed to overcome the stronger forces." },
      { g: 9, marks: 5, q: "Explain how you could deduce the structure and bonding of four unknown substances from a table of their physical properties.", scheme: ["High m.p. + conducts molten/aqueous, not solid → ionic", "Low m.p. + non-conductor → simple molecular", "Very high m.p. + non-conductor → giant covalent (diamond-like)", "High m.p. + conducts when solid → metallic (or graphite for covalent that conducts)", "Use the combination of properties, not one alone"], answer: "A substance with a high melting point that conducts when molten or dissolved but not when solid is ionic; a low melting point non-conductor is simple molecular; a very high melting point non-conductor is giant covalent; and one that conducts even as a solid with a high melting point is metallic (graphite being the covalent exception that conducts). You judge from the combination of properties, not any single one." },
      { g: 9, marks: 6, q: "Evaluate the benefits and risks of using nanoparticles in consumer products.", scheme: ["Benefits: huge surface area → effective catalysts, better sunscreens, targeted medicine, stronger/lighter materials", "Use less material", "Risks: may be absorbed into the body/cells; toxicity uncertain", "Environmental effects unknown; hard to remove", "Need for testing/regulation", "Justified conclusion balancing benefits and precaution"], answer: "Nanoparticles' very large surface area makes them excellent catalysts, effective sunscreens, useful for targeted medicine and for making strong, light materials while using less material. However, they may be absorbed into cells with uncertain toxicity, their environmental effects are not fully known, and they are hard to remove once released. Their clear benefits must therefore be balanced against careful testing and regulation." },
      { g: 9, marks: 5, q: "Explain why diamond, sodium chloride and iodine have very different melting points, linking each to its structure and bonding.", scheme: ["Diamond: giant covalent, many strong covalent bonds → very high m.p.", "Sodium chloride: giant ionic, strong electrostatic forces → high m.p.", "Iodine: simple molecular, weak intermolecular forces → low m.p.", "The type of forces broken determines the melting point"], answer: "Diamond is giant covalent, so melting it means breaking many strong covalent bonds, giving a very high melting point. Sodium chloride is a giant ionic lattice with strong electrostatic forces, giving a high melting point. Iodine is simple molecular, so only weak intermolecular forces are overcome, giving a low melting point — the type of force broken determines the melting point." },
      { g: 9, marks: 6, q: "Explain fully the structure and bonding of a metal and how it explains why metals are good conductors, malleable and have high melting points, and why alloys differ.", scheme: ["Giant structure of positive ions in a sea of delocalised electrons", "Delocalised electrons move → conduct electricity and heat", "Layers of ions slide → malleable", "Strong attraction ions–electrons → high melting point", "Alloys: different-sized atoms distort layers → harder (can't slide)", "Property links explained"], answer: "A metal is a giant structure of positive ions in a sea of delocalised electrons. The electrons move freely to conduct electricity and heat, the layers of ions can slide over one another making the metal malleable, and the strong attraction between the ions and electrons gives a high melting point. In an alloy, atoms of different sizes distort the layers so they cannot slide easily, making the alloy harder than the pure metal." },
      { g: 9, marks: 5, q: "Design an experiment to classify three unknown solids as ionic, simple molecular or giant covalent, and justify the tests you choose.", scheme: ["Test melting point (heat and observe)", "Test electrical conductivity as a solid and when dissolved/molten", "Test solubility in water", "Ionic: high m.p., conducts when dissolved; molecular: low m.p., non-conductor; giant covalent: very high m.p., non-conductor", "Justify: these properties directly reveal the structure/bonding"], answer: "Measure each solid's melting point, test whether it conducts electricity as a solid and when dissolved or molten, and test its solubility. An ionic solid will have a high melting point and conduct when dissolved; a simple molecular solid will have a low melting point and not conduct; a giant covalent solid will have a very high melting point and not conduct. These property tests are chosen because they directly reveal the structure and bonding." },
      { g: 9, marks: 6, q: "Explain how graphene's structure gives it its exceptional strength and conductivity, and discuss its potential uses.", scheme: ["Single layer of carbon, each bonded to 3 others in a hexagonal network", "Many strong covalent bonds → very strong for its weight", "One atom thick → extremely light/flexible", "One delocalised electron per atom → excellent conductor", "Uses: flexible electronics, touchscreens, composites, sensors", "Properties linked to uses"], answer: "Graphene is a single layer of carbon atoms each bonded to three others in a hexagonal network, so its many strong covalent bonds make it extremely strong for its weight while being just one atom thick and flexible. Each atom's spare delocalised electron makes it an excellent conductor. These properties suit it to flexible electronics, touchscreens, strong composites and sensors." },
      { g: 9, marks: 5, q: "Explain, in terms of forces, why some covalent substances (like methane) have very low melting points while others (like diamond) have very high ones.", scheme: ["Methane: separate small molecules with weak intermolecular forces", "Only these weak forces are overcome on melting → low m.p.", "Diamond: giant covalent network, no separate molecules", "Melting means breaking strong covalent bonds → very high m.p.", "Difference is molecular vs giant structure"], answer: "Methane exists as separate small molecules with only weak intermolecular forces, so melting overcomes just these weak forces and needs little energy, giving a low melting point. Diamond is one giant covalent network with no separate molecules, so melting means breaking strong covalent bonds throughout, needing huge energy — hence its very high melting point. The difference is between a simple molecular and a giant covalent structure." },
      { g: 9, marks: 6, q: "Evaluate the statement: 'all giant structures have high melting points'.", scheme: ["Giant ionic (NaCl) and giant covalent (diamond) do have high melting points", "Giant metallic also generally high", "But it depends on bond/force strength — e.g. Group 1 metals have relatively low melting points despite being giant metallic", "Some giant structures weaker than others", "Conclusion: mostly true but not universal — depends on the strength of the bonding"], answer: "Giant ionic structures like sodium chloride, giant covalent ones like diamond and most giant metallic structures do have high melting points because many strong bonds or attractions must be overcome. However, it is not universally true: Group 1 metals are giant metallic yet have relatively low melting points because their metallic bonding is weaker. So the statement is generally true but depends on how strong the bonding in the giant structure is." },
      { g: 9, marks: 5, q: "Explain the link between an element's position in the periodic table, the type of bonding it forms, and the properties of its compounds.", scheme: ["Metals (left) lose electrons → ionic bonding with non-metals", "Non-metals (right) share electrons → covalent bonding together", "Metal + metal → metallic (alloys)", "Position predicts bonding type", "Bonding type predicts properties (m.p., conductivity)"], answer: "Metals on the left lose electrons and bond ionically with non-metals, non-metals on the right share electrons and bond covalently with each other, and metals bond metallically together. So an element's position predicts the type of bonding it forms, which in turn predicts the properties of its compounds, such as melting point and conductivity." },
      { g: 9, marks: 6, q: "Explain fully the structure and bonding of a polymer and how they determine its properties and uses.", scheme: ["Long chains of repeating units (monomers) joined by covalent bonds", "Weak intermolecular forces between chains", "So solid but flexible; melts at moderate temperatures (thermosoftening)", "Longer chains/stronger forces → stronger, higher melting", "Used for packaging, bottles, etc. depending on properties", "Properties linked to structure"], answer: "A polymer is made of long chains of repeating monomer units joined by strong covalent bonds, with weaker intermolecular forces between the chains. This makes it solid but flexible and, if thermosoftening, able to melt at moderate temperatures. Longer chains or stronger forces between them make the polymer stronger and higher-melting, which is why different polymers are chosen for uses such as flexible packaging or rigid bottles." },
      { g: 9, marks: 5, q: "Explain how the structure and bonding of silicon dioxide make it suitable for use in sandpaper and in glass making.", scheme: ["Giant covalent lattice of many strong Si–O covalent bonds", "Very hard → good abrasive for sandpaper", "Very high melting point → withstands high temperatures in glass making", "No free electrons/ions → an insulator", "Uses follow from the giant covalent structure"], answer: "Silicon dioxide is a giant covalent lattice held by many strong silicon–oxygen bonds, which makes it very hard and gives it a very high melting point. Its hardness makes it a good abrasive for sandpaper, and its high melting point lets it withstand the heat of glass making, while having no free electrons makes it an insulator — all following from its giant covalent structure." },
    ],

    "3. Quantitative chemistry": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "State the law of conservation of mass.", scheme: ["No atoms are lost or made in a reaction / total mass of reactants = total mass of products"], answer: "No atoms are created or destroyed in a reaction, so the total mass of the reactants equals the total mass of the products." },
      { g: 4, marks: 1, q: "What is the relative formula mass (Mr) of a compound?", scheme: ["The sum of the relative atomic masses of all the atoms in its formula"], answer: "The sum of the relative atomic masses of all the atoms shown in its formula." },
      { g: 4, marks: 1, q: "Calculate the Mr of water, H₂O. (H = 1, O = 16)", scheme: ["(2×1) + 16 = 18"], answer: "(2 × 1) + 16 = 18." },
      { g: 4, marks: 1, q: "Calculate the Mr of carbon dioxide, CO₂. (C = 12, O = 16)", scheme: ["12 + (2×16) = 44"], answer: "12 + (2 × 16) = 44." },
      { g: 4, marks: 1, q: "What is a mole?", scheme: ["The amount of a substance containing 6.02 × 10²³ particles"], answer: "The amount of a substance that contains 6.02 × 10²³ particles." },
      { g: 4, marks: 1, q: "What is Avogadro's number?", scheme: ["6.02 × 10²³"], answer: "6.02 × 10²³." },
      { g: 4, marks: 1, q: "Write the formula linking moles, mass and Mr.", scheme: ["moles = mass ÷ Mr"], answer: "moles = mass ÷ relative formula mass (Mr)." },
      { g: 4, marks: 1, q: "What must be the same on both sides of a balanced chemical equation?", scheme: ["The number of atoms of each element"], answer: "The number of atoms of each element." },
      { g: 4, marks: 1, q: "What is a limiting reactant?", scheme: ["The reactant that is used up first, stopping the reaction"], answer: "The reactant that runs out first, stopping the reaction." },
      { g: 4, marks: 1, q: "Give two units used to measure the concentration of a solution.", scheme: ["g/dm³ and mol/dm³"], answer: "Grams per dm³ (g/dm³) and moles per dm³ (mol/dm³)." },
      { g: 4, marks: 1, q: "What does the percentage yield of a reaction tell you?", scheme: ["How much product you actually made compared with the maximum possible"], answer: "How much product you actually made compared with the maximum possible amount." },
      { g: 4, marks: 1, q: "Why might the mass seem to decrease when a metal carbonate is heated in an open dish?", scheme: ["A gas (carbon dioxide) is released and escapes"], answer: "A gas — carbon dioxide — is released and escapes into the air." },
      { g: 4, marks: 1, q: "Why might the mass seem to increase when a metal burns in air?", scheme: ["Oxygen from the air combines with/adds to the metal"], answer: "Oxygen from the air combines with the metal and adds to its mass." },
      { g: 4, marks: 1, q: "Convert 1000 cm³ into dm³.", scheme: ["1 dm³"], answer: "1 dm³." },
      { g: 4, marks: 1, q: "Calculate the Mr of oxygen gas, O₂. (O = 16)", scheme: ["2 × 16 = 32"], answer: "2 × 16 = 32." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Calculate the Mr of sodium chloride, NaCl. (Na = 23, Cl = 35.5)", scheme: ["23 + 35.5 = 58.5"], answer: "23 + 35.5 = 58.5." },
      { g: 5, marks: 2, q: "Calculate the Mr of calcium carbonate, CaCO₃. (Ca = 40, C = 12, O = 16)", scheme: ["40 + 12 + (3×16)", "= 100"], answer: "40 + 12 + (3 × 16) = 100." },
      { g: 5, marks: 1, q: "Rearrange 'moles = mass ÷ Mr' to make mass the subject.", scheme: ["mass = moles × Mr"], answer: "mass = moles × Mr." },
      { g: 5, marks: 2, q: "Calculate the number of moles in 36 g of water. (Mr = 18)", scheme: ["moles = 36 ÷ 18", "= 2 mol"], answer: "moles = 36 ÷ 18 = 2 mol." },
      { g: 5, marks: 2, q: "Calculate the mass of 0.5 mol of carbon dioxide. (Mr = 44)", scheme: ["mass = 0.5 × 44", "= 22 g"], answer: "mass = 0.5 × 44 = 22 g." },
      { g: 5, marks: 2, q: "Balance the equation: H₂ + O₂ → H₂O.", scheme: ["2H₂ + O₂ → 2H₂O"], answer: "2H₂ + O₂ → 2H₂O." },
      { g: 5, marks: 1, q: "Write the formula for percentage yield.", scheme: ["(actual yield ÷ theoretical yield) × 100"], answer: "percentage yield = (actual yield ÷ theoretical yield) × 100." },
      { g: 5, marks: 1, q: "Give one reason the percentage yield of a reaction is often below 100%.", scheme: ["Any one: reaction incomplete/reversible, product lost in transfer/filtering, side reactions"], answer: "Because some product is lost during transfer, or the reaction is incomplete or reversible." },
      { g: 5, marks: 1, q: "Write the formula for concentration in g/dm³.", scheme: ["concentration = mass ÷ volume (in dm³)"], answer: "concentration = mass (g) ÷ volume (dm³)." },
      { g: 5, marks: 1, q: "Calculate the concentration of 20 g of solute dissolved in 2 dm³ of solution.", scheme: ["20 ÷ 2 = 10 g/dm³"], answer: "20 ÷ 2 = 10 g/dm³." },
      { g: 5, marks: 1, q: "Convert 500 cm³ into dm³.", scheme: ["0.5 dm³"], answer: "0.5 dm³." },
      { g: 5, marks: 1, q: "How many particles are there in one mole of a substance?", scheme: ["6.02 × 10²³"], answer: "6.02 × 10²³." },
      { g: 5, marks: 2, q: "Calculate the Mr of sulfuric acid, H₂SO₄. (H = 1, S = 32, O = 16)", scheme: ["(2×1) + 32 + (4×16)", "= 98"], answer: "(2 × 1) + 32 + (4 × 16) = 98." },
      { g: 5, marks: 1, q: "Explain why mass is conserved in a chemical reaction.", scheme: ["Atoms are only rearranged, not created or destroyed"], answer: "Because atoms are only rearranged during a reaction — none are created or destroyed — so the total mass stays the same." },
      { g: 5, marks: 1, q: "Calculate the number of moles in 25 g of calcium carbonate. (Mr = 100)", scheme: ["25 ÷ 100 = 0.25 mol"], answer: "25 ÷ 100 = 0.25 mol." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Calculate the number of moles in 8 g of oxygen gas, O₂. (Mr = 32)", scheme: ["moles = 8 ÷ 32", "= 0.25 mol"], answer: "moles = 8 ÷ 32 = 0.25 mol." },
      { g: 6, marks: 2, q: "Balance the equation: Fe + O₂ → Fe₂O₃.", scheme: ["4Fe + 3O₂ → 2Fe₂O₃"], answer: "4Fe + 3O₂ → 2Fe₂O₃." },
      { g: 6, marks: 2, q: "Explain why the mass increases when magnesium burns in air.", scheme: ["Magnesium combines with oxygen from the air", "The oxide's mass includes the added oxygen"], answer: "The magnesium combines with oxygen from the air, and the magnesium oxide formed includes the mass of that added oxygen, so the mass increases." },
      { g: 6, marks: 2, q: "Explain why the mass decreases when a metal carbonate is heated in an open crucible.", scheme: ["Carbon dioxide gas is produced", "It escapes into the air, so the remaining solid weighs less"], answer: "Heating produces carbon dioxide gas, which escapes into the air, so the solid left behind weighs less." },
      { g: 6, marks: 2, q: "Calculate the concentration in g/dm³ of 25 g of solute in 250 cm³ of solution.", scheme: ["250 cm³ = 0.25 dm³", "25 ÷ 0.25 = 100 g/dm³"], answer: "250 cm³ = 0.25 dm³, so concentration = 25 ÷ 0.25 = 100 g/dm³." },
      { g: 6, marks: 2, q: "A reaction has a theoretical yield of 8 g but produces 6 g. Calculate the percentage yield.", scheme: ["(6 ÷ 8) × 100", "= 75%"], answer: "(6 ÷ 8) × 100 = 75%." },
      { g: 6, marks: 2, q: "Calculate the mass of 0.2 mol of sodium hydroxide, NaOH. (Mr = 40)", scheme: ["mass = 0.2 × 40", "= 8 g"], answer: "mass = 0.2 × 40 = 8 g." },
      { g: 6, marks: 1, q: "What is meant by a reactant being 'in excess'?", scheme: ["It is not all used up / more is present than needed"], answer: "There is more of it than is needed, so it is not all used up." },
      { g: 6, marks: 2, q: "Balance the equation for making ammonia: N₂ + H₂ → NH₃.", scheme: ["N₂ + 3H₂ → 2NH₃"], answer: "N₂ + 3H₂ → 2NH₃." },
      { g: 6, marks: 2, q: "Calculate the Mr of calcium hydroxide, Ca(OH)₂. (Ca = 40, O = 16, H = 1)", scheme: ["40 + 2×(16 + 1)", "= 74"], answer: "40 + 2 × (16 + 1) = 74." },
      { g: 6, marks: 2, q: "Calculate the number of moles in 4.4 g of carbon dioxide. (Mr = 44)", scheme: ["4.4 ÷ 44", "= 0.1 mol"], answer: "4.4 ÷ 44 = 0.1 mol." },
      { g: 6, marks: 2, q: "Calculate the concentration in mol/dm³ of 0.5 mol of solute in 2 dm³ of solution.", scheme: ["0.5 ÷ 2", "= 0.25 mol/dm³"], answer: "0.5 ÷ 2 = 0.25 mol/dm³." },
      { g: 6, marks: 2, q: "Explain why a reaction done in an open flask may appear to lose mass.", scheme: ["A gaseous product is made", "It escapes from the flask into the air"], answer: "A gaseous product is formed and escapes from the open flask into the air, so the measured mass falls." },
      { g: 6, marks: 2, q: "Calculate the mass of oxygen in one mole of carbon dioxide, CO₂. (O = 16)", scheme: ["2 oxygen atoms × 16", "= 32 g"], answer: "There are two oxygen atoms, so 2 × 16 = 32 g." },
      { g: 6, marks: 2, q: "Calculate the number of moles in 5.6 g of iron. (Ar = 56)", scheme: ["5.6 ÷ 56", "= 0.1 mol"], answer: "5.6 ÷ 56 = 0.1 mol." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "Calculate the mass of magnesium oxide formed when 48 g of magnesium reacts fully with oxygen. (Mg = 24, MgO = 40; 2Mg + O₂ → 2MgO)", scheme: ["moles Mg = 48 ÷ 24 = 2 mol", "ratio Mg:MgO = 1:1 → 2 mol MgO", "mass = 2 × 40 = 80 g"], answer: "Moles Mg = 48 ÷ 24 = 2 mol. The ratio Mg:MgO is 1:1, so 2 mol MgO forms. Mass = 2 × 40 = 80 g." },
      { g: 7, marks: 3, q: "Calculate the mass of water formed when 4 g of hydrogen burns. (H₂ = 2, H₂O = 18; 2H₂ + O₂ → 2H₂O)", scheme: ["moles H₂ = 4 ÷ 2 = 2 mol", "ratio H₂:H₂O = 1:1 → 2 mol water", "mass = 2 × 18 = 36 g"], answer: "Moles H₂ = 4 ÷ 2 = 2 mol. The ratio H₂:H₂O is 1:1, so 2 mol water forms. Mass = 2 × 18 = 36 g." },
      { g: 7, marks: 2, q: "Describe how you would work out which reactant is the limiting reactant from their masses.", scheme: ["Convert each mass to moles (mass ÷ Mr)", "Divide by the balancing numbers; the reactant giving the smallest value is limiting"], answer: "Convert each reactant's mass to moles, then divide each by its balancing number in the equation — the one that gives the smallest value is the limiting reactant." },
      { g: 7, marks: 2, q: "Calculate the concentration in mol/dm³ of 0.5 mol of solute in 250 cm³ of solution.", scheme: ["250 cm³ = 0.25 dm³", "0.5 ÷ 0.25 = 2 mol/dm³"], answer: "250 cm³ = 0.25 dm³, so concentration = 0.5 ÷ 0.25 = 2 mol/dm³." },
      { g: 7, marks: 3, q: "Explain, in terms of atoms and bonds, why mass is conserved in every chemical reaction.", scheme: ["Bonds in reactants break and new bonds form", "The same atoms are present before and after", "No atoms are created or destroyed → same total mass"], answer: "During a reaction the bonds in the reactants break and new bonds form in the products, but the same atoms are simply rearranged. Since no atoms are created or destroyed, the total mass stays the same." },
      { g: 7, marks: 2, q: "Calculate the number of moles of solute in 50 cm³ of a 0.1 mol/dm³ solution.", scheme: ["moles = concentration × volume (dm³) = 0.1 × 0.05", "= 0.005 mol"], answer: "moles = 0.1 × (50 ÷ 1000) = 0.1 × 0.05 = 0.005 mol." },
      { g: 7, marks: 2, q: "Balance the equation: Al + Cl₂ → AlCl₃.", scheme: ["2Al + 3Cl₂ → 2AlCl₃"], answer: "2Al + 3Cl₂ → 2AlCl₃." },
      { g: 7, marks: 3, q: "Calculate the mass of carbon dioxide produced when 10 g of calcium carbonate decomposes. (CaCO₃ → CaO + CO₂; Mr CaCO₃ = 100, CO₂ = 44)", scheme: ["moles CaCO₃ = 10 ÷ 100 = 0.1 mol", "ratio 1:1 → 0.1 mol CO₂", "mass = 0.1 × 44 = 4.4 g"], answer: "Moles CaCO₃ = 10 ÷ 100 = 0.1 mol. The ratio is 1:1, so 0.1 mol CO₂ forms. Mass = 0.1 × 44 = 4.4 g." },
      { g: 7, marks: 2, q: "Explain why a high percentage yield is important to a chemical manufacturer.", scheme: ["More product made from the same amount of reactants", "Less waste / more profit"], answer: "A high yield means more product is made from the same amount of reactants, reducing waste and increasing profit." },
      { g: 7, marks: 2, q: "Calculate the number of molecules in 0.5 mol of a substance. (Avogadro = 6.02 × 10²³)", scheme: ["0.5 × 6.02 × 10²³", "= 3.01 × 10²³"], answer: "0.5 × 6.02 × 10²³ = 3.01 × 10²³ molecules." },
      { g: 7, marks: 2, q: "Calculate the mass of solute needed to make 200 cm³ of a solution of concentration 25 g/dm³.", scheme: ["200 cm³ = 0.2 dm³", "mass = 25 × 0.2 = 5 g"], answer: "200 cm³ = 0.2 dm³, so mass = concentration × volume = 25 × 0.2 = 5 g." },
      { g: 7, marks: 1, q: "What does 'atom economy' measure? (Higher tier)", scheme: ["The percentage of the reactant atoms that end up in the useful product"], answer: "The percentage of the reactant atoms that end up in the useful product." },
      { g: 7, marks: 2, q: "State the formula for atom economy. (Higher tier)", scheme: ["(Mr of useful product ÷ total Mr of all products/reactants) × 100"], answer: "atom economy = (Mr of the useful product ÷ total Mr of all the products) × 100." },
      { g: 7, marks: 2, q: "Calculate the number of moles in 11 g of carbon dioxide. (Mr = 44)", scheme: ["11 ÷ 44", "= 0.25 mol"], answer: "11 ÷ 44 = 0.25 mol." },
      { g: 7, marks: 3, q: "0.05 mol of zinc reacts with excess acid to give hydrogen (Zn + 2HCl → ZnCl₂ + H₂). Calculate the moles and mass of hydrogen produced. (H₂ = 2)", scheme: ["ratio Zn:H₂ = 1:1 → 0.05 mol H₂", "mass = 0.05 × 2 = 0.1 g"], answer: "The ratio Zn:H₂ is 1:1, so 0.05 mol H₂ is produced. Mass = 0.05 × 2 = 0.1 g." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 3, q: "Calculate the mass of magnesium oxide formed when 12 g of magnesium reacts completely with oxygen. (Mg = 24, MgO = 40; 2Mg + O₂ → 2MgO)", scheme: ["moles Mg = 12 ÷ 24 = 0.5 mol", "ratio 1:1 → 0.5 mol MgO", "mass = 0.5 × 40 = 20 g"], answer: "Moles Mg = 12 ÷ 24 = 0.5 mol. Ratio Mg:MgO is 1:1, so 0.5 mol MgO forms. Mass = 0.5 × 40 = 20 g." },
      { g: 8, marks: 4, q: "6 g of magnesium reacts with 6 g of oxygen (2Mg + O₂ → 2MgO). Determine the limiting reactant and the mass of MgO formed. (Mg = 24, O₂ = 32, MgO = 40)", scheme: ["moles Mg = 6 ÷ 24 = 0.25; moles O₂ = 6 ÷ 32 = 0.1875", "0.25 mol Mg needs only 0.125 mol O₂ (2Mg:1O₂)", "O₂ is in excess, Mg is limiting", "mass MgO = 0.25 × 40 = 10 g"], answer: "Moles Mg = 6 ÷ 24 = 0.25; moles O₂ = 6 ÷ 32 = 0.1875. The equation needs 2 Mg per O₂, so 0.25 mol Mg needs only 0.125 mol O₂ — oxygen is in excess and magnesium is limiting. So 0.25 mol MgO forms = 0.25 × 40 = 10 g." },
      { g: 8, marks: 3, q: "A solution contains 0.2 mol of solute in 500 cm³. Calculate its concentration in mol/dm³ and, if the Mr is 40, in g/dm³.", scheme: ["500 cm³ = 0.5 dm³; conc = 0.2 ÷ 0.5 = 0.4 mol/dm³", "in g/dm³ = 0.4 × 40 = 16 g/dm³"], answer: "500 cm³ = 0.5 dm³, so concentration = 0.2 ÷ 0.5 = 0.4 mol/dm³. In g/dm³ = 0.4 × 40 = 16 g/dm³." },
      { g: 8, marks: 3, q: "A reaction has a theoretical yield of 25 g but produces 20 g. Calculate the percentage yield and give two reasons it is below 100%.", scheme: ["(20 ÷ 25) × 100 = 80%", "Reasons (any two): reaction incomplete/reversible; product lost in transfer/filtering; side reactions"], answer: "Percentage yield = (20 ÷ 25) × 100 = 80%. It is below 100% because the reaction may be incomplete or reversible and some product is lost during transfer or purification." },
      { g: 8, marks: 4, q: "Hydrogen is made by Zn + H₂SO₄ → ZnSO₄ + H₂. Calculate the atom economy for hydrogen and explain why a high atom economy is desirable. (Mr: Zn = 65, H₂SO₄ = 98, H₂ = 2) (Higher tier)", scheme: ["total Mr of reactants = 65 + 98 = 163", "atom economy = (2 ÷ 163) × 100 = 1.2%", "High atom economy: more reactant becomes useful product → less waste, more sustainable/economical"], answer: "Atom economy = (Mr of H₂ ÷ total Mr of reactants) × 100 = (2 ÷ 163) × 100 = 1.2%. A high atom economy is desirable because more of the reactant atoms end up in the useful product, so there is less waste and the process is more sustainable and economical." },
      { g: 8, marks: 4, q: "Explain, using conservation of mass, why a metal gains mass when it burns but a metal carbonate loses mass when heated in an open crucible.", scheme: ["Mass is always conserved overall", "Burning: metal gains oxygen from the air → oxide heavier", "Heating carbonate: CO₂ gas given off and escapes → solid lighter", "Counting the gas, total mass is unchanged"], answer: "Mass is always conserved overall. When a metal burns it combines with oxygen from the air, so the oxide includes the added oxygen and weighs more. When a carbonate is heated it gives off carbon dioxide, which escapes, so the solid left weighs less — but including the escaped gas, the total mass is unchanged." },
      { g: 8, marks: 3, q: "A compound contains 4.8 g of carbon and 1.2 g of hydrogen. Calculate its empirical formula. (C = 12, H = 1)", scheme: ["moles C = 4.8 ÷ 12 = 0.4; moles H = 1.2 ÷ 1 = 1.2", "ratio C:H = 0.4 : 1.2 = 1 : 3", "empirical formula = CH₃"], answer: "Moles C = 4.8 ÷ 12 = 0.4; moles H = 1.2 ÷ 1 = 1.2. Ratio C:H = 0.4 : 1.2 = 1 : 3, so the empirical formula is CH₃." },
      { g: 8, marks: 4, q: "In a titration, 25 cm³ of sodium hydroxide is neutralised by 20 cm³ of 0.1 mol/dm³ hydrochloric acid (NaOH + HCl → NaCl + H₂O). Calculate the concentration of the NaOH. (Higher tier)", scheme: ["moles HCl = 0.1 × (20 ÷ 1000) = 0.002 mol", "ratio 1:1 → moles NaOH = 0.002", "conc NaOH = 0.002 ÷ (25 ÷ 1000) = 0.08 mol/dm³"], answer: "Moles HCl = 0.1 × (20 ÷ 1000) = 0.002 mol. The ratio is 1:1, so moles NaOH = 0.002. Concentration = 0.002 ÷ (25 ÷ 1000) = 0.08 mol/dm³." },
      { g: 8, marks: 3, q: "Calculate the number of molecules in 8.8 g of carbon dioxide. (Mr = 44, Avogadro = 6.02 × 10²³)", scheme: ["moles = 8.8 ÷ 44 = 0.2 mol", "molecules = 0.2 × 6.02 × 10²³ = 1.2 × 10²³"], answer: "Moles = 8.8 ÷ 44 = 0.2 mol. Molecules = 0.2 × 6.02 × 10²³ = 1.2 × 10²³." },
      { g: 8, marks: 3, q: "Calculate the mass of calcium oxide produced when 50 g of calcium carbonate decomposes. (CaCO₃ → CaO + CO₂; Mr CaCO₃ = 100, CaO = 56)", scheme: ["moles CaCO₃ = 50 ÷ 100 = 0.5 mol", "ratio 1:1 → 0.5 mol CaO", "mass = 0.5 × 56 = 28 g"], answer: "Moles CaCO₃ = 50 ÷ 100 = 0.5 mol. Ratio 1:1, so 0.5 mol CaO forms. Mass = 0.5 × 56 = 28 g." },
      { g: 8, marks: 3, q: "Calculate the volume of carbon dioxide (at rtp) produced when 0.25 mol of calcium carbonate decomposes. (1 mol of gas = 24 dm³ at rtp) (Higher tier)", scheme: ["ratio CaCO₃:CO₂ = 1:1 → 0.25 mol CO₂", "volume = 0.25 × 24 = 6 dm³"], answer: "0.25 mol CaCO₃ gives 0.25 mol CO₂ (1:1). Volume = 0.25 × 24 = 6 dm³." },
      { g: 8, marks: 3, q: "A student prepares copper sulfate crystals and gets a low yield. Suggest and explain three reasons for the loss of product.", scheme: ["Some product left on the filter paper / in the beaker", "Some stays dissolved in the solution", "Crystals lost during washing or drying"], answer: "The yield can be low because some product is left on the filter paper or in the beaker, some stays dissolved in the solution, and some crystals are lost during washing and drying, so not all of it is collected." },
      { g: 8, marks: 3, q: "50 cm³ of a 2 mol/dm³ solution is diluted with water to a total volume of 200 cm³. Calculate the new concentration.", scheme: ["moles = 2 × (50 ÷ 1000) = 0.1 mol", "new volume = 0.2 dm³", "conc = 0.1 ÷ 0.2 = 0.5 mol/dm³"], answer: "Moles = 2 × (50 ÷ 1000) = 0.1 mol. New concentration = 0.1 ÷ (200 ÷ 1000) = 0.5 mol/dm³." },
      { g: 8, marks: 3, q: "Compare percentage yield and atom economy as measures of how efficient a reaction is.", scheme: ["Percentage yield: how much product you actually got vs the maximum", "Atom economy: how much of the reactants become useful product (by formula)", "A reaction can have high yield but low atom economy (much waste) — both matter"], answer: "Percentage yield measures how much product you actually obtained compared with the maximum possible, while atom economy measures how much of the reactants end up in the useful product rather than waste. A reaction can have a high yield but low atom economy, so both are needed to judge efficiency." },
      { g: 8, marks: 3, q: "Explain why measuring the mass in a sealed container proves that mass is conserved even when a gas is made.", scheme: ["No gas can escape from a sealed container", "So all products (including gas) are still weighed", "The total mass stays the same → conservation of mass"], answer: "In a sealed container no gas can escape, so all the products including the gas are still there and weighed. As the total mass does not change, this shows mass is conserved." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 5, q: "5 g of calcium carbonate reacts with excess hydrochloric acid (CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂). Calculate the mass of calcium chloride formed if the yield is 90%. (Mr CaCO₃ = 100, CaCl₂ = 111)", scheme: ["moles CaCO₃ = 5 ÷ 100 = 0.05 mol", "ratio 1:1 → 0.05 mol CaCl₂", "theoretical mass = 0.05 × 111 = 5.55 g", "actual = 0.90 × 5.55 = 5.0 g"], answer: "Moles CaCO₃ = 5 ÷ 100 = 0.05 mol. Ratio 1:1 gives 0.05 mol CaCl₂, theoretical mass = 0.05 × 111 = 5.55 g. At 90% yield, actual mass = 0.90 × 5.55 = 5.0 g." },
      { g: 9, marks: 5, q: "In a titration 24.0 cm³ of 0.150 mol/dm³ sulfuric acid neutralises 25.0 cm³ of sodium hydroxide (H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O). Calculate the concentration of the NaOH, showing each step. (Higher tier)", scheme: ["moles H₂SO₄ = 0.150 × (24.0 ÷ 1000) = 0.0036 mol", "ratio acid:NaOH = 1:2 → moles NaOH = 0.0072 mol", "conc = 0.0072 ÷ (25.0 ÷ 1000) = 0.288 mol/dm³"], answer: "Moles H₂SO₄ = 0.150 × (24.0 ÷ 1000) = 0.0036 mol. The ratio of acid to NaOH is 1:2, so moles NaOH = 2 × 0.0036 = 0.0072 mol. Concentration = 0.0072 ÷ (25.0 ÷ 1000) = 0.288 mol/dm³." },
      { g: 9, marks: 6, q: "Ethanol can be made by fermentation or by the hydration of ethene. Explain how you would compare the efficiency of the two routes using atom economy and other factors. (Higher tier)", scheme: ["Hydration (C₂H₄ + H₂O → C₂H₅OH): one product → ~100% atom economy", "Fermentation makes CO₂ waste → lower atom economy", "Also consider yield, rate and cost", "Fermentation uses renewable sugar but is slow; hydration uses finite crude oil", "Weigh sustainability against speed/cost", "Justified comparison"], answer: "Hydrating ethene (C₂H₄ + H₂O → C₂H₅OH) has about 100% atom economy as there is one product, while fermentation makes carbon dioxide as waste, giving a lower atom economy. However, efficiency also depends on yield, rate and cost: fermentation uses renewable sugar but is slow, whereas hydration is fast but uses finite crude oil. Both the atom-economy and these practical factors must be weighed to compare the routes." },
      { g: 9, marks: 5, q: "A compound is 40% carbon, 6.7% hydrogen and 53.3% oxygen by mass, with Mr = 60. Determine its empirical and molecular formulae. (C = 12, H = 1, O = 16)", scheme: ["moles: C = 40/12 = 3.33; H = 6.7/1 = 6.7; O = 53.3/16 = 3.33", "ratio ≈ 1 : 2 : 1 → empirical formula CH₂O", "empirical mass = 30; 60 ÷ 30 = 2", "molecular formula = C₂H₄O₂"], answer: "Dividing each percentage by its Ar: C = 40/12 = 3.33, H = 6.7/1 = 6.7, O = 53.3/16 = 3.33, a ratio of about 1:2:1, so the empirical formula is CH₂O (mass 30). As Mr = 60, 60 ÷ 30 = 2, so the molecular formula is C₂H₄O₂." },
      { g: 9, marks: 5, q: "Explain, at the level of atoms, why total mass is unchanged in a reaction, and why in practice it can appear to increase or decrease.", scheme: ["Atoms are only rearranged (bonds break/form) — none created or destroyed", "Same atoms before and after → same total mass", "Open system, gas given off → mass appears to fall", "Open system, gas taken in (e.g. O₂) → mass appears to rise", "Sealed system → mass constant"], answer: "In a reaction bonds break and reform but the same atoms are simply rearranged, so no atoms are created or destroyed and the total mass is unchanged. In practice, in an open container mass appears to fall if a gas escapes, or to rise if a gas such as oxygen is taken in from the air; in a sealed container the mass stays constant." },
      { g: 9, marks: 5, q: "0.1 mol of magnesium reacts with excess hydrochloric acid (Mg + 2HCl → MgCl₂ + H₂). Calculate the volume of hydrogen at rtp and use conservation of mass to justify your reasoning. (1 mol gas = 24 dm³) (Higher tier)", scheme: ["ratio Mg:H₂ = 1:1 → 0.1 mol H₂", "volume = 0.1 × 24 = 2.4 dm³", "hydrogen atoms from the acid are released as H₂ gas → no atoms lost"], answer: "The ratio of Mg to H₂ is 1:1, so 0.1 mol Mg gives 0.1 mol H₂. Volume = 0.1 × 24 = 2.4 dm³. Mass is conserved because the hydrogen atoms from the acid are simply released as hydrogen gas — no atoms are created or destroyed." },
      { g: 9, marks: 5, q: "A reaction has a percentage yield of 95% but an atom economy of only 40%. Evaluate how efficient it is.", scheme: ["95% yield → little product lost in practice (good)", "40% atom economy → most reactant atoms become waste by-products", "So a lot of raw material is wasted", "Could improve by using/selling the by-products", "Conclusion: not very efficient on materials despite the high yield"], answer: "A 95% yield means very little of the possible product is lost in practice, which is good. However, an atom economy of only 40% means most of the reactant atoms end up as waste by-products, so a lot of raw material is wasted. Overall the reaction is not very efficient on materials, though finding a use for the by-products would improve this." },
      { g: 9, marks: 5, q: "8 g of methane is burned completely (CH₄ + 2O₂ → CO₂ + 2H₂O). Calculate the mass of CO₂ formed and the number of CO₂ molecules. (Mr CH₄ = 16, CO₂ = 44; Avogadro = 6.02 × 10²³)", scheme: ["moles CH₄ = 8 ÷ 16 = 0.5 mol", "ratio 1:1 → 0.5 mol CO₂; mass = 0.5 × 44 = 22 g", "molecules = 0.5 × 6.02 × 10²³ = 3.0 × 10²³"], answer: "Moles CH₄ = 8 ÷ 16 = 0.5 mol. Ratio 1:1 gives 0.5 mol CO₂, mass = 0.5 × 44 = 22 g, and molecules = 0.5 × 6.02 × 10²³ = 3.0 × 10²³." },
      { g: 9, marks: 5, q: "Explain how a manufacturer could maximise both the percentage yield and the atom economy of a process, and why both matter.", scheme: ["Yield: optimise conditions (temperature, pressure, catalyst), recycle unreacted reactants, reduce losses", "Atom economy: choose routes with fewer waste products, or find uses for by-products", "Yield = how much product; atom economy = how little waste", "Both affect profit and sustainability"], answer: "To maximise yield they can optimise the reaction conditions, use a catalyst and recycle unreacted materials while minimising losses. To maximise atom economy they can choose reaction routes that make fewer waste by-products or find uses for them. Both matter because yield sets how much product is actually made and atom economy how little material is wasted, together affecting profit and sustainability." },
      { g: 9, marks: 5, q: "50 cm³ of 0.4 mol/dm³ acid is mixed with 150 cm³ of water. Calculate the new concentration and the mass of acid present. (Mr = 36.5)", scheme: ["moles = 0.4 × (50 ÷ 1000) = 0.02 mol", "total volume = 200 cm³ = 0.2 dm³; conc = 0.02 ÷ 0.2 = 0.1 mol/dm³", "mass = 0.02 × 36.5 = 0.73 g"], answer: "Moles = 0.4 × (50 ÷ 1000) = 0.02 mol. Total volume = 200 cm³ = 0.2 dm³, so concentration = 0.02 ÷ 0.2 = 0.1 mol/dm³. Mass of acid = 0.02 × 36.5 = 0.73 g." },
      { g: 9, marks: 5, q: "Describe how you would find the percentage yield of copper sulfate crystals made from copper oxide and sulfuric acid, and identify two sources of error.", scheme: ["Work out the theoretical yield from the mass of copper oxide reacted", "Make, dry and weigh the crystals actually obtained", "% yield = (actual ÷ theoretical) × 100", "Errors: product lost on filter/in solution; crystals not fully dry"], answer: "Work out the theoretical yield from the mass of copper oxide used, then make, dry and weigh the crystals actually obtained and calculate percentage yield = (actual ÷ theoretical) × 100. Errors include losing product on the filter paper or in the solution, and weighing crystals that are not fully dry." },
      { g: 9, marks: 4, q: "24 g of magnesium is added to 100 cm³ of 1.0 mol/dm³ hydrochloric acid (Mg + 2HCl → MgCl₂ + H₂). Show by calculation which reactant is in excess. (Mg = 24)", scheme: ["moles Mg = 24 ÷ 24 = 1.0 mol", "moles HCl = 1.0 × (100 ÷ 1000) = 0.1 mol", "1 mol Mg needs 2 mol HCl but only 0.1 mol is present", "HCl is limiting; Mg is in large excess"], answer: "Moles Mg = 24 ÷ 24 = 1.0 mol; moles HCl = 1.0 × (100 ÷ 1000) = 0.1 mol. The equation needs 2 mol HCl per mol Mg, so 1 mol Mg would need 2 mol HCl but only 0.1 mol is present. So HCl is the limiting reactant and magnesium is in large excess." },
      { g: 9, marks: 4, q: "Explain why the mole is such an important concept in quantitative chemistry.", scheme: ["Lets us count particles by weighing (fixed number per mole)", "Links mass, number of particles and gas volume", "Balanced equations give mole ratios", "So reacting masses, concentrations and yields can be calculated"], answer: "The mole lets chemists count particles by weighing, since one mole always contains 6.02×10²³ particles. It links mass, number of particles and gas volume, and balanced equations give the ratio of moles reacting, so reacting masses, concentrations and yields can all be calculated — which would be impossible by counting atoms directly." },
      { g: 9, marks: 5, q: "A titration gives concordant titres of 24.10, 24.20 and 24.15 cm³ of 0.100 mol/dm³ acid to neutralise 25.0 cm³ of alkali (1:1 ratio). Calculate the concentration of the alkali using the mean. (Higher tier)", scheme: ["mean titre = (24.10 + 24.20 + 24.15) ÷ 3 = 24.15 cm³", "moles acid = 0.100 × (24.15 ÷ 1000) = 0.002415 mol", "ratio 1:1 → moles alkali = 0.002415", "conc = 0.002415 ÷ (25.0 ÷ 1000) = 0.097 mol/dm³"], answer: "Mean titre = (24.10 + 24.20 + 24.15) ÷ 3 = 24.15 cm³. Moles of acid = 0.100 × (24.15 ÷ 1000) = 0.002415 mol. As the ratio is 1:1, moles of alkali = 0.002415, so concentration = 0.002415 ÷ (25.0 ÷ 1000) = 0.097 mol/dm³." },
      { g: 9, marks: 5, q: "A company claims its new process is 'more efficient' because it has a higher percentage yield. Evaluate this claim.", scheme: ["Higher yield only shows more of the possible product is obtained", "It says nothing about waste by-products", "A lower atom economy could mean more waste overall", "Efficiency also depends on cost, energy and rate", "Conclusion: the claim is incomplete without atom economy and other data"], answer: "A higher percentage yield only shows they obtain more of the possible product, not that less material is wasted. If the new process has a lower atom economy it could still make more waste by-products, so it might not be more efficient overall. Judging efficiency also needs cost, energy use and rate, so the claim is incomplete on yield alone." },
    ],
    "4. Chemical changes": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is oxidation in terms of oxygen?", scheme: ["Gain of oxygen"], answer: "Oxidation is the gain of oxygen." },
      { g: 4, marks: 1, q: "What is reduction in terms of oxygen?", scheme: ["Loss of oxygen"], answer: "Reduction is the loss of oxygen." },
      { g: 4, marks: 1, q: "Which metal is more reactive: magnesium or copper?", scheme: ["Magnesium"], answer: "Magnesium." },
      { g: 4, marks: 2, q: "Name the two types of product formed when a metal reacts with a dilute acid.", scheme: ["A salt", "Hydrogen (gas)"], answer: "A salt and hydrogen." },
      { g: 4, marks: 2, q: "Name the three products formed when an acid reacts with a metal carbonate.", scheme: ["A salt and water", "Carbon dioxide"], answer: "A salt, water and carbon dioxide." },
      { g: 4, marks: 1, q: "What is the pH of a neutral solution?", scheme: ["pH 7"], answer: "pH 7." },
      { g: 4, marks: 1, q: "Which ion is produced by all acids in aqueous solution?", scheme: ["Hydrogen ions, H⁺"], answer: "Hydrogen ions, H⁺." },
      { g: 4, marks: 1, q: "Which ion is produced by all alkalis in aqueous solution?", scheme: ["Hydroxide ions, OH⁻"], answer: "Hydroxide ions, OH⁻." },
      { g: 4, marks: 1, q: "What type of salt is made when hydrochloric acid is neutralised?", scheme: ["A chloride"], answer: "A chloride (e.g. sodium chloride)." },
      { g: 4, marks: 1, q: "What is an electrolyte?", scheme: ["A molten or dissolved ionic compound (whose ions are free to move)"], answer: "A molten or dissolved ionic compound whose ions are free to move." },
      { g: 4, marks: 1, q: "What is the name of the negative electrode in electrolysis?", scheme: ["The cathode"], answer: "The cathode." },
      { g: 4, marks: 1, q: "Why is gold found in the Earth as the metal itself rather than as a compound?", scheme: ["It is very unreactive"], answer: "Because gold is very unreactive, so it does not form compounds easily." },
      { g: 4, marks: 1, q: "Which method is used to extract metals that are more reactive than carbon?", scheme: ["Electrolysis"], answer: "Electrolysis." },
      { g: 4, marks: 1, q: "What is an alkali?", scheme: ["A soluble base"], answer: "An alkali is a base that dissolves in water (a soluble base)." },
      { g: 4, marks: 1, q: "Which substance is formed at the cathode when molten lead bromide is electrolysed?", scheme: ["Lead"], answer: "Lead." },
      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "Write the word equation for the reaction between magnesium and hydrochloric acid.", scheme: ["magnesium + hydrochloric acid → magnesium chloride", "+ hydrogen"], answer: "magnesium + hydrochloric acid → magnesium chloride + hydrogen" },
      { g: 5, marks: 2, q: "Zinc reacts with dilute sulfuric acid to give a gas. Describe the test for this gas and the positive result.", scheme: ["Hold a lighted/burning splint at the mouth of the tube", "Burns with a squeaky pop (hydrogen)"], answer: "The gas is hydrogen: a lighted splint held at the mouth of the test tube gives a squeaky pop." },
      { g: 5, marks: 2, q: "Explain why iron can be extracted from iron oxide by heating it with carbon.", scheme: ["Carbon is more reactive than iron", "So carbon removes the oxygen from iron oxide / reduces the iron oxide"], answer: "Carbon is more reactive than iron, so it takes the oxygen from the iron oxide, reducing it to iron." },
      { g: 5, marks: 2, q: "Explain why aluminium cannot be extracted from its oxide by heating with carbon.", scheme: ["Aluminium is more reactive than carbon", "So carbon cannot remove the oxygen; electrolysis must be used instead"], answer: "Aluminium is more reactive than carbon, so carbon cannot reduce aluminium oxide; the metal must be extracted by electrolysis." },
      { g: 5, marks: 3, q: "Zinc powder is added to copper sulfate solution. State whether a reaction happens, explain why, and name the products.", scheme: ["Yes, because zinc is more reactive than copper (displaces it)", "Zinc sulfate formed", "Copper formed"], answer: "A displacement reaction happens because zinc is more reactive than copper. The products are zinc sulfate and copper." },
      { g: 5, marks: 2, q: "Copper oxide reacts with dilute sulfuric acid. Name the two products.", scheme: ["Copper sulfate", "Water"], answer: "Copper sulfate and water." },
      { g: 5, marks: 2, q: "Explain why solid sodium chloride cannot be electrolysed but molten sodium chloride can.", scheme: ["In the solid the ions are held in fixed positions / cannot move", "When molten the ions are free to move (and carry charge)"], answer: "In the solid, the ions are fixed in a lattice and cannot move. When molten, the ions are free to move to the electrodes, so it can be electrolysed." },
      { g: 5, marks: 2, q: "Sodium hydroxide solution is added gradually to hydrochloric acid until it is in excess. Describe how the pH changes.", scheme: ["pH starts below 7 and rises to 7 when neutralised", "pH rises above 7 when the alkali is in excess"], answer: "The pH starts below 7 (acidic), rises to 7 at neutralisation, then goes above 7 once excess alkali is added." },
      { g: 5, marks: 2, q: "Molten zinc chloride is electrolysed. Name the product at each electrode.", scheme: ["Zinc at the cathode (negative electrode)", "Chlorine at the anode (positive electrode)"], answer: "Zinc forms at the cathode and chlorine forms at the anode." },
      { g: 5, marks: 2, q: "Describe how universal indicator can be used to find the pH of a solution.", scheme: ["Add a few drops of universal indicator to the solution", "Compare the colour with a pH colour chart"], answer: "Add a few drops of universal indicator to the solution and compare the colour with a pH colour chart." },
      { g: 5, marks: 2, q: "Explain why cryolite is used in the extraction of aluminium.", scheme: ["It lowers the melting point of aluminium oxide", "So less energy is needed, reducing costs"], answer: "Aluminium oxide is dissolved in molten cryolite, which lowers its melting point, so less energy is needed and costs are reduced." },
      { g: 5, marks: 2, q: "Write the ionic equation for neutralisation, including state symbols.", scheme: ["H⁺ + OH⁻ → H₂O", "State symbols: H⁺(aq) + OH⁻(aq) → H₂O(l)"], answer: "H⁺(aq) + OH⁻(aq) → H₂O(l)" },
      { g: 5, marks: 2, q: "Calcium carbonate is added to hydrochloric acid. Give one observation and name the gas produced.", scheme: ["Fizzing / bubbles / the solid disappears", "Carbon dioxide"], answer: "Fizzing is seen as the solid disappears; the gas produced is carbon dioxide." },
      { g: 5, marks: 2, q: "Name an acid and an alkali that could be reacted together to make potassium nitrate.", scheme: ["Nitric acid", "Potassium hydroxide"], answer: "Nitric acid and potassium hydroxide." },
      { g: 5, marks: 2, q: "Explain why copper does not react with dilute hydrochloric acid.", scheme: ["Copper is less reactive than hydrogen", "So it cannot displace hydrogen from the acid"], answer: "Copper is below hydrogen in the reactivity series, so it cannot displace hydrogen from the acid." },
      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 4, q: "Describe how to make pure, dry crystals of copper sulfate from copper oxide and dilute sulfuric acid.", scheme: ["Warm the acid and add copper oxide until it is in excess (no more dissolves)", "Filter to remove the excess copper oxide", "Heat the filtrate to evaporate some water (to the point of crystallisation)", "Leave to cool and crystallise, then pat the crystals dry"], answer: "Warm the sulfuric acid and add copper oxide, stirring, until no more dissolves. Filter off the excess copper oxide. Gently heat the filtrate to evaporate some water, then leave it to cool so crystals form, and pat them dry with filter paper." },
      { g: 6, marks: 2, q: "Explain why hydrogen, not sodium, is produced at the cathode when sodium chloride solution is electrolysed.", scheme: ["Sodium is more reactive than hydrogen", "So hydrogen ions (from water) are discharged instead of sodium ions"], answer: "Sodium is more reactive than hydrogen, so the hydrogen ions from the water gain electrons and hydrogen is produced; sodium ions stay in solution." },
      { g: 6, marks: 2, q: "Copper sulfate solution is electrolysed using inert electrodes. Name the product at each electrode.", scheme: ["Copper at the cathode", "Oxygen at the anode"], answer: "Copper is deposited at the cathode and oxygen is given off at the anode." },
      { g: 6, marks: 2, q: "Explain why the positive electrodes must be replaced regularly in the extraction of aluminium.", scheme: ["The anodes are made of carbon (graphite) and oxygen is produced there", "The oxygen reacts with the carbon to form carbon dioxide, so the anode burns away"], answer: "Oxygen forms at the carbon anodes and reacts with the carbon to make carbon dioxide, so the anodes gradually burn away." },
      { g: 6, marks: 2, q: "Write a balanced symbol equation for the reaction of magnesium with hydrochloric acid.", scheme: ["Correct formulae: Mg, HCl, MgCl₂, H₂", "Balanced: Mg + 2HCl → MgCl₂ + H₂"], answer: "Mg + 2HCl → MgCl₂ + H₂" },
      { g: 6, marks: 2, q: "Write a balanced symbol equation for the reaction of calcium carbonate with hydrochloric acid.", scheme: ["Correct formulae: CaCO₃, HCl, CaCl₂, H₂O, CO₂", "Balanced: CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂"], answer: "CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂" },
      { g: 6, marks: 2, q: "In the reaction CuO + H₂ → Cu + H₂O, identify which substance is oxidised and which is reduced, in terms of oxygen.", scheme: ["Copper oxide is reduced because it loses oxygen", "Hydrogen is oxidised because it gains oxygen"], answer: "Copper oxide is reduced as it loses oxygen; hydrogen is oxidised as it gains oxygen to form water." },
      { g: 6, marks: 2, q: "Explain the difference between a strong acid and a weak acid.", scheme: ["A strong acid is completely/fully ionised in aqueous solution (e.g. hydrochloric acid)", "A weak acid is only partially ionised in aqueous solution (e.g. ethanoic acid)"], answer: "A strong acid, such as hydrochloric acid, is fully ionised in water; a weak acid, such as ethanoic acid, is only partially ionised." },
      { g: 6, marks: 2, q: "Explain the difference between a dilute acid and a weak acid.", scheme: ["Dilute means a small amount of acid dissolved per unit volume (low concentration)", "Weak means the acid is only partially ionised"], answer: "Dilute refers to concentration – a small amount of acid in a given volume of water. Weak refers to the acid only partially ionising in solution." },
      { g: 6, marks: 2, q: "Predict the products at each electrode when potassium bromide solution is electrolysed.", scheme: ["Hydrogen at the cathode (potassium is more reactive than hydrogen)", "Bromine at the anode (bromide is a halide ion)"], answer: "Hydrogen at the cathode, because potassium is more reactive than hydrogen; bromine at the anode, because bromide ions are halide ions." },
      { g: 6, marks: 2, q: "Name the products at each electrode when dilute sulfuric acid is electrolysed.", scheme: ["Hydrogen at the cathode", "Oxygen at the anode"], answer: "Hydrogen at the cathode and oxygen at the anode." },
      { g: 6, marks: 2, q: "Give two reasons why extracting aluminium by electrolysis is expensive.", scheme: ["Large amounts of energy are needed to melt the ore / huge amounts of electricity are used", "The carbon anodes have to be replaced regularly"], answer: "It uses a lot of energy to melt the aluminium oxide and a lot of electricity, and the carbon anodes must be replaced regularly." },
      { g: 6, marks: 3, q: "Write the word equation for the reaction between zinc carbonate and hydrochloric acid.", scheme: ["zinc carbonate + hydrochloric acid → zinc chloride", "+ water", "+ carbon dioxide"], answer: "zinc carbonate + hydrochloric acid → zinc chloride + water + carbon dioxide" },
      { g: 6, marks: 2, q: "Name all four ions present in copper chloride solution.", scheme: ["Cu²⁺ and Cl⁻ (from the copper chloride)", "H⁺ and OH⁻ (from the water)"], answer: "Copper ions (Cu²⁺) and chloride ions (Cl⁻) from the salt, plus hydrogen ions (H⁺) and hydroxide ions (OH⁻) from the water." },
      { g: 6, marks: 2, q: "An iron nail is placed in blue copper sulfate solution. Describe two observations.", scheme: ["The blue colour fades (solution turns pale green)", "A red-brown/pink coating of copper forms on the nail"], answer: "The blue solution fades to pale green as iron sulfate forms, and a red-brown coating of copper appears on the nail." },
      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "Molten lead bromide is electrolysed. Write the half equations at each electrode and state which electrode reaction is reduction.", scheme: ["Cathode: Pb²⁺ + 2e⁻ → Pb", "Anode: 2Br⁻ → Br₂ + 2e⁻", "The cathode reaction is reduction (gain of electrons)"], answer: "Cathode: Pb²⁺ + 2e⁻ → Pb (reduction, electrons gained). Anode: 2Br⁻ → Br₂ + 2e⁻ (oxidation, electrons lost)." },
      { g: 7, marks: 3, q: "Magnesium reacts with copper sulfate solution. Write the ionic equation and explain which species is oxidised and which is reduced in terms of electrons.", scheme: ["Mg + Cu²⁺ → Mg²⁺ + Cu", "Magnesium is oxidised because it loses electrons", "Copper ions are reduced because they gain electrons"], answer: "Mg + Cu²⁺ → Mg²⁺ + Cu. Magnesium atoms lose two electrons, so they are oxidised; copper ions gain two electrons, so they are reduced. (Sulfate is a spectator ion.)" },
      { g: 7, marks: 4, q: "25.00 cm³ of sodium hydroxide solution is neutralised by 20.00 cm³ of 0.100 mol/dm³ hydrochloric acid. NaOH + HCl → NaCl + H₂O. Calculate the concentration of the sodium hydroxide.", scheme: ["Moles HCl = 0.100 × 20.00/1000 = 0.00200 mol", "1:1 ratio, so moles NaOH = 0.00200 mol", "Concentration = 0.00200 ÷ 0.02500 = 0.0800", "Unit: mol/dm³"], answer: "Moles HCl = 0.100 × 0.02000 = 0.00200 mol. Ratio 1:1, so moles NaOH = 0.00200 mol. Concentration = 0.00200 ÷ 0.02500 = 0.0800 mol/dm³." },
      { g: 7, marks: 3, q: "Name the three products made in the electrolysis of brine (concentrated sodium chloride solution) and state where each is formed.", scheme: ["Hydrogen at the cathode", "Chlorine at the anode", "Sodium hydroxide left in the solution"], answer: "Hydrogen gas forms at the cathode, chlorine gas forms at the anode, and sodium hydroxide solution is left behind." },
      { g: 7, marks: 5, q: "Describe how to carry out a titration to find the volume of hydrochloric acid needed to neutralise 25.0 cm³ of sodium hydroxide solution.", scheme: ["Use a pipette to measure 25.0 cm³ of sodium hydroxide into a conical flask", "Add a few drops of indicator (e.g. phenolphthalein or methyl orange)", "Add acid from a burette while swirling the flask", "Add the acid dropwise near the end point until the indicator just changes colour; record the volume", "Repeat until concordant results (within 0.10 cm³) are obtained and calculate a mean"], answer: "Pipette 25.0 cm³ of sodium hydroxide into a conical flask and add a few drops of indicator. Fill a burette with acid and add it to the flask while swirling, adding it drop by drop near the end point until the colour just changes. Record the volume used. Repeat until you have concordant titres within 0.10 cm³ and calculate the mean." },
      { g: 7, marks: 3, q: "Sodium hydroxide solution reacts with hydrochloric acid. Name the salt formed and write the balanced symbol equation with state symbols.", scheme: ["Sodium chloride", "NaOH + HCl → NaCl + H₂O (correct and balanced)", "State symbols: (aq) + (aq) → (aq) + (l)"], answer: "The salt is sodium chloride. NaOH(aq) + HCl(aq) → NaCl(aq) + H₂O(l)" },
      { g: 7, marks: 3, q: "Explain why 0.1 mol/dm³ ethanoic acid has a higher pH than 0.1 mol/dm³ hydrochloric acid.", scheme: ["Ethanoic acid is a weak acid, so it is only partially ionised", "Hydrochloric acid is a strong acid, so it is fully ionised", "Ethanoic acid has a lower concentration of H⁺ ions, so its pH is higher"], answer: "Ethanoic acid is weak and only partially ionises, whereas hydrochloric acid is strong and fully ionises. At the same concentration, ethanoic acid releases fewer H⁺ ions, so its H⁺ concentration is lower and its pH is higher." },
      { g: 7, marks: 3, q: "Write the half equations for the electrolysis of sodium chloride solution and explain why sodium hydroxide is left in solution.", scheme: ["Cathode: 2H⁺ + 2e⁻ → H₂", "Anode: 2Cl⁻ → Cl₂ + 2e⁻", "Na⁺ and OH⁻ ions are not discharged, so they remain as sodium hydroxide"], answer: "Cathode: 2H⁺ + 2e⁻ → H₂. Anode: 2Cl⁻ → Cl₂ + 2e⁻. The Na⁺ and OH⁻ ions are not discharged, so they remain in solution as sodium hydroxide." },
      { g: 7, marks: 3, q: "Calculate the mass of sodium hydroxide needed to make 250 cm³ of a 0.200 mol/dm³ solution. (Mr of NaOH = 40)", scheme: ["Moles = 0.200 × 250/1000 = 0.0500 mol", "Mass = 0.0500 × 40 = 2.00", "Unit: g"], answer: "Moles = 0.200 × 0.250 = 0.0500 mol. Mass = 0.0500 × 40 = 2.00 g." },
      { g: 7, marks: 4, q: "Iron is extracted in the equation 2Fe₂O₃ + 3C → 4Fe + 3CO₂. State which substance is reduced and calculate the mass of iron produced from 320 g of iron(III) oxide. (Ar: Fe = 56, O = 16)", scheme: ["Iron(III) oxide is reduced because it loses oxygen", "Mr Fe₂O₃ = 160, so moles = 320 ÷ 160 = 2.0 mol", "Ratio 2:4, so moles Fe = 4.0 mol", "Mass Fe = 4.0 × 56 = 224 g"], answer: "Iron(III) oxide is reduced (it loses oxygen). Mr Fe₂O₃ = (2 × 56) + (3 × 16) = 160. Moles = 320 ÷ 160 = 2.0 mol. Ratio Fe₂O₃:Fe = 2:4, so 4.0 mol Fe. Mass = 4.0 × 56 = 224 g." },
      { g: 7, marks: 3, q: "Write the half equations at the cathode and anode in the extraction of aluminium from aluminium oxide, and explain why carbon dioxide is also produced.", scheme: ["Cathode: Al³⁺ + 3e⁻ → Al", "Anode: 2O²⁻ → O₂ + 4e⁻", "The oxygen reacts with the carbon anode to form carbon dioxide (C + O₂ → CO₂)"], answer: "Cathode: Al³⁺ + 3e⁻ → Al. Anode: 2O²⁻ → O₂ + 4e⁻. The hot oxygen reacts with the carbon anode: C + O₂ → CO₂." },
      { g: 7, marks: 4, q: "Copper sulfate solution is electrolysed with inert electrodes. Name the product at each electrode and explain why each is formed.", scheme: ["Copper forms at the cathode", "Because copper is less reactive than hydrogen, so Cu²⁺ ions are discharged", "Oxygen forms at the anode", "Because there are no halide ions, so hydroxide ions (from water) are discharged, not sulfate"], answer: "Copper forms at the cathode because copper is less reactive than hydrogen, so Cu²⁺ ions gain electrons instead of H⁺. Oxygen forms at the anode because sulfate is not a halide, so hydroxide ions from the water are discharged." },
      { g: 7, marks: 4, q: "25.0 cm³ of 0.100 mol/dm³ sulfuric acid is neutralised by 0.200 mol/dm³ sodium hydroxide. H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O. Calculate the volume of sodium hydroxide needed in cm³.", scheme: ["Moles H₂SO₄ = 0.100 × 0.0250 = 0.00250 mol", "Moles NaOH = 2 × 0.00250 = 0.00500 mol", "Volume = 0.00500 ÷ 0.200 = 0.0250 dm³", "= 25.0 cm³"], answer: "Moles H₂SO₄ = 0.100 × 0.0250 = 0.00250 mol. Ratio 1:2, so moles NaOH = 0.00500 mol. Volume = 0.00500 ÷ 0.200 = 0.0250 dm³ = 25.0 cm³." },
      { g: 7, marks: 3, q: "Metal X displaces metal Z from a solution of Z sulfate. Metal Z displaces metal Y from Y sulfate but does not react with X sulfate. Deduce the order of reactivity of X, Y and Z, with reasons.", scheme: ["X is more reactive than Z (X displaces Z; Z cannot displace X)", "Z is more reactive than Y (Z displaces Y)", "Order (most to least reactive): X, Z, Y"], answer: "X displaces Z, and Z cannot displace X, so X is more reactive than Z. Z displaces Y, so Z is more reactive than Y. Order: X > Z > Y." },
      { g: 7, marks: 3, q: "Write the ionic equation for the reaction between hydrochloric acid and sodium carbonate solution, and explain why sodium and chloride ions are not included.", scheme: ["2H⁺ + CO₃²⁻ → H₂O + CO₂ (correct species)", "Correctly balanced with 2H⁺", "Na⁺ and Cl⁻ are spectator ions – they do not change in the reaction"], answer: "2H⁺(aq) + CO₃²⁻(aq) → H₂O(l) + CO₂(g). Sodium and chloride ions are spectator ions: they remain unchanged in solution, so they are left out." },
      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 5, q: "25.0 cm³ of 0.100 mol/dm³ sodium hydroxide is titrated with hydrochloric acid. The titres were 24.60, 23.10, 23.20 and 23.15 cm³ (the first was a rough titration). Calculate the mean titre from the concordant results and the concentration of the acid. NaOH + HCl → NaCl + H₂O", scheme: ["Ignore the rough 24.60 cm³; concordant results are 23.10, 23.20 and 23.15", "Mean titre = 69.45 ÷ 3 = 23.15 cm³", "Moles NaOH = 0.100 × 0.0250 = 0.00250 mol (= moles HCl, 1:1)", "Concentration = 0.00250 ÷ 0.02315 = 0.108", "Unit: mol/dm³"], answer: "The rough 24.60 cm³ is ignored. Mean = (23.10 + 23.20 + 23.15) ÷ 3 = 23.15 cm³. Moles NaOH = 0.100 × 0.0250 = 0.00250 mol = moles HCl. Concentration = 0.00250 ÷ 0.02315 = 0.108 mol/dm³ (3 s.f.)." },
      { g: 8, marks: 5, q: "25.0 cm³ of sulfuric acid is neutralised by 20.0 cm³ of 0.150 mol/dm³ potassium hydroxide. H₂SO₄ + 2KOH → K₂SO₄ + 2H₂O. Calculate the concentration of the acid in mol/dm³ and in g/dm³. (Mr of H₂SO₄ = 98)", scheme: ["Moles KOH = 0.150 × 0.0200 = 0.00300 mol", "Moles H₂SO₄ = 0.00300 ÷ 2 = 0.00150 mol", "Concentration = 0.00150 ÷ 0.0250 = 0.0600 mol/dm³", "Mass concentration = 0.0600 × 98 = 5.88", "Unit: g/dm³"], answer: "Moles KOH = 0.150 × 0.0200 = 0.00300 mol. Ratio 1:2, so moles H₂SO₄ = 0.00150 mol. Concentration = 0.00150 ÷ 0.0250 = 0.0600 mol/dm³. In g/dm³: 0.0600 × 98 = 5.88 g/dm³." },
      { g: 8, marks: 3, q: "Solution A has pH 3 and solution B has pH 5. Compare the concentrations of hydrogen ions in the two solutions.", scheme: ["Solution A (lower pH) has the higher H⁺ concentration", "Each decrease of 1 pH unit means a 10 times greater H⁺ concentration", "2 units difference, so A has 10 × 10 = 100 times the H⁺ concentration of B"], answer: "A has the higher H⁺ concentration. Each 1 unit drop in pH is a tenfold increase in H⁺, and the difference is 2 units, so A has 10² = 100 times the hydrogen ion concentration of B." },
      { g: 8, marks: 4, q: "Iron reacts with copper sulfate solution to form iron(II) sulfate and copper. Use half equations to explain why this is a redox reaction.", scheme: ["Fe → Fe²⁺ + 2e⁻", "Iron loses electrons, so it is oxidised", "Cu²⁺ + 2e⁻ → Cu", "Copper ions gain electrons, so they are reduced; oxidation and reduction happen together (redox)"], answer: "Fe → Fe²⁺ + 2e⁻: iron atoms lose electrons and are oxidised. Cu²⁺ + 2e⁻ → Cu: copper ions gain electrons and are reduced. Because oxidation and reduction occur at the same time, it is a redox reaction." },
      { g: 8, marks: 4, q: "Sodium sulfate solution is electrolysed with inert electrodes. Explain the product at each electrode and write the half equation for each.", scheme: ["Hydrogen at the cathode, because sodium is more reactive than hydrogen", "2H⁺ + 2e⁻ → H₂", "Oxygen at the anode, because no halide ions are present (hydroxide ions discharged)", "4OH⁻ → O₂ + 2H₂O + 4e⁻"], answer: "Cathode: sodium is more reactive than hydrogen, so hydrogen forms: 2H⁺ + 2e⁻ → H₂. Anode: there are no halide ions, so hydroxide ions are discharged and oxygen forms: 4OH⁻ → O₂ + 2H₂O + 4e⁻." },
      { g: 8, marks: 3, q: "During the electrolysis of brine, the solution around the cathode becomes alkaline. Explain why.", scheme: ["Hydrogen ions (from water) are discharged at the cathode to form hydrogen gas", "Hydroxide ions are left behind in the solution", "Together with sodium ions they form sodium hydroxide, so the OH⁻ concentration increases"], answer: "H⁺ ions from the water gain electrons at the cathode and leave as hydrogen gas. The OH⁻ ions are left in solution with the Na⁺ ions, forming sodium hydroxide, so the solution becomes alkaline." },
      { g: 8, marks: 4, q: "Aluminium is extracted using the overall equation 2Al₂O₃ → 4Al + 3O₂. Calculate the mass of aluminium produced from 51 tonnes of aluminium oxide. (Ar: Al = 27, O = 16)", scheme: ["Mr Al₂O₃ = (2 × 27) + (3 × 16) = 102", "2 × 102 = 204 of Al₂O₃ gives 4 × 27 = 108 of Al", "51 × 108 ÷ 204 = 27", "Unit: tonnes"], answer: "Mr Al₂O₃ = 102. From the equation, 204 tonnes of Al₂O₃ gives 108 tonnes of Al. So 51 tonnes gives 51 × 108 ÷ 204 = 27 tonnes of aluminium." },
      { g: 8, marks: 3, q: "A student says: 'A strong acid always has a lower pH than a weak acid.' Explain why this is not necessarily true.", scheme: ["Strength refers to how fully the acid ionises, not how much acid is present", "pH depends on the concentration of H⁺ ions, which depends on both strength and concentration", "A very dilute strong acid could have a lower H⁺ concentration (higher pH) than a concentrated weak acid"], answer: "Strength describes the degree of ionisation, but pH depends on the H⁺ concentration, which also depends on how concentrated the acid is. A very dilute strong acid can contain fewer H⁺ ions per dm³ than a concentrated weak acid, so it could have a higher pH." },
      { g: 8, marks: 3, q: "Potassium is more reactive than copper, but it is not used to displace copper from copper sulfate solution. Explain why.", scheme: ["Potassium reacts with the water in the solution", "Violently, producing hydrogen (and potassium hydroxide) – dangerous", "So it does not simply displace copper from the solution"], answer: "Potassium reacts violently with the water in the solution, giving off hydrogen and forming potassium hydroxide. This is dangerous, and the potassium reacts with the water rather than cleanly displacing the copper." },
      { g: 8, marks: 3, q: "Calculate the number of moles of electrons needed to produce 54 g of aluminium at the cathode. (Ar: Al = 27)", scheme: ["Half equation: Al³⁺ + 3e⁻ → Al", "Moles Al = 54 ÷ 27 = 2.0 mol", "Moles electrons = 3 × 2.0 = 6.0 mol"], answer: "Al³⁺ + 3e⁻ → Al. Moles Al = 54 ÷ 27 = 2.0 mol. Each mole needs 3 moles of electrons, so 6.0 mol of electrons." },
      { g: 8, marks: 4, q: "Compare the products formed when molten potassium iodide and potassium iodide solution are each electrolysed.", scheme: ["Molten: potassium at the cathode", "Molten: iodine at the anode", "Solution: hydrogen at the cathode, because potassium is more reactive than hydrogen", "Solution: iodine at the anode, because iodide is a halide ion"], answer: "Molten KI gives potassium at the cathode and iodine at the anode. In solution, hydrogen forms at the cathode instead, because potassium is more reactive than hydrogen, while iodine still forms at the anode because iodide is a halide." },
      { g: 8, marks: 5, q: "Plan an investigation to place magnesium, zinc, iron and copper in order of reactivity by measuring the temperature change when each reacts with dilute hydrochloric acid.", scheme: ["Measure the same volume and concentration of acid into an insulated (polystyrene) cup", "Record the starting temperature with a thermometer", "Add the same mass of each metal (same particle size, e.g. powder) and stir", "Record the highest temperature reached and calculate the temperature rise", "Repeat for each metal; the larger the temperature rise, the more reactive the metal"], answer: "Put the same volume of the same concentration of hydrochloric acid in a polystyrene cup and record its temperature. Add a fixed mass of metal powder, stir and record the maximum temperature. Calculate the rise. Repeat with each metal, keeping all other variables the same; a bigger temperature rise shows a more reactive metal." },
      { g: 8, marks: 4, q: "Write the ionic equation for the reaction of magnesium with hydrochloric acid and explain the reaction in terms of oxidation and reduction.", scheme: ["Mg + 2H⁺ → Mg²⁺ + H₂", "Magnesium loses electrons, so it is oxidised", "Hydrogen ions gain electrons, so they are reduced", "Chloride ions are spectator ions (unchanged)"], answer: "Mg + 2H⁺ → Mg²⁺ + H₂. Magnesium atoms lose two electrons and are oxidised; hydrogen ions gain electrons and are reduced to hydrogen gas. Chloride ions are spectator ions." },
      { g: 8, marks: 4, q: "Calculate the volume of 0.250 mol/dm³ nitric acid needed to neutralise 1.00 g of sodium hydroxide. NaOH + HNO₃ → NaNO₃ + H₂O (Mr of NaOH = 40)", scheme: ["Moles NaOH = 1.00 ÷ 40 = 0.0250 mol", "1:1 ratio, so moles HNO₃ = 0.0250 mol", "Volume = 0.0250 ÷ 0.250 = 0.100 dm³", "= 100 cm³"], answer: "Moles NaOH = 1.00 ÷ 40 = 0.0250 mol = moles HNO₃. Volume = 0.0250 ÷ 0.250 = 0.100 dm³ = 100 cm³." },
      { g: 8, marks: 4, q: "Zinc oxide can be reduced by heating with carbon, forming zinc and carbon dioxide, but magnesium oxide cannot. Explain why, and write a balanced symbol equation for the reduction of zinc oxide.", scheme: ["Carbon is more reactive than zinc, so it can remove the oxygen from zinc oxide", "Magnesium is more reactive than carbon, so carbon cannot reduce magnesium oxide", "Correct formulae: ZnO, C, Zn, CO₂", "Balanced: 2ZnO + C → 2Zn + CO₂"], answer: "Carbon is above zinc in the reactivity series, so it takes the oxygen from zinc oxide; magnesium is above carbon, so carbon cannot reduce magnesium oxide. 2ZnO + C → 2Zn + CO₂" },
      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 5, q: "Aluminium is more abundant in the Earth's crust than iron, yet aluminium metal is more expensive. Explain why.", scheme: ["Aluminium is more reactive than carbon, so it must be extracted by electrolysis", "Electrolysis uses very large amounts of electricity", "Aluminium oxide has a very high melting point, so a lot of energy is needed to melt it (even when dissolved in cryolite)", "The carbon anodes burn away and must be replaced regularly", "Iron is less reactive than carbon, so it can be extracted cheaply by reduction with carbon"], answer: "Aluminium is more reactive than carbon, so it cannot be extracted by carbon reduction and must be extracted by electrolysis. This uses huge amounts of electricity, and a lot of energy is needed to keep the aluminium oxide molten, even with cryolite. The carbon anodes also burn away and must be replaced. Iron is less reactive than carbon, so it can be extracted cheaply by heating with carbon. So despite being more abundant, aluminium costs more to produce." },
      { g: 9, marks: 5, q: "25.0 cm³ of sodium carbonate solution reacts exactly with 18.75 cm³ of 0.120 mol/dm³ sulfuric acid. Na₂CO₃ + H₂SO₄ → Na₂SO₄ + H₂O + CO₂. Calculate the concentration of the sodium carbonate solution in g/dm³. (Mr of Na₂CO₃ = 106)", scheme: ["Moles H₂SO₄ = 0.120 × 0.01875 = 0.00225 mol", "1:1 ratio, so moles Na₂CO₃ = 0.00225 mol", "Concentration = 0.00225 ÷ 0.0250 = 0.0900 mol/dm³", "Mass concentration = 0.0900 × 106 = 9.54", "Unit: g/dm³"], answer: "Moles H₂SO₄ = 0.120 × 0.01875 = 0.00225 mol. Ratio 1:1, so moles Na₂CO₃ = 0.00225 mol. Concentration = 0.00225 ÷ 0.0250 = 0.0900 mol/dm³. Mass concentration = 0.0900 × 106 = 9.54 g/dm³." },
      { g: 9, marks: 6, q: "2.00 g of impure sodium hydroxide is dissolved in water to make 250 cm³ of solution. 25.0 cm³ of this solution is neutralised by 22.50 cm³ of 0.200 mol/dm³ hydrochloric acid. NaOH + HCl → NaCl + H₂O. Calculate the percentage purity of the sodium hydroxide. (Mr of NaOH = 40)", scheme: ["Moles HCl = 0.200 × 0.02250 = 0.00450 mol", "1:1 ratio, so moles NaOH in 25.0 cm³ = 0.00450 mol", "Moles NaOH in 250 cm³ = 0.00450 × 10 = 0.0450 mol", "Mass NaOH = 0.0450 × 40 = 1.80 g", "Purity = 1.80 ÷ 2.00 × 100 = 90.0", "Unit: %"], answer: "Moles HCl = 0.200 × 0.02250 = 0.00450 mol, so 0.00450 mol NaOH in 25.0 cm³. In 250 cm³: 0.00450 × 10 = 0.0450 mol. Mass = 0.0450 × 40 = 1.80 g. Percentage purity = 1.80 ÷ 2.00 × 100 = 90.0%." },
      { g: 9, marks: 5, q: "Ethanoic acid ionises as CH₃COOH ⇌ CH₃COO⁻ + H⁺. Using this, explain why ethanoic acid is a weak acid, and compare its reaction with magnesium ribbon to that of hydrochloric acid of the same concentration and volume.", scheme: ["The reaction is reversible, so ethanoic acid is only partially ionised (weak acid)", "So it has a lower concentration of H⁺ ions than hydrochloric acid, and a higher pH", "Fewer H⁺ ions means less frequent collisions with magnesium", "So ethanoic acid fizzes less / reacts more slowly", "Both contain the same amount of acid, so the same total volume of hydrogen is eventually made (with excess magnesium)"], answer: "The ⇌ shows the ionisation is reversible, so only some ethanoic acid molecules release H⁺ – it is a weak acid. At the same concentration it has a lower H⁺ concentration and higher pH than hydrochloric acid, which is fully ionised. With fewer H⁺ ions, collisions with magnesium are less frequent, so it reacts more slowly with less fizzing. However, both contain the same number of moles of acid, so with excess magnesium they eventually produce the same volume of hydrogen." },
      { g: 9, marks: 6, q: "Explain fully the electrolysis of brine, including half equations, why each product forms, and why the products must be kept apart.", scheme: ["Cathode: 2H⁺ + 2e⁻ → H₂", "Hydrogen forms because sodium is more reactive than hydrogen", "Anode: 2Cl⁻ → Cl₂ + 2e⁻", "Chlorine forms because chloride is a halide ion, discharged in preference to hydroxide", "Na⁺ and OH⁻ remain in solution, forming sodium hydroxide", "Products kept apart because chlorine reacts with sodium hydroxide / hydrogen and chlorine can react explosively"], answer: "At the cathode, sodium is more reactive than hydrogen, so H⁺ ions from water are discharged: 2H⁺ + 2e⁻ → H₂. At the anode, chloride ions are halides and are discharged instead of hydroxide ions: 2Cl⁻ → Cl₂ + 2e⁻. The Na⁺ and OH⁻ ions remain, forming sodium hydroxide solution. The products are kept apart because chlorine reacts with sodium hydroxide (forming bleach) and a hydrogen–chlorine mixture can explode." },
      { g: 9, marks: 5, q: "In the thermite reaction, 2Al + Fe₂O₃ → Al₂O₃ + 2Fe. Explain why the reaction happens and, using half equations, identify what is oxidised and what is reduced.", scheme: ["Aluminium is more reactive than iron, so it displaces iron from its oxide", "Al → Al³⁺ + 3e⁻", "Aluminium loses electrons (and gains oxygen), so it is oxidised", "Fe³⁺ + 3e⁻ → Fe", "Iron(III) ions gain electrons (iron oxide loses oxygen), so they are reduced"], answer: "Aluminium is more reactive than iron, so it takes the oxygen from iron(III) oxide. Al → Al³⁺ + 3e⁻: aluminium loses electrons and gains oxygen, so it is oxidised. Fe³⁺ + 3e⁻ → Fe: iron ions gain electrons as iron oxide loses oxygen, so they are reduced. Both happen together, so it is a redox reaction." },
      { g: 9, marks: 4, q: "10.0 cm³ of hydrochloric acid with pH 1.0 is diluted with water to a total volume of 1.00 dm³. Calculate the new pH, showing your reasoning.", scheme: ["Volume increases from 10.0 cm³ to 1000 cm³, a factor of 100", "So the H⁺ concentration decreases by a factor of 100", "Each tenfold decrease in H⁺ concentration increases pH by 1, so pH rises by 2", "New pH = 3.0"], answer: "1.00 dm³ = 1000 cm³, so the acid is diluted 1000 ÷ 10.0 = 100 times and the H⁺ concentration falls by a factor of 100 = 10². Each factor of 10 raises the pH by 1, so the pH rises by 2: new pH = 1.0 + 2 = 3.0." },
      { g: 9, marks: 5, q: "A student electrolyses copper chloride solution with inert electrodes and claims the gas at the anode is oxygen. Evaluate this claim, including a half equation, a test for the gas and the product at the cathode.", scheme: ["The claim is wrong: the gas is chlorine", "Chloride ions are halide ions, so they are discharged in preference to hydroxide ions", "2Cl⁻ → Cl₂ + 2e⁻", "Test: damp (blue) litmus paper is bleached white", "Copper forms at the cathode because copper is less reactive than hydrogen"], answer: "The student is wrong – the gas is chlorine, because chloride is a halide and is discharged in preference to hydroxide: 2Cl⁻ → Cl₂ + 2e⁻. This can be shown with damp blue litmus paper, which is bleached white. At the cathode copper forms, since copper is less reactive than hydrogen." },
      { g: 9, marks: 6, q: "Describe how to make pure, dry crystals of sodium sulfate from sodium hydroxide solution and dilute sulfuric acid, and explain why the excess-base method used for copper sulfate cannot be used.", scheme: ["Pipette 25.0 cm³ of sodium hydroxide into a conical flask and add a few drops of indicator", "Add sulfuric acid from a burette until the indicator changes colour; record the volume", "Repeat using the same volumes but without indicator (so the salt is not contaminated)", "Heat the solution to evaporate some of the water", "Leave to cool and crystallise, then filter and dry the crystals", "Sodium hydroxide is soluble, so any excess could not be filtered off"], answer: "Titrate: pipette 25.0 cm³ of NaOH into a flask with indicator and add acid from a burette until the colour changes, recording the volume. Repeat with the same volumes but no indicator, so the salt is pure. Evaporate some water by heating, leave to cool and crystallise, then filter and dry the crystals. The excess-base method cannot be used because sodium hydroxide is soluble, so an excess could not be removed by filtering." },
      { g: 9, marks: 5, q: "In aluminium extraction, 2Al₂O₃ → 4Al + 3O₂, and all the oxygen reacts with the carbon anodes: C + O₂ → CO₂. Calculate the mass of carbon anode used up when 108 kg of aluminium is produced. (Ar: Al = 27, C = 12)", scheme: ["Moles Al = 108 000 ÷ 27 = 4000 mol", "Ratio Al:O₂ = 4:3, so moles O₂ = 3000 mol", "Ratio O₂:C = 1:1, so moles C = 3000 mol", "Mass C = 3000 × 12 = 36 000 g", "= 36 kg"], answer: "Moles Al = 108 000 g ÷ 27 = 4000 mol. From 4Al:3O₂, moles O₂ = 3000 mol. From C + O₂ → CO₂, moles C = 3000 mol. Mass = 3000 × 12 = 36 000 g = 36 kg." },
      { g: 9, marks: 5, q: "A metal M forms M²⁺ ions. 0.60 g of M reacts with excess hydrochloric acid, producing 0.025 mol of hydrogen gas. Identify M from magnesium (Ar 24), calcium (Ar 40) and zinc (Ar 65), and write the ionic equation.", scheme: ["M + 2HCl → MCl₂ + H₂, so the ratio M:H₂ is 1:1", "Moles M = 0.025 mol", "Ar = 0.60 ÷ 0.025 = 24", "M is magnesium", "Mg + 2H⁺ → Mg²⁺ + H₂"], answer: "M + 2HCl → MCl₂ + H₂, so 1 mol M gives 1 mol H₂, meaning 0.025 mol of M reacted. Ar = 0.60 ÷ 0.025 = 24, so M is magnesium. Ionic equation: Mg + 2H⁺ → Mg²⁺ + H₂." },
      { g: 9, marks: 5, q: "A student has two unlabelled acids of the same concentration: one strong and one weak. Evaluate using a pH probe, universal indicator and reaction with magnesium to identify them.", scheme: ["The strong acid is fully ionised, so it has a higher H⁺ concentration and lower pH", "A pH probe gives a precise numerical pH, so the lower reading identifies the strong acid", "Universal indicator relies on judging colours and is less precise, so similar colours may be hard to tell apart", "With the same mass of magnesium, the strong acid fizzes faster because more H⁺ ions give more frequent collisions (control volume and temperature)", "Conclusion: the pH probe is the most reliable method, with the magnesium test as supporting evidence"], answer: "The strong acid is fully ionised, so it has more H⁺ ions and a lower pH. A pH probe measures pH precisely, so the lower reading clearly shows the strong acid. Universal indicator depends on judging colour, which is subjective and less precise. Adding equal masses of magnesium to equal volumes at the same temperature, the strong acid fizzes faster because more frequent collisions occur with H⁺ ions, but this is qualitative. Overall, the pH probe is the best method, supported by the magnesium test." },
      { g: 9, marks: 4, q: "When dilute sulfuric acid is electrolysed, the volume of hydrogen collected is twice the volume of oxygen. Use half equations to explain why.", scheme: ["Cathode: 2H⁺ + 2e⁻ → H₂", "Anode: 4OH⁻ → O₂ + 2H₂O + 4e⁻", "The same number of electrons flows through each electrode", "4 electrons produce 2 mol H₂ but only 1 mol O₂, and equal moles of gas occupy equal volumes, giving a 2:1 ratio"], answer: "Cathode: 2H⁺ + 2e⁻ → H₂. Anode: 4OH⁻ → O₂ + 2H₂O + 4e⁻. The same number of electrons passes through both electrodes. Transferring 4 electrons makes 2 molecules of H₂ but only 1 of O₂, and equal amounts of gas take up equal volumes, so twice as much hydrogen is collected." },
      { g: 9, marks: 5, q: "Using ideas about electrons, explain why magnesium displaces zinc from zinc sulfate solution but copper does not. Include an ionic equation.", scheme: ["A metal's reactivity depends on its tendency to lose electrons and form positive ions", "Magnesium loses electrons more readily than zinc, so it displaces zinc", "Mg + Zn²⁺ → Mg²⁺ + Zn", "Magnesium is oxidised (loses electrons) and zinc ions are reduced (gain electrons)", "Copper has less tendency to form ions than zinc, so it cannot give electrons to Zn²⁺ – no reaction"], answer: "Reactivity depends on how easily a metal loses electrons to form positive ions. Magnesium does this more readily than zinc, so it gives electrons to zinc ions: Mg + Zn²⁺ → Mg²⁺ + Zn. Magnesium is oxidised and zinc ions are reduced. Copper forms ions less readily than zinc, so it cannot reduce Zn²⁺ and no reaction occurs." },
      { g: 9, marks: 5, q: "Explain why sodium metal is manufactured by electrolysing molten sodium chloride rather than sodium chloride solution. Include half equations and one reason the process is expensive.", scheme: ["In solution, sodium is more reactive than hydrogen, so hydrogen would form at the cathode instead of sodium", "When molten there is no water, so Na⁺ are the only positive ions and are discharged", "Cathode: Na⁺ + e⁻ → Na", "Anode: 2Cl⁻ → Cl₂ + 2e⁻", "Expensive because a lot of energy is needed to melt sodium chloride (high melting point) and a lot of electricity is used"], answer: "In solution, hydrogen ions from water are discharged instead of sodium ions because sodium is more reactive than hydrogen, so no sodium forms. Molten sodium chloride contains no water, so Na⁺ ions are discharged: Na⁺ + e⁻ → Na, while at the anode 2Cl⁻ → Cl₂ + 2e⁻. The process is expensive because sodium chloride has a high melting point, so a lot of energy is needed to melt it, plus large amounts of electricity." },
    ],
    "5. Energy changes": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is an exothermic reaction?", scheme: ["A reaction that transfers energy to the surroundings (so the temperature of the surroundings increases)"], answer: "A reaction that transfers energy to the surroundings, so the temperature of the surroundings increases." },
      { g: 4, marks: 1, q: "What is an endothermic reaction?", scheme: ["A reaction that takes in energy from the surroundings (so the temperature of the surroundings decreases)"], answer: "A reaction that takes in energy from the surroundings, so the temperature of the surroundings decreases." },
      { g: 4, marks: 1, q: "State whether neutralisation reactions are exothermic or endothermic.", scheme: ["Exothermic"], answer: "Exothermic." },
      { g: 4, marks: 2, q: "Give two examples of exothermic reactions, other than neutralisation.", scheme: ["Combustion (burning fuels)", "Oxidation (e.g. respiration or rusting)"], answer: "Combustion of fuels and oxidation reactions such as rusting." },
      { g: 4, marks: 1, q: "Give one example of an endothermic reaction.", scheme: ["Thermal decomposition / citric acid reacting with sodium hydrogencarbonate"], answer: "Thermal decomposition, e.g. of calcium carbonate (or citric acid reacting with sodium hydrogencarbonate)." },
      { g: 4, marks: 1, q: "Give one everyday use of an exothermic reaction.", scheme: ["Hand warmers / self-heating cans"], answer: "Hand warmers (or self-heating cans)." },
      { g: 4, marks: 1, q: "Give one everyday use of an endothermic reaction.", scheme: ["Sports injury (instant cold) packs"], answer: "Sports injury cold packs." },
      { g: 4, marks: 1, q: "What is activation energy?", scheme: ["The minimum amount of energy that particles must have to react"], answer: "The minimum amount of energy that particles must have when they collide in order to react." },
      { g: 4, marks: 1, q: "State the units used for bond energies and energy changes of reactions.", scheme: ["kJ/mol (kilojoules per mole)"], answer: "kJ/mol (kilojoules per mole)." },
      { g: 4, marks: 1, q: "Name the piece of equipment used to measure the temperature change of a reacting solution.", scheme: ["Thermometer (or temperature probe)"], answer: "A thermometer (or a temperature probe)." },
      { g: 4, marks: 1, q: "Why is a polystyrene cup used to hold the reaction mixture when measuring temperature changes?", scheme: ["It is a good insulator, so it reduces energy transfer to or from the surroundings"], answer: "Polystyrene is a good thermal insulator, so it reduces energy transfer between the mixture and the surroundings." },
      { g: 4, marks: 1, q: "What is a simple chemical cell made from?", scheme: ["Two different metals (electrodes) in contact with an electrolyte"], answer: "Two different metals (electrodes) in contact with an electrolyte." },
      { g: 4, marks: 1, q: "What is a battery?", scheme: ["Two or more cells connected together in series"], answer: "Two or more cells connected together in series to give a greater voltage." },
      { g: 4, marks: 1, q: "What is the only waste product of a hydrogen fuel cell?", scheme: ["Water"], answer: "Water." },
      { g: 4, marks: 1, q: "Why do non-rechargeable cells, such as alkaline batteries, eventually stop working?", scheme: ["One of the reactants is used up (the reaction cannot be reversed)"], answer: "One of the reactants is used up, and the reaction cannot be reversed." },
      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "Describe, in words, the reaction profile for an exothermic reaction.", scheme: ["The products are at a lower energy level than the reactants", "The difference is the energy released to the surroundings (the curve rises to a peak first because of the activation energy)"], answer: "The products are lower in energy than the reactants; the curve first rises to a peak (activation energy) and the drop from reactants to products is the energy released to the surroundings." },
      { g: 5, marks: 2, q: "Describe, in words, the reaction profile for an endothermic reaction.", scheme: ["The products are at a higher energy level than the reactants", "The difference is the energy taken in from the surroundings (the curve rises to a peak first because of the activation energy)"], answer: "The products are higher in energy than the reactants; the curve rises to a peak (activation energy) and the rise from reactants to products is the energy taken in from the surroundings." },
      { g: 5, marks: 2, q: "When two solutions are mixed, the temperature falls from 20.0 °C to 14.5 °C. Calculate the temperature change and state the type of reaction.", scheme: ["Temperature change = 20.0 − 14.5 = 5.5 °C decrease (−5.5 °C)", "Endothermic"], answer: "20.0 − 14.5 = 5.5 °C decrease. The temperature fell, so the reaction is endothermic." },
      { g: 5, marks: 2, q: "Suggest why a student uses a thermometer that reads to 0.1 °C rather than to 1 °C when measuring temperature changes.", scheme: ["It has a higher resolution", "So small temperature changes can be measured more precisely/accurately"], answer: "It has a higher resolution, so small temperature changes can be measured more precisely." },
      { g: 5, marks: 2, q: "Explain how a self-heating can warms its contents.", scheme: ["Chemicals in the can react in an exothermic reaction (e.g. calcium oxide and water)", "Energy is transferred to the surroundings / the food or drink, raising its temperature"], answer: "When activated, chemicals in the base (e.g. calcium oxide and water) react exothermically, transferring energy to the food or drink so its temperature rises." },
      { g: 5, marks: 2, q: "Explain why an instant cold pack feels cold when it is activated.", scheme: ["The chemicals inside undergo an endothermic reaction/process", "Energy is taken in from the surroundings (the injured skin), so the temperature falls"], answer: "The chemicals undergo an endothermic process that takes in energy from the surroundings, including the skin, so the temperature falls." },
      { g: 5, marks: 2, q: "Explain why a lid is placed on the polystyrene cup when investigating the temperature change of a reaction.", scheme: ["Reduces energy (heat) loss to the surroundings (e.g. by evaporation/convection)", "So the measured temperature change is more accurate"], answer: "A lid reduces energy transfer to the surroundings, so the measured temperature change is closer to the true value." },
      { g: 5, marks: 2, q: "State two factors that affect the voltage produced by a simple chemical cell.", scheme: ["The type of metals used as electrodes (their difference in reactivity)", "The electrolyte used"], answer: "The type of metals used for the electrodes (the bigger the difference in reactivity, the bigger the voltage) and the electrolyte used." },
      { g: 5, marks: 2, q: "Explain why rechargeable cells and batteries can be recharged.", scheme: ["The chemical reactions are reversed", "When an external electrical current is supplied"], answer: "When an external electrical current is supplied, the chemical reactions are reversed, so the reactants are re-formed." },
      { g: 5, marks: 2, q: "What is a fuel cell?", scheme: ["A cell supplied by an external source of fuel (e.g. hydrogen) and oxygen/air", "The fuel is oxidised electrochemically to produce a potential difference (voltage)"], answer: "A cell that is supplied with a fuel such as hydrogen and oxygen from air; the fuel is oxidised electrochemically to produce a potential difference." },
      { g: 5, marks: 2, q: "Name the two reactants used in a hydrogen fuel cell and write the word equation for the overall reaction.", scheme: ["Hydrogen and oxygen", "hydrogen + oxygen → water"], answer: "Hydrogen and oxygen: hydrogen + oxygen → water." },
      { g: 5, marks: 2, q: "On a reaction profile, how are the activation energy and the overall energy change shown?", scheme: ["Activation energy: the energy difference from the reactants up to the peak of the curve", "Overall energy change: the energy difference between the reactants and the products"], answer: "The activation energy is the rise from the reactants to the top of the curve; the overall energy change is the difference in energy between the reactants and the products." },
      { g: 5, marks: 2, q: "Calcium carbonate only breaks down while it is being heated strongly. Is this reaction exothermic or endothermic? Explain your answer.", scheme: ["Endothermic", "Energy must be continuously taken in (supplied by heating) for the reaction to happen"], answer: "Endothermic — thermal decomposition takes in energy, so it must be continuously heated for the reaction to continue." },
      { g: 5, marks: 2, q: "State whether breaking bonds and making bonds are exothermic or endothermic processes.", scheme: ["Breaking bonds is endothermic (energy is taken in)", "Making bonds is exothermic (energy is released)"], answer: "Breaking bonds is endothermic because energy is needed; making bonds is exothermic because energy is released." },
      { g: 5, marks: 2, q: "Describe how energy is conserved when an exothermic reaction takes place.", scheme: ["Energy is transferred from the reacting chemicals (the products store less energy than the reactants) to the surroundings", "The total amount of energy stays the same — energy gained by the surroundings equals energy lost by the chemicals"], answer: "Energy is transferred from the chemicals to the surroundings; the products store less energy than the reactants by exactly the amount the surroundings gain, so the total energy is unchanged." },
      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 4, q: "Describe a method to investigate how the mass of magnesium powder added to 25 cm³ of hydrochloric acid affects the temperature change.", scheme: ["Measure 25 cm³ of acid with a measuring cylinder into a polystyrene cup (in a beaker, with a lid)", "Record the starting temperature of the acid with a thermometer", "Add a measured mass of magnesium, stir and record the highest temperature reached", "Calculate the temperature change and repeat with different masses of magnesium (using fresh acid each time)"], answer: "Measure 25 cm³ of acid into a polystyrene cup inside a beaker and record its starting temperature. Add a weighed mass of magnesium powder, put on the lid, stir and record the highest temperature. Calculate the temperature change, then repeat with fresh acid and different masses of magnesium." },
      { g: 6, marks: 3, q: "In an investigation into how the mass of magnesium added to hydrochloric acid affects the temperature change, identify the independent variable, the dependent variable and one control variable.", scheme: ["Independent: mass of magnesium", "Dependent: temperature change", "Control: volume/concentration of acid (or type of cup, starting temperature, particle size)"], answer: "Independent variable: mass of magnesium. Dependent variable: temperature change. Control variable: e.g. volume and concentration of acid." },
      { g: 6, marks: 2, q: "Explain, in terms of bonds, why a reaction is exothermic.", scheme: ["The energy released when new bonds form in the products", "Is greater than the energy needed to break bonds in the reactants"], answer: "More energy is released when the new bonds in the products are made than is needed to break the bonds in the reactants." },
      { g: 6, marks: 2, q: "Explain, in terms of bonds, why a reaction is endothermic.", scheme: ["The energy needed to break bonds in the reactants", "Is greater than the energy released when new bonds form in the products"], answer: "More energy is needed to break the bonds in the reactants than is released when the bonds in the products are made." },
      { g: 6, marks: 2, q: "The combustion of a match is exothermic. Explain why the match must be struck before it will burn.", scheme: ["The reacting particles need a minimum energy (activation energy) to react", "Striking the match supplies this energy (by friction/heat) to start the reaction"], answer: "The particles need the activation energy to react; striking the match supplies this energy, then the energy released keeps the reaction going." },
      { g: 6, marks: 3, q: "For the reaction H2 + Cl2 → 2HCl, calculate the overall energy change. Bond energies: H–H = 436 kJ/mol, Cl–Cl = 243 kJ/mol, H–Cl = 432 kJ/mol.", scheme: ["Bonds broken = 436 + 243 = 679 kJ/mol", "Bonds made = 2 × 432 = 864 kJ/mol", "Energy change = 679 − 864 = −185 kJ/mol"], answer: "Bonds broken: 436 + 243 = 679 kJ/mol. Bonds made: 2 × 432 = 864 kJ/mol. Energy change = 679 − 864 = −185 kJ/mol (exothermic)." },
      { g: 6, marks: 2, q: "A battery is made from three cells, each producing 1.5 V, connected in series. Calculate the voltage of the battery and explain your answer.", scheme: ["3 × 1.5 = 4.5 V", "Cells in series add their voltages together"], answer: "3 × 1.5 = 4.5 V, because the voltages of cells connected in series add together." },
      { g: 6, marks: 2, q: "A student repeats a reaction three times and records temperature rises of 6.2 °C, 6.6 °C and 6.4 °C. Calculate the mean temperature rise and state the type of reaction.", scheme: ["Mean = (6.2 + 6.6 + 6.4) ÷ 3 = 6.4 °C", "Exothermic (temperature rises)"], answer: "Mean = (6.2 + 6.6 + 6.4) ÷ 3 = 19.2 ÷ 3 = 6.4 °C. The temperature rises, so the reaction is exothermic." },
      { g: 6, marks: 2, q: "A student carries out an exothermic reaction in a glass beaker instead of a polystyrene cup. Explain how this would affect the measured temperature rise.", scheme: ["The measured temperature rise would be smaller", "Glass is a poorer insulator/better conductor so more energy is lost to the surroundings"], answer: "The temperature rise would be smaller, because glass is a poorer insulator than polystyrene so more energy is transferred to the surroundings." },
      { g: 6, marks: 3, q: "Three salts are dissolved separately in water starting at 20.0 °C. Salt A reaches 26.5 °C, salt B reaches 15.5 °C and salt C reaches 12.0 °C. Identify the salt that dissolves exothermically and the salt that is most endothermic, giving the temperature changes.", scheme: ["Salt A is exothermic: change = +6.5 °C", "Salt B = −4.5 °C and salt C = −8.0 °C", "Salt C is the most endothermic (largest temperature decrease)"], answer: "A: 26.5 − 20.0 = +6.5 °C, so A is exothermic. B: 15.5 − 20.0 = −4.5 °C; C: 12.0 − 20.0 = −8.0 °C. C has the largest decrease, so it is the most endothermic." },
      { g: 6, marks: 2, q: "Explain why a cell with two electrodes made of the same metal produces no voltage.", scheme: ["The voltage depends on the difference in reactivity between the two electrodes", "The same metal has no difference in reactivity, so there is no potential difference"], answer: "A cell's voltage comes from the difference in reactivity between the two metals; identical metals have no difference, so the voltage is zero." },
      { g: 6, marks: 3, q: "Describe how a student could set up a simple cell to investigate how the type of electrolyte affects the voltage produced.", scheme: ["Place two different metal electrodes (e.g. zinc and copper) in an electrolyte and connect them to a voltmeter", "Keep the same pair of metals (and electrolyte concentration/volume) each time", "Change the electrolyte (different salt solutions) and record the voltage for each"], answer: "Dip a zinc strip and a copper strip into an electrolyte and connect them with wires to a voltmeter. Keeping the metals and the electrolyte concentration the same, change the electrolyte solution and record the voltage each time." },
      { g: 6, marks: 2, q: "Give two advantages of hydrogen fuel cells compared with rechargeable batteries.", scheme: ["Only product is water (no pollutants during use)", "Do not need to be recharged/do not run down while fuel is supplied, or have fewer toxic chemicals to dispose of"], answer: "The only product is water, and they don't need recharging — they keep producing electricity while hydrogen is supplied (they also contain fewer toxic chemicals to dispose of)." },
      { g: 6, marks: 2, q: "Give two disadvantages of hydrogen fuel cells.", scheme: ["Hydrogen is a flammable gas that is difficult to store (needs large or high-pressure tanks)", "Hydrogen is often produced from fossil fuels/using electricity from non-renewable sources"], answer: "Hydrogen is a flammable gas that is hard to store safely, and it is often made from fossil fuels or using electricity from non-renewable sources." },
      { g: 6, marks: 2, q: "Describe how adding a catalyst changes the reaction profile of a reaction.", scheme: ["The peak is lower — the activation energy is reduced", "The energies of the reactants and products (overall energy change) stay the same"], answer: "A catalyst lowers the peak of the curve, reducing the activation energy, but the reactant and product energies — and so the overall energy change — do not change." },
      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Calculate the overall energy change for H2 + Br2 → 2HBr. Bond energies: H–H = 436 kJ/mol, Br–Br = 193 kJ/mol, H–Br = 366 kJ/mol. State whether the reaction is exothermic or endothermic.", scheme: ["Bonds broken = 436 + 193 = 629 kJ/mol", "Bonds made = 2 × 366 = 732 kJ/mol", "Energy change = 629 − 732 = −103 kJ/mol", "Exothermic (negative value)"], answer: "Bonds broken: 436 + 193 = 629 kJ/mol. Bonds made: 2 × 366 = 732 kJ/mol. Energy change = 629 − 732 = −103 kJ/mol, so the reaction is exothermic." },
      { g: 7, marks: 4, q: "Calculate the overall energy change for N2 + 3H2 → 2NH3. Bond energies: N≡N = 941 kJ/mol, H–H = 436 kJ/mol, N–H = 391 kJ/mol.", scheme: ["Bonds broken = 941 + (3 × 436) = 2249 kJ/mol", "Bonds made = 6 × 391 = 2346 kJ/mol (2 NH3 contain 6 N–H bonds)", "Energy change = 2249 − 2346", "= −97 kJ/mol"], answer: "Bonds broken: 941 + 3 × 436 = 941 + 1308 = 2249 kJ/mol. Bonds made: 2NH3 contain 6 N–H bonds, 6 × 391 = 2346 kJ/mol. Energy change = 2249 − 2346 = −97 kJ/mol (exothermic)." },
      { g: 7, marks: 4, q: "Calculate the overall energy change for 2HI → H2 + I2. Bond energies: H–I = 298 kJ/mol, H–H = 436 kJ/mol, I–I = 151 kJ/mol. State whether the reaction is exothermic or endothermic.", scheme: ["Bonds broken = 2 × 298 = 596 kJ/mol", "Bonds made = 436 + 151 = 587 kJ/mol", "Energy change = 596 − 587 = +9 kJ/mol", "Endothermic (positive value)"], answer: "Bonds broken: 2 × 298 = 596 kJ/mol. Bonds made: 436 + 151 = 587 kJ/mol. Energy change = 596 − 587 = +9 kJ/mol, so the reaction is endothermic." },
      { g: 7, marks: 3, q: "A student adds sodium hydroxide solution in 5 cm³ portions to hydrochloric acid in a polystyrene cup. The temperature rises to a maximum and then falls. Explain this pattern.", scheme: ["Neutralisation is exothermic, so the temperature rises as more alkali reacts", "The maximum is reached when all the acid has been neutralised", "After this, excess (cooler) alkali is added but no more reaction occurs, so the mixture cools (and energy is lost to the surroundings)"], answer: "Neutralisation is exothermic, so the temperature rises as alkali reacts with acid. The maximum occurs when all the acid is neutralised. Further alkali does not react, so the added cooler solution and energy loss to the surroundings make the temperature fall." },
      { g: 7, marks: 3, q: "Write the balanced symbol equation for the overall reaction in a hydrogen fuel cell and explain why the hydrogen is described as being oxidised.", scheme: ["2H2 + O2 → 2H2O", "Hydrogen loses electrons (at the negative electrode)", "Oxidation is loss of electrons (or hydrogen gains oxygen)"], answer: "2H2 + O2 → 2H2O. Hydrogen molecules lose electrons at the negative electrode to form H+ ions, and loss of electrons is oxidation." },
      { g: 7, marks: 3, q: "A student makes simple cells using pairs of metals from magnesium, zinc, iron and copper (reactivity: magnesium > zinc > iron > copper). Identify the pair that would give the highest voltage and the pair that would give the lowest voltage, and explain your choice.", scheme: ["Highest voltage: magnesium and copper", "Lowest voltage: zinc and iron", "The bigger the difference in reactivity between the metals, the bigger the voltage"], answer: "Magnesium and copper give the highest voltage and zinc and iron the lowest, because the voltage increases with the difference in reactivity between the two metals." },
      { g: 7, marks: 3, q: "Explain why a hydrogen fuel cell in a car does not need recharging, whereas a lithium-ion battery does.", scheme: ["In a fuel cell, the reactants (hydrogen and oxygen) are supplied continuously from outside the cell", "In a battery the reactants are stored inside and are eventually used up", "The battery must be recharged by an external current to reverse the reaction; the fuel cell just needs refuelling"], answer: "A fuel cell is fed continuously with hydrogen and oxygen from outside, so it keeps working while refuelled. A battery stores its reactants inside; they are used up, and an external current must reverse the reactions to recharge it." },
      { g: 7, marks: 3, q: "An instant cold pack contains solid ammonium nitrate and a separate bag of water. Explain how the pack works and why it can only be used once.", scheme: ["Squeezing breaks the inner bag so the ammonium nitrate dissolves in the water", "Dissolving is endothermic, taking in energy from the surroundings so the pack cools", "Once all the solid has dissolved the process has finished and cannot easily be reversed, so it cannot be reused"], answer: "Squeezing the pack breaks the water bag so the ammonium nitrate dissolves. This is endothermic, taking in energy from the surroundings so the pack feels cold. Once the solid has dissolved, the process is complete and the pack cannot easily be reused." },
      { g: 7, marks: 3, q: "Explain, in terms of bond breaking and bond making, why the combustion of fuels such as methane releases a lot of energy.", scheme: ["Energy is needed to break bonds in the fuel and oxygen (endothermic)", "Energy is released when the strong bonds in carbon dioxide and water form (exothermic)", "More energy is released making the bonds in the products than is used breaking the bonds in the reactants"], answer: "Breaking the C–H and O=O bonds takes in energy, but forming the strong C=O and O–H bonds in carbon dioxide and water releases more energy than was taken in, so overall a lot of energy is released." },
      { g: 7, marks: 3, q: "Equal amounts of zinc powder and magnesium powder are added separately to 25 cm³ of copper sulfate solution at 20.5 °C. The zinc mixture reaches 31.0 °C and the magnesium mixture reaches 45.5 °C. Calculate both temperature changes and explain the difference.", scheme: ["Zinc: 31.0 − 20.5 = 10.5 °C", "Magnesium: 45.5 − 20.5 = 25.0 °C", "Magnesium is more reactive than zinc (bigger difference in reactivity from copper), so more energy is released"], answer: "Zinc: 31.0 − 20.5 = 10.5 °C. Magnesium: 45.5 − 20.5 = 25.0 °C. Magnesium is further above copper in the reactivity series than zinc, so its displacement reaction releases more energy." },
      { g: 7, marks: 3, q: "A student's measured temperature rise for an exothermic reaction is lower than expected. Suggest three improvements to the method.", scheme: ["Put a lid on the cup / use a polystyrene cup inside a beaker (or add insulation such as cotton wool)", "Stir the mixture so the temperature is even and record the highest temperature reached", "Use a thermometer with a higher resolution / repeat and calculate a mean (or use a temperature probe and data logger)"], answer: "Use a lid and extra insulation (e.g. cup inside a beaker) to reduce energy loss; stir and record the maximum temperature; use a higher-resolution thermometer or data logger and repeat to calculate a mean." },
      { g: 7, marks: 3, q: "Hydrogen for fuel cells is mostly produced from methane. Explain why hydrogen fuel cell cars are not necessarily carbon-neutral, even though they only emit water.", scheme: ["Producing hydrogen from methane (a fossil fuel) releases carbon dioxide", "Hydrogen made by electrolysis may use electricity from fossil-fuel power stations", "Energy is also needed to compress, store and transport the hydrogen, which may release CO2"], answer: "Making hydrogen from methane releases carbon dioxide; if made by electrolysis, the electricity may come from burning fossil fuels; and compressing, storing and transporting hydrogen also uses energy that may produce CO2." },
      { g: 7, marks: 3, q: "In a reaction profile, the reactants are at 100 kJ/mol, the peak of the curve is at 180 kJ/mol and the products are at 40 kJ/mol. Calculate the activation energy and the overall energy change, and state the type of reaction.", scheme: ["Activation energy = 180 − 100 = 80 kJ/mol", "Overall energy change = 40 − 100 = −60 kJ/mol", "Exothermic (products lower in energy than reactants)"], answer: "Activation energy = 180 − 100 = 80 kJ/mol. Overall energy change = 40 − 100 = −60 kJ/mol, so the reaction is exothermic." },
      { g: 7, marks: 3, q: "Explain, in terms of activation energy, why a mixture of hydrogen and oxygen can be kept at room temperature without reacting, but explodes when a spark is applied.", scheme: ["At room temperature few/no particles have enough energy to overcome the activation energy", "The spark supplies energy so some particles reach the activation energy and react", "The reaction is exothermic, so the energy released provides the activation energy for more particles, so it spreads rapidly"], answer: "At room temperature the particles don't have enough energy to overcome the activation energy. A spark gives some particles enough energy to react; the energy released by this exothermic reaction then supplies the activation energy for more particles, so the reaction spreads explosively." },
      { g: 7, marks: 3, q: "Explain what happens chemically when a rechargeable cell is used and then recharged.", scheme: ["When used, a chemical reaction produces a voltage/current and the reactants are gradually used up", "When recharged, an external electrical current is applied", "This reverses the reaction, re-forming the original reactants"], answer: "In use, the chemical reaction produces an electric current and the reactants are used up. When recharging, an external current is supplied which reverses the reaction and re-forms the reactants." },
      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 5, q: "Calculate the overall energy change for the combustion of methane: CH4 + 2O2 → CO2 + 2H2O. Bond energies: C–H = 413 kJ/mol, O=O = 498 kJ/mol, C=O = 805 kJ/mol, O–H = 464 kJ/mol.", scheme: ["Bonds broken = (4 × 413) + (2 × 498) = 1652 + 996", "= 2648 kJ/mol", "Bonds made = (2 × 805) + (4 × 464) = 1610 + 1856 = 3466 kJ/mol", "Energy change = 2648 − 3466 = −818", "Unit kJ/mol (and exothermic)"], answer: "Bonds broken: 4 × 413 + 2 × 498 = 1652 + 996 = 2648 kJ/mol. Bonds made: 2 × 805 + 4 × 464 = 1610 + 1856 = 3466 kJ/mol. Energy change = 2648 − 3466 = −818 kJ/mol (exothermic)." },
      { g: 8, marks: 4, q: "Calculate the overall energy change for 2H2 + O2 → 2H2O. Bond energies: H–H = 436 kJ/mol, O=O = 498 kJ/mol, O–H = 464 kJ/mol.", scheme: ["Bonds broken = (2 × 436) + 498 = 1370 kJ/mol", "Bonds made = 4 × 464 = 1856 kJ/mol (2 H2O contain 4 O–H bonds)", "Energy change = 1370 − 1856", "= −486 kJ/mol"], answer: "Bonds broken: 2 × 436 + 498 = 872 + 498 = 1370 kJ/mol. Bonds made: 4 × 464 = 1856 kJ/mol. Energy change = 1370 − 1856 = −486 kJ/mol (exothermic)." },
      { g: 8, marks: 3, q: "For H2 + Cl2 → 2HCl the overall energy change is −185 kJ/mol. Given H–H = 436 kJ/mol and Cl–Cl = 243 kJ/mol, calculate the H–Cl bond energy.", scheme: ["Bonds broken = 436 + 243 = 679 kJ/mol", "679 − 2x = −185, so 2x = 864", "x = 432 kJ/mol"], answer: "Bonds broken = 436 + 243 = 679 kJ/mol. Energy change = broken − made, so 679 − 2x = −185, giving 2x = 679 + 185 = 864, so H–Cl = 864 ÷ 2 = 432 kJ/mol." },
      { g: 8, marks: 4, q: "Ethene (H2C=CH2) reacts with hydrogen to form ethane (H3C–CH3): C2H4 + H2 → C2H6. Calculate the overall energy change. Bond energies: C=C = 612 kJ/mol, C–H = 413 kJ/mol, H–H = 436 kJ/mol, C–C = 347 kJ/mol.", scheme: ["Bonds broken = 612 + (4 × 413) + 436 = 2700 kJ/mol", "Bonds made = 347 + (6 × 413) = 2825 kJ/mol", "Energy change = 2700 − 2825 = −125", "Unit kJ/mol and exothermic"], answer: "Bonds broken: 612 + 4 × 413 + 436 = 612 + 1652 + 436 = 2700 kJ/mol. Bonds made: 347 + 6 × 413 = 347 + 2478 = 2825 kJ/mol. Energy change = 2700 − 2825 = −125 kJ/mol, so exothermic." },
      { g: 8, marks: 3, q: "Write the half equation for the reaction at the negative electrode of a hydrogen fuel cell with an acidic electrolyte, and state whether hydrogen is oxidised or reduced.", scheme: ["2H2 → 4H+ + 4e− (or H2 → 2H+ + 2e−)", "Hydrogen loses electrons", "So hydrogen is oxidised"], answer: "2H2 → 4H+ + 4e−. Hydrogen loses electrons, so it is oxidised." },
      { g: 8, marks: 3, q: "A reaction has an activation energy of 120 kJ/mol and an overall energy change of −80 kJ/mol. Taking the reactants as 0 kJ/mol, state the energy at the peak of the profile and of the products, and calculate the activation energy for the reverse reaction.", scheme: ["Peak at +120 kJ/mol", "Products at −80 kJ/mol", "Reverse activation energy = 120 − (−80) = 200 kJ/mol"], answer: "The peak is at +120 kJ/mol and the products are at −80 kJ/mol. For the reverse reaction, the climb from products to peak is 120 − (−80) = 200 kJ/mol." },
      { g: 8, marks: 4, q: "Hydrogen peroxide (H–O–O–H) decomposes: 2H2O2 → 2H2O + O2. Calculate the overall energy change. Bond energies: O–H = 464 kJ/mol, O–O = 146 kJ/mol, O=O = 498 kJ/mol.", scheme: ["Bonds broken = 2 × [(2 × 464) + 146] = 2148 kJ/mol", "Bonds made = (4 × 464) + 498 = 2354 kJ/mol", "Energy change = 2148 − 2354 = −206", "Unit kJ/mol and exothermic"], answer: "Each H2O2 has 2 O–H and 1 O–O: broken = 2 × (928 + 146) = 2148 kJ/mol. Made: 2H2O has 4 O–H plus one O=O = 1856 + 498 = 2354 kJ/mol. Energy change = 2148 − 2354 = −206 kJ/mol, so exothermic." },
      { g: 8, marks: 3, q: "Suggest three reasons why the energy change of a reaction measured in a school experiment is often different from the value calculated using bond energies.", scheme: ["Bond energies are average values for that bond in many different molecules", "Energy is lost to the surroundings in the experiment", "Reaction may be incomplete / substances may not all be gases as bond energies assume"], answer: "Bond energies are averages taken from many different compounds; in the experiment energy is lost to the surroundings; and the reaction may be incomplete or involve liquids and solutions rather than gases." },
      { g: 8, marks: 3, q: "For H2 + Cl2 → 2HCl the energy change is −185 kJ/mol. Calculate the energy released when 10 mol of hydrogen chloride is formed.", scheme: ["2 mol HCl formed releases 185 kJ", "10 mol HCl = 5 × the equation amounts", "Energy released = 5 × 185 = 925 kJ"], answer: "The equation forms 2 mol HCl and releases 185 kJ. 10 mol is 5 times this, so 5 × 185 = 925 kJ is released." },
      { g: 8, marks: 5, q: "Nitrogen reacts with oxygen in car engines: N2 + O2 → 2NO. Calculate the overall energy change and explain why this reaction happens in car engines but not in the air at normal temperatures. Bond energies: N≡N = 945 kJ/mol, O=O = 498 kJ/mol, N=O = 630 kJ/mol.", scheme: ["Bonds broken = 945 + 498 = 1443 kJ/mol", "Bonds made = 2 × 630 = 1260 kJ/mol", "Energy change = 1443 − 1260 = +183 kJ/mol", "Endothermic (and the N≡N bond is very strong, so the activation energy is high)", "The very high temperature in the engine supplies the energy needed"], answer: "Bonds broken: 945 + 498 = 1443 kJ/mol. Bonds made: 2 × 630 = 1260 kJ/mol. Energy change = 1443 − 1260 = +183 kJ/mol, so it is endothermic with a high activation energy (strong N≡N bond). Only the very high temperatures in engines supply enough energy for it to happen." },
      { g: 8, marks: 3, q: "When measuring the temperature change for a metal reacting with an acid, explain why the student should use metal powder rather than ribbon and stir the mixture.", scheme: ["Powder has a larger surface area so reacts faster", "The maximum temperature is reached quickly, before much energy is lost to the surroundings", "Stirring spreads the energy evenly so the thermometer reading represents the whole mixture"], answer: "Powder has a larger surface area so it reacts faster, reaching the maximum temperature before much energy escapes to the surroundings. Stirring spreads the energy evenly so the thermometer reading is representative." },
      { g: 8, marks: 5, q: "Plan an investigation to find which of four metals releases the most energy when reacting with copper sulfate solution.", scheme: ["Measure a fixed volume (e.g. 25 cm³) of copper sulfate solution of the same concentration into a polystyrene cup with a lid", "Record the starting temperature", "Add the same mass (and same particle size) of one metal, stir and record the highest temperature", "Calculate the temperature change and repeat for each metal (using fresh solution each time)", "Repeat each test and calculate means; the metal with the largest temperature rise releases most energy"], answer: "Put 25 cm³ of the same copper sulfate solution into an insulated polystyrene cup with a lid and record the temperature. Add a fixed mass of metal powder, stir and record the highest temperature. Repeat with fresh solution for each metal, repeat each test and calculate mean temperature rises — the largest rise shows the most energy released." },
      { g: 8, marks: 3, q: "Explain why a hydrogen fuel cell is usually more efficient at powering a vehicle than burning hydrogen in an engine.", scheme: ["A fuel cell transfers chemical energy directly into electrical energy", "Burning involves more energy transfer stages (chemical → thermal → kinetic)", "So less energy is wasted as heat to the surroundings in a fuel cell"], answer: "A fuel cell converts chemical energy directly to electrical energy, whereas combustion goes through thermal energy stores first. With fewer transfer stages, less energy is wasted as heat, so the fuel cell is more efficient." },
      { g: 8, marks: 3, q: "A student writes: 'Exothermic reactions release energy because breaking bonds releases energy.' Explain why the student is wrong and give a correct explanation.", scheme: ["Breaking bonds requires/takes in energy (endothermic)", "Making bonds releases energy (exothermic)", "A reaction is exothermic because more energy is released making new bonds than is taken in breaking bonds"], answer: "Breaking bonds takes in energy, it does not release it. Energy is released when bonds are made, and a reaction is exothermic because more energy is released making the new bonds than is needed to break the old ones." },
      { g: 8, marks: 4, q: "A simple cell has a zinc electrode and a copper electrode in copper sulfate solution, joined by a wire. Explain, in terms of electrons, how the cell produces an electric current.", scheme: ["Zinc is more reactive, so zinc atoms lose electrons: Zn → Zn2+ + 2e−", "Electrons flow through the external wire from the zinc to the copper electrode", "At the copper electrode, copper ions gain electrons: Cu2+ + 2e− → Cu", "Zinc is the negative electrode (and copper the positive electrode)"], answer: "Zinc is more reactive, so zinc atoms lose electrons (Zn → Zn2+ + 2e−), making zinc the negative electrode. The electrons flow through the wire to the copper electrode, where Cu2+ ions from the solution gain them (Cu2+ + 2e− → Cu). This flow of electrons is the current." },
      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Evaluate the use of hydrogen fuel cells compared with rechargeable lithium-ion batteries to power electric cars.", scheme: ["Fuel cells: only water is produced during use, and refuelling is quick", "Fuel cells: do not need recharging and don't lose capacity after many charge cycles", "Fuel cells: hydrogen is flammable and hard to store (needs high-pressure tanks); few refuelling stations", "Fuel cells: hydrogen is often made from fossil fuels or by electrolysis using non-renewable electricity", "Batteries: can be charged from mains electricity (possibly renewable) but recharging is slow, capacity falls over time and they contain toxic/scarce metals that are hard to dispose of", "Justified conclusion weighing up the points (e.g. depends on how the hydrogen/electricity is produced)"], answer: "Hydrogen fuel cells only produce water, refuel quickly and do not need recharging or wear out through charge cycles. However, hydrogen is flammable, difficult to store, has few refuelling stations and is mostly made from methane or with fossil-fuel electricity. Batteries can use existing mains electricity, possibly from renewables, but recharge slowly, lose capacity and contain toxic metals that are hard to recycle. Overall, neither is automatically greener — it depends on how the hydrogen or electricity is produced." },
      { g: 9, marks: 5, q: "Calculate the overall energy change for the combustion of propane: C3H8 + 5O2 → 3CO2 + 4H2O. Bond energies: C–C = 347 kJ/mol, C–H = 413 kJ/mol, O=O = 498 kJ/mol, C=O = 805 kJ/mol, O–H = 464 kJ/mol.", scheme: ["Propane contains 2 C–C and 8 C–H bonds", "Bonds broken = (2 × 347) + (8 × 413) + (5 × 498) = 694 + 3304 + 2490 = 6488 kJ/mol", "Bonds made = (6 × 805) + (8 × 464) = 4830 + 3712 = 8542 kJ/mol", "Energy change = 6488 − 8542 = −2054", "Unit kJ/mol and exothermic"], answer: "Propane has 2 C–C and 8 C–H bonds. Broken: 2 × 347 + 8 × 413 + 5 × 498 = 694 + 3304 + 2490 = 6488 kJ/mol. Made: 3CO2 has 6 C=O and 4H2O has 8 O–H: 6 × 805 + 8 × 464 = 4830 + 3712 = 8542 kJ/mol. Energy change = 6488 − 8542 = −2054 kJ/mol (exothermic)." },
      { g: 9, marks: 6, q: "2H2 + O2 → 2H2O has an energy change of −486 kJ/mol and CH4 + 2O2 → CO2 + 2H2O has an energy change of −818 kJ/mol. Using Ar: H = 1, C = 12, compare the energy released per gram of each fuel and evaluate hydrogen as a fuel.", scheme: ["Hydrogen: 486 ÷ 2 = 243 kJ per mole of H2", "243 ÷ 2 (Mr of H2) = 121.5 kJ/g", "Methane: Mr = 16, so 818 ÷ 16 = 51.1 kJ/g", "Hydrogen releases more than twice as much energy per gram", "Hydrogen produces only water, whereas methane releases carbon dioxide (greenhouse gas)", "But hydrogen is hard to store and is often made from fossil fuels, so a balanced conclusion is needed"], answer: "Hydrogen: 486 kJ for 2 mol, so 243 kJ/mol; Mr = 2, so 243 ÷ 2 = 121.5 kJ/g. Methane: Mr = 12 + 4 = 16, so 818 ÷ 16 = 51.1 kJ/g. Hydrogen releases over twice as much energy per gram and only produces water, while methane produces CO2. However, hydrogen is a gas that is hard to store and is usually produced from fossil fuels, so its benefits depend on how it is made." },
      { g: 9, marks: 4, q: "For CH4 + 2O2 → CO2 + 2H2O the energy change is −818 kJ/mol. Given C–H = 413 kJ/mol, O=O = 498 kJ/mol and O–H = 464 kJ/mol, calculate the C=O bond energy.", scheme: ["Bonds broken = (4 × 413) + (2 × 498) = 2648 kJ/mol", "Bonds made = 2x + (4 × 464) = 2x + 1856", "2648 − (2x + 1856) = −818, so 2x = 1610", "x = 805 kJ/mol"], answer: "Broken = 4 × 413 + 2 × 498 = 2648 kJ/mol. Made = 2x + 4 × 464 = 2x + 1856. 2648 − (2x + 1856) = −818 → 2x + 1856 = 3466 → 2x = 1610 → C=O = 805 kJ/mol." },
      { g: 9, marks: 5, q: "Methane reacts with chlorine: CH4 + Cl2 → CH3Cl + HCl. Calculate the overall energy change and explain why the calculation gives the same answer if only the bonds that change are considered. Bond energies: C–H = 413 kJ/mol, Cl–Cl = 243 kJ/mol, C–Cl = 346 kJ/mol, H–Cl = 432 kJ/mol.", scheme: ["Bonds broken = (4 × 413) + 243 = 1895 kJ/mol", "Bonds made = (3 × 413) + 346 + 432 = 2017 kJ/mol", "Energy change = 1895 − 2017 = −122 kJ/mol (exothermic)", "Three C–H bonds are broken and re-made, so their energies cancel out", "Only one C–H and Cl–Cl broken (656) and C–Cl and H–Cl made (778) gives 656 − 778 = −122 kJ/mol"], answer: "Broken: 4 × 413 + 243 = 1652 + 243 = 1895 kJ/mol. Made: 3 × 413 + 346 + 432 = 1239 + 778 = 2017 kJ/mol. Energy change = 1895 − 2017 = −122 kJ/mol. Three C–H bonds are effectively broken and re-formed, so they cancel: 413 + 243 = 656 and 346 + 432 = 778 gives 656 − 778 = −122 kJ/mol too." },
      { g: 9, marks: 6, q: "A student investigates the temperature change when hydrochloric acid reacts with sodium hydroxide. They use a glass beaker with no lid, measure the solutions with a beaker, read the thermometer once after exactly 1 minute and do the experiment once. Evaluate the method and suggest improvements.", scheme: ["Glass beaker with no lid allows energy loss — use a polystyrene cup with a lid, inside a beaker", "Measuring volumes with a beaker is imprecise — use a measuring cylinder or pipette/burette", "Reading after a fixed 1 minute may miss the maximum — stir and record the highest temperature reached", "No starting temperature check / both solutions should start at the same temperature", "A single result cannot be checked for anomalies — repeat and calculate a mean", "Conclusion: the method underestimates the temperature change; improvements increase accuracy and repeatability"], answer: "The glass beaker without a lid loses energy, so use a lidded polystyrene cup. Beakers measure volumes imprecisely, so use a measuring cylinder or pipette. Reading after 1 minute may miss the peak, so stir and record the maximum temperature, having recorded the starting temperatures of both solutions. One run gives no check for anomalies, so repeat and take a mean. As it stands, the method underestimates the temperature rise." },
      { g: 9, marks: 4, q: "The combustion of methane has an energy change of −818 kJ/mol. Calculate the mass of methane that must be burned to release 4090 kJ of energy. (Ar: C = 12, H = 1)", scheme: ["Moles = 4090 ÷ 818", "= 5.0 mol", "Mr of CH4 = 12 + (4 × 1) = 16", "Mass = 5.0 × 16 = 80 g"], answer: "Moles of methane = 4090 ÷ 818 = 5.0 mol. Mr of CH4 = 12 + 4 = 16. Mass = 5.0 × 16 = 80 g." },
      { g: 9, marks: 5, q: "Explain, using half equations, how a hydrogen fuel cell with an acidic electrolyte produces an electric current.", scheme: ["At the negative electrode hydrogen is oxidised: 2H2 → 4H+ + 4e−", "Electrons flow through the external circuit from the negative to the positive electrode (this is the current)", "H+ ions move through the electrolyte to the positive electrode", "At the positive electrode oxygen is reduced: O2 + 4H+ + 4e− → 2H2O", "Adding the half equations gives the overall reaction 2H2 + O2 → 2H2O"], answer: "At the negative electrode hydrogen loses electrons (oxidation): 2H2 → 4H+ + 4e−. The electrons flow through the external circuit — the current — while H+ ions move through the electrolyte. At the positive electrode oxygen gains electrons (reduction): O2 + 4H+ + 4e− → 2H2O. Overall: 2H2 + O2 → 2H2O." },
      { g: 9, marks: 4, q: "Evaluate whether non-rechargeable alkaline batteries or rechargeable batteries are the better choice for a TV remote control.", scheme: ["Alkaline: cheaper to buy and a remote uses very little power, so they last a long time", "Alkaline: must be thrown away when used up, creating waste/using more resources", "Rechargeable: more expensive and need a charger, but can be reused many times, reducing waste", "Justified conclusion (e.g. alkaline acceptable for low-drain devices, rechargeables better for high-drain or environmental reasons)"], answer: "Alkaline batteries are cheap and a remote uses little power so they last many months, but they must be discarded, creating waste. Rechargeables cost more and need a charger but can be reused many times. For a low-drain device like a remote, alkaline batteries are convenient, though rechargeables reduce waste over time." },
      { g: 9, marks: 5, q: "Once lit, methane continues to burn without further heating, but calcium carbonate only decomposes while it is heated strongly. Explain this difference using ideas about activation energy and energy changes.", scheme: ["Both reactions need energy to overcome the activation energy before they start", "Methane combustion is exothermic, releasing more energy than was needed to break bonds", "The energy released supplies the activation energy for further methane molecules, so the reaction is self-sustaining", "Decomposition of calcium carbonate is endothermic — products have more energy than reactants", "So energy must be supplied continuously, both to reach the activation energy and to provide the overall energy taken in"], answer: "Both reactions need the activation energy to start. Combustion of methane is exothermic, so the energy released provides the activation energy for more molecules and burning continues by itself. Thermal decomposition of calcium carbonate is endothermic, so no net energy is released; energy must be supplied continuously to overcome the activation energy and to provide the energy taken in by the reaction." },
      { g: 9, marks: 5, q: "Sodium hydroxide solution is added in 5 cm³ portions to 25 cm³ of hydrochloric acid. The temperatures are: 0 cm³, 20.0 °C; 5 cm³, 23.2 °C; 10 cm³, 26.4 °C; 15 cm³, 29.2 °C; 20 cm³, 28.4 °C; 25 cm³, 27.6 °C. By finding where the rising and falling straight-line trends meet, determine the volume needed for neutralisation and the maximum temperature, and explain the shape of the results.", scheme: ["Rising trend: temperature increases by 0.64 °C per cm³ (T = 20.0 + 0.64V) from the first three points", "Falling trend: temperature decreases by 0.16 °C per cm³ (T = 31.6 − 0.16V) from the last points", "Lines meet when 20.0 + 0.64V = 31.6 − 0.16V, so V = 14.5 cm³", "Maximum temperature = 20.0 + 0.64 × 14.5 ≈ 29.3 °C", "Rise: exothermic neutralisation; fall: acid used up so added alkali cools the mixture (and energy is lost to surroundings)"], answer: "Rising line: +3.2 °C per 5 cm³, so T = 20.0 + 0.64V. Falling line: −0.8 °C per 5 cm³, so T = 31.6 − 0.16V. Setting equal: 0.80V = 11.6, V = 14.5 cm³, and T = 20.0 + 9.28 ≈ 29.3 °C. The temperature rises because neutralisation is exothermic; after all the acid has reacted, further cooler alkali and energy loss make it fall." },
      { g: 9, marks: 5, q: "A zinc–copper cell produces 1.10 V and a magnesium–copper cell produces 2.71 V. Predict the voltage of a magnesium–zinc cell, state which electrode is negative, and calculate the minimum number of magnesium–zinc cells in series needed to produce more than 6 V.", scheme: ["Mg–Zn voltage = 2.71 − 1.10 = 1.61 V", "Because voltage depends on the difference in reactivity, and zinc lies between magnesium and copper", "Magnesium is the negative electrode (more reactive, loses electrons)", "6 ÷ 1.61 = 3.7, so 4 cells are needed", "4 × 1.61 = 6.44 V (3 cells would give only 4.83 V)"], answer: "Voltage depends on the difference in reactivity, and zinc lies between magnesium and copper, so Mg–Zn = 2.71 − 1.10 = 1.61 V. Magnesium is more reactive, so it is the negative electrode. 6 ÷ 1.61 = 3.7, so 4 cells are needed: 4 × 1.61 = 6.44 V (3 cells give only 4.83 V)." },
      { g: 9, marks: 4, q: "Evaluate the use of an exothermic reaction, such as calcium oxide reacting with water, to heat food in a self-heating can.", scheme: ["Advantage: no external energy source (flame/electricity) needed — useful when camping or in emergencies", "Disadvantage: single use only — the reactants are used up, producing extra waste", "Disadvantage: more expensive than normal cans and the chemicals take up space, reducing the amount of food", "Risk of burns or uneven/limited heating; justified conclusion (useful for specific situations, not everyday use)"], answer: "Self-heating cans heat food without a flame or electricity, useful for camping or emergencies. However, they only work once, create extra waste, cost more, and the chemicals take up space so there is less food. They can also cause burns or heat unevenly, so they suit occasional specialist use rather than everyday use." },
      { g: 9, marks: 6, q: "Using bond energies, compare the energy changes for H2 + F2 → 2HF and H2 + Cl2 → 2HCl, and explain the difference. Bond energies: H–H = 436 kJ/mol, F–F = 158 kJ/mol, H–F = 568 kJ/mol, Cl–Cl = 243 kJ/mol, H–Cl = 432 kJ/mol.", scheme: ["HF: bonds broken = 436 + 158 = 594 kJ/mol; bonds made = 2 × 568 = 1136 kJ/mol", "HF: energy change = 594 − 1136 = −542 kJ/mol", "HCl: bonds broken = 436 + 243 = 679 kJ/mol; bonds made = 2 × 432 = 864 kJ/mol", "HCl: energy change = 679 − 864 = −185 kJ/mol", "Both exothermic, but forming HF releases much more energy because the H–F bond is stronger than H–Cl", "Also the F–F bond is weaker than Cl–Cl, so less energy is needed to break it"], answer: "HF: broken 436 + 158 = 594; made 2 × 568 = 1136; change = 594 − 1136 = −542 kJ/mol. HCl: broken 436 + 243 = 679; made 2 × 432 = 864; change = 679 − 864 = −185 kJ/mol. Both are exothermic, but HF formation releases far more energy because H–F bonds are stronger (more energy released when made) and F–F is weaker than Cl–Cl (less energy needed to break)." },
      { g: 9, marks: 5, q: "Excess renewable electricity can be used to electrolyse water into hydrogen and oxygen, and the hydrogen later used in a fuel cell. Explain why the fuel cell cannot return more energy than was used, and evaluate this method of storing energy.", scheme: ["Electrolysis of water is the reverse of the fuel cell reaction, so it is endothermic (needs at least as much energy as the fuel cell releases)", "Energy is conserved, so the fuel cell cannot release more energy than was put in", "Some energy is wasted as heat in both processes, so less electrical energy is recovered than used", "Advantage: stores surplus renewable energy for later/hydrogen can be transported, with only water produced", "Disadvantage: energy losses, and hydrogen is flammable and difficult to store; justified conclusion"], answer: "Splitting water is the reverse of the fuel cell reaction, so it takes in at least as much energy as the fuel cell gives out; by conservation of energy you cannot get more out than you put in, and heat losses in both steps mean you get less back. The method usefully stores surplus renewable electricity and produces only water, but the energy losses and the difficulty of storing flammable hydrogen make it less efficient than using the electricity directly." },
    ],
    "6. Rate & extent of change": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "State the equation for calculating the mean rate of a reaction from the amount of product formed.", scheme: ["Mean rate = quantity of product formed ÷ time taken"], answer: "Mean rate of reaction = quantity of product formed ÷ time taken." },
      { g: 4, marks: 2, q: "Name four factors that affect the rate of a chemical reaction.", scheme: ["Any two of: temperature, concentration of solutions, pressure of gases, surface area of solids, catalyst", "Any two further factors from the list"], answer: "Temperature, concentration (of solutions), surface area (of solids) and the use of a catalyst (pressure of gases also affects rate)." },
      { g: 4, marks: 1, q: "What is a catalyst?", scheme: ["A substance that speeds up a reaction without being used up"], answer: "A substance that increases the rate of a reaction without being used up." },
      { g: 4, marks: 1, q: "What name is given to the minimum amount of energy that colliding particles must have in order to react?", scheme: ["Activation energy"], answer: "The activation energy." },
      { g: 4, marks: 1, q: "What are biological catalysts called?", scheme: ["Enzymes"], answer: "Enzymes." },
      { g: 4, marks: 2, q: "According to collision theory, what two things are needed for particles to react?", scheme: ["The particles must collide", "With enough energy (at least the activation energy)"], answer: "The particles must collide with each other, and the collision must have at least the activation energy." },
      { g: 4, marks: 1, q: "What symbol is used in a chemical equation to show that a reaction is reversible?", scheme: ["⇌ (two half-arrows pointing in opposite directions)"], answer: "The ⇌ symbol (two half-arrows pointing in opposite directions)." },
      { g: 4, marks: 1, q: "What is a reversible reaction?", scheme: ["A reaction in which the products can react to re-form the reactants"], answer: "A reaction in which the products can react to re-form the original reactants." },
      { g: 4, marks: 1, q: "Give a unit for the rate of a reaction that is followed by measuring the volume of gas produced.", scheme: ["cm³/s (or cm³/min)"], answer: "cm³/s (cubic centimetres per second)." },
      { g: 4, marks: 1, q: "What happens to the rate of a reaction when the temperature is increased?", scheme: ["The rate increases"], answer: "The rate of reaction increases." },
      { g: 4, marks: 1, q: "Why is a catalyst not included in the overall equation for a reaction?", scheme: ["It is not used up / is chemically unchanged at the end"], answer: "Because it is not used up — it is chemically unchanged at the end of the reaction." },
      { g: 4, marks: 1, q: "What colour change is seen when blue hydrated copper sulfate is heated?", scheme: ["Blue to white"], answer: "It changes from blue to white (anhydrous copper sulfate)." },
      { g: 4, marks: 1, q: "What is meant by a 'closed system' for a reaction?", scheme: ["Apparatus that prevents the escape of reactants and products (nothing can get in or out)"], answer: "Apparatus that stops any reactants or products escaping, so nothing can get in or out." },
      { g: 4, marks: 1, q: "When a reversible reaction is at equilibrium, how do the rates of the forward and reverse reactions compare?", scheme: ["They are equal"], answer: "The forward and reverse reactions happen at exactly the same rate." },
      { g: 4, marks: 2, q: "Name two quantities you could measure over time to follow the rate of the reaction between marble chips and hydrochloric acid.", scheme: ["The volume of carbon dioxide gas given off (e.g. with a gas syringe)", "The loss in mass of the flask and contents (on a balance)"], answer: "The volume of carbon dioxide produced, using a gas syringe, and the decrease in mass of the flask as the gas escapes, using a balance." },
      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "A reaction produces 60 cm³ of gas in 30 seconds. Calculate the mean rate of reaction.", scheme: ["Mean rate = 60 ÷ 30", "= 2 cm³/s"], answer: "Mean rate = volume of gas ÷ time = 60 ÷ 30 = 2 cm³/s." },
      { g: 5, marks: 2, q: "Explain why increasing the concentration of hydrochloric acid increases the rate of its reaction with magnesium.", scheme: ["There are more acid particles in the same volume", "So collisions with magnesium are more frequent"], answer: "A more concentrated acid has more acid particles in the same volume, so they collide with the magnesium more frequently and the reaction is faster." },
      { g: 5, marks: 2, q: "Explain why powdered calcium carbonate reacts faster with acid than the same mass of large marble chips.", scheme: ["The powder has a larger surface area (to volume ratio)", "So more particles are exposed and collisions are more frequent"], answer: "The powder has a much larger surface area, so more calcium carbonate particles are exposed to the acid and collisions happen more frequently." },
      { g: 5, marks: 2, q: "Give two reasons why increasing the temperature increases the rate of a reaction.", scheme: ["Particles move faster, so they collide more frequently", "Collisions have more energy, so more of them reach the activation energy (more successful collisions)"], answer: "At a higher temperature the particles move faster, so they collide more often, and the collisions are more energetic, so more of them have at least the activation energy." },
      { g: 5, marks: 2, q: "Explain how a catalyst increases the rate of a reaction.", scheme: ["It provides a different reaction pathway", "With a lower activation energy"], answer: "A catalyst provides a different pathway for the reaction that has a lower activation energy, so more collisions are successful." },
      { g: 5, marks: 2, q: "Explain why a reversible reaction can only reach equilibrium in a closed system.", scheme: ["In an open system products (e.g. gases) can escape", "So the reverse reaction cannot happen at the same rate as the forward reaction"], answer: "In an open system products such as gases escape, so the reverse reaction cannot keep pace with the forward reaction and equilibrium can never be established." },
      { g: 5, marks: 2, q: "Describe what is meant by dynamic equilibrium.", scheme: ["The forward and reverse reactions are happening at the same rate", "So the amounts (concentrations) of reactants and products stay constant"], answer: "In a closed system, the forward and reverse reactions continue at the same rate, so the amounts of reactants and products stay constant." },
      { g: 5, marks: 2, q: "The mass of a flask decreases by 3.0 g in 60 s as gas escapes during a reaction. Calculate the mean rate of reaction.", scheme: ["Mean rate = 3.0 ÷ 60", "= 0.05 g/s"], answer: "Mean rate = mass lost ÷ time = 3.0 ÷ 60 = 0.05 g/s." },
      { g: 5, marks: 2, q: "When ammonium chloride is heated in a test tube, a white solid reappears near the cool top of the tube. Explain why.", scheme: ["On heating, ammonium chloride decomposes into ammonia and hydrogen chloride gases", "At the cool top the gases react together to re-form ammonium chloride (the reaction is reversible)"], answer: "Heating breaks ammonium chloride down into ammonia and hydrogen chloride gases. When these reach the cooler top of the tube they react together again to re-form solid ammonium chloride, because the reaction is reversible." },
      { g: 5, marks: 2, q: "The forward reaction of a reversible reaction is exothermic. What can you say about the reverse reaction?", scheme: ["It is endothermic", "It transfers the same amount of energy"], answer: "The reverse reaction is endothermic, and it takes in exactly the same amount of energy as the forward reaction releases." },
      { g: 5, marks: 2, q: "Explain why increasing the pressure of reacting gases increases the rate of reaction.", scheme: ["The same number of particles are in a smaller volume (closer together)", "So collisions are more frequent"], answer: "At higher pressure the same number of gas particles are squeezed into a smaller volume, so they are closer together and collide more frequently." },
      { g: 5, marks: 2, q: "Describe how the rate of a reaction changes as the reaction goes on, and explain why.", scheme: ["The rate is fastest at the start and then slows down until it stops", "Because reactants are used up, so there are fewer reactant particles to collide"], answer: "The reaction is fastest at the start and then slows down until it stops, because the reactants are being used up, so there are fewer particles to collide." },
      { g: 5, marks: 2, q: "On a graph of volume of gas produced against time, what does the steepness of the line show, and what does it mean when the line becomes horizontal?", scheme: ["The steeper the line (gradient), the faster the rate", "A horizontal line means the reaction has stopped (rate is zero)"], answer: "The steeper the gradient, the faster the reaction. When the line becomes horizontal no more gas is being made, so the reaction has stopped." },
      { g: 5, marks: 2, q: "In the reaction between sodium thiosulfate and hydrochloric acid the mixture goes cloudy. Name the substance that causes the cloudiness and describe how this can be used to measure the rate.", scheme: ["Sulfur (a solid precipitate)", "Time how long it takes for a cross drawn under the flask to disappear from view"], answer: "The cloudiness is caused by a precipitate of sulfur. You time how long it takes for a cross drawn on paper under the flask to disappear from view — the shorter the time, the faster the reaction." },
      { g: 5, marks: 3, q: "Hydrogen peroxide decomposes slowly into water and oxygen. When a little manganese(IV) oxide is added, oxygen is produced much faster, and the same mass of manganese(IV) oxide can be recovered at the end. Explain what this shows.", scheme: ["Manganese(IV) oxide is a catalyst for the reaction", "It increases the rate of the reaction", "It is not used up, as its mass is unchanged"], answer: "It shows manganese(IV) oxide is a catalyst: it increases the rate at which hydrogen peroxide decomposes, but it is not used up because the same mass is recovered at the end." },
      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 3, q: "In a reaction, the total volume of hydrogen collected was 18 cm³ after 10 s, 30 cm³ after 20 s and 38 cm³ after 30 s. Calculate the mean rate of reaction between 10 s and 30 s.", scheme: ["Volume produced = 38 − 18 = 20 cm³", "Time taken = 30 − 10 = 20 s", "Mean rate = 20 ÷ 20 = 1.0 cm³/s"], answer: "Volume produced = 38 − 18 = 20 cm³ in 30 − 10 = 20 s, so mean rate = 20 ÷ 20 = 1.0 cm³/s." },
      { g: 6, marks: 3, q: "Explain, using collision theory, why a reaction is faster at a higher temperature.", scheme: ["Particles have more (kinetic) energy and move faster", "So they collide more frequently", "And a greater proportion of collisions have energy equal to or greater than the activation energy (more successful collisions)"], answer: "At a higher temperature the particles have more energy and move faster, so they collide more frequently. A greater proportion of the collisions also have at least the activation energy, so more collisions are successful." },
      { g: 6, marks: 2, q: "In the disappearing cross experiment, explain why 1/time can be used as a measure of the rate of reaction.", scheme: ["The same amount of sulfur (cloudiness) must form each time for the cross to disappear", "So the shorter the time, the faster the rate — rate is proportional to 1/time"], answer: "The cross disappears when the same amount of sulfur has formed each time, so the shorter the time taken, the faster the reaction; rate is therefore proportional to 1/time." },
      { g: 6, marks: 3, q: "A student timed how long a cross took to disappear in the sodium thiosulfate reaction. At one concentration it took 80 s; at a higher concentration it took 40 s. Calculate 1/time for each and state how the rate changed.", scheme: ["1 ÷ 80 = 0.0125 /s", "1 ÷ 40 = 0.025 /s", "The rate doubled at the higher concentration"], answer: "1 ÷ 80 = 0.0125 /s and 1 ÷ 40 = 0.025 /s, so the rate doubled at the higher concentration." },
      { g: 6, marks: 4, q: "Describe a method to investigate how the concentration of hydrochloric acid affects the rate of its reaction with magnesium ribbon by measuring the volume of gas produced.", scheme: ["Add a measured length (mass) of magnesium ribbon to a measured volume of acid in a conical flask", "Connect the flask to a gas syringe (or an upturned measuring cylinder in water)", "Record the volume of hydrogen at regular time intervals (e.g. every 10 s)", "Repeat with different concentrations, keeping the volume of acid, length of magnesium and temperature the same"], answer: "Put a measured volume of acid in a conical flask, add a measured length of magnesium ribbon and immediately connect a gas syringe. Record the volume of hydrogen every 10 seconds. Repeat with different acid concentrations, keeping the volume of acid, the length of magnesium and the temperature the same." },
      { g: 6, marks: 3, q: "Describe how you could use a balance to find the mean rate of reaction between marble chips and hydrochloric acid.", scheme: ["Put the flask containing the acid and marble chips on a balance (with cotton wool in the neck to stop acid spray but let gas out)", "Record the mass at the start and after a measured time (or at regular intervals)", "Mean rate = mass lost ÷ time, in g/s"], answer: "Place the flask of acid and marble chips on a balance with a cotton wool plug in the neck. Record the mass at the start and after a measured time as carbon dioxide escapes, then calculate mean rate = mass lost ÷ time in g/s." },
      { g: 6, marks: 3, q: "When blue hydrated copper sulfate is heated it turns white. When water is added to the white solid it turns blue again and the mixture gets hot. Explain what these observations show.", scheme: ["The reaction is reversible", "The forward reaction (heating/removing water) is endothermic", "The reverse reaction (adding water) is exothermic and transfers the same amount of energy"], answer: "They show the reaction is reversible. Removing the water by heating is endothermic, while adding water back is exothermic, releasing the same amount of energy that was taken in." },
      { g: 6, marks: 3, q: "A student says: 'At equilibrium the reaction has stopped and there are equal amounts of reactants and products.' Explain what is wrong with this statement.", scheme: ["The reactions have not stopped: the forward and reverse reactions are still happening", "They happen at the same rate (dynamic equilibrium)", "The amounts of reactants and products stay constant but are not necessarily equal"], answer: "The reactions have not stopped — both the forward and reverse reactions continue, but at the same rate, which is why it is called dynamic. The amounts of reactants and products stay constant, but they do not have to be equal." },
      { g: 6, marks: 2, q: "Explain why food goes off more slowly in a fridge than on a kitchen worktop.", scheme: ["At a lower temperature particles have less energy and move more slowly", "So there are fewer (successful) collisions and the reactions that spoil food are slower"], answer: "In a fridge the temperature is lower, so particles have less energy and move more slowly. There are fewer successful collisions, so the reactions that make food go off happen more slowly." },
      { g: 6, marks: 3, q: "For the reversible reaction A ⇌ B, the forward reaction is exothermic. State and explain the effect of increasing the temperature on the amount of B at equilibrium.", scheme: ["The amount of B decreases", "Increasing the temperature favours the endothermic reaction", "The reverse reaction is endothermic, so the equilibrium shifts to the left (towards A)"], answer: "The amount of B decreases. Increasing the temperature favours the endothermic direction, which here is the reverse reaction, so the position of equilibrium shifts towards A." },
      { g: 6, marks: 2, q: "State Le Chatelier's principle.", scheme: ["If a system at equilibrium is subjected to a change in conditions", "The position of equilibrium shifts to counteract (oppose) the change"], answer: "If a system at equilibrium is subjected to a change in conditions, the position of equilibrium shifts to counteract the change." },
      { g: 6, marks: 3, q: "Ammonia is made in the reversible reaction N₂(g) + 3H₂(g) ⇌ 2NH₃(g). Explain the effect of increasing the pressure on the yield of ammonia.", scheme: ["The yield of ammonia increases", "Increasing pressure shifts the equilibrium towards the side with fewer molecules of gas", "There are 4 molecules of gas on the left and 2 on the right, so the equilibrium shifts to the right"], answer: "The yield of ammonia increases. Increasing the pressure shifts the equilibrium towards the side with fewer gas molecules; there are 4 molecules on the left and only 2 on the right, so it shifts to the right." },
      { g: 6, marks: 2, q: "Some of the product is removed from a reaction mixture at equilibrium. State and explain what happens.", scheme: ["More reactants react to make product / the position of equilibrium shifts to the right", "This replaces the product that was removed (opposes the change) until equilibrium is reached again"], answer: "The equilibrium shifts to the right: more reactants react to form product, replacing what was removed and opposing the change, until equilibrium is reached again." },
      { g: 6, marks: 2, q: "Explain why solid catalysts are often used as fine powders or meshes.", scheme: ["This gives the catalyst a larger surface area", "So more reactant particles can collide with / react on the catalyst at the same time, increasing the rate"], answer: "A powder or mesh has a much larger surface area, so more reactant particles can collide with the catalyst surface at once, making it more effective at increasing the rate." },
      { g: 6, marks: 2, q: "Give two reasons why manufacturers often use a catalyst rather than simply raising the temperature to speed up a reaction.", scheme: ["Raising the temperature needs more energy, which is expensive (and uses more fuel)", "A catalyst speeds up the reaction without being used up, so it can be reused"], answer: "Heating to a higher temperature uses more energy and costs more money, whereas a catalyst speeds up the reaction without being used up, so the same catalyst can be used again and again." },
      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "A 2 cm × 2 cm × 2 cm cube of calcium carbonate is cut into eight 1 cm cubes. Calculate the total surface area before and after cutting, and explain the effect on the rate of reaction with acid.", scheme: ["Before: 6 × (2 × 2) = 24 cm²", "After: 8 × 6 × (1 × 1) = 48 cm²", "Surface area has doubled, so more particles are exposed and collisions are more frequent — faster rate"], answer: "Before: 6 × 4 = 24 cm². After: 8 cubes × 6 faces × 1 cm² = 48 cm². The surface area doubles, so more particles are exposed to the acid, collisions are more frequent and the reaction is faster." },
      { g: 7, marks: 4, q: "The total volume of carbon dioxide collected in a reaction was: 0 cm³ at 0 s, 30 cm³ at 20 s, 48 cm³ at 40 s, 56 cm³ at 60 s, 60 cm³ at 80 s and 60 cm³ at 100 s. Calculate the mean rate over the first 20 s and between 40 s and 80 s, and explain the difference.", scheme: ["First 20 s: 30 ÷ 20 = 1.5 cm³/s", "40–80 s: (60 − 48) ÷ 40 = 0.3 cm³/s", "The rate is slower later because the reactants are being used up", "So the concentration of acid is lower and collisions are less frequent"], answer: "Over the first 20 s: 30 ÷ 20 = 1.5 cm³/s. Between 40 s and 80 s: (60 − 48) ÷ 40 = 0.3 cm³/s. The rate falls because the reactants are being used up, so there are fewer acid particles per unit volume and collisions are less frequent." },
      { g: 7, marks: 3, q: "0.12 g of magnesium ribbon reacts completely with excess hydrochloric acid in 40 s. Calculate the mean rate of reaction in mol/s. (Ar of Mg = 24)", scheme: ["Moles of Mg = 0.12 ÷ 24 = 0.005 mol", "Mean rate = 0.005 ÷ 40", "= 1.25 × 10⁻⁴ mol/s (0.000125 mol/s)"], answer: "Moles of magnesium = 0.12 ÷ 24 = 0.005 mol. Mean rate = 0.005 ÷ 40 = 1.25 × 10⁻⁴ mol/s." },
      { g: 7, marks: 3, q: "A tangent is drawn to a curve of volume of gas against time at 30 s. The tangent passes through the points (10 s, 20 cm³) and (50 s, 60 cm³). Calculate the rate of reaction at 30 s.", scheme: ["Change in volume = 60 − 20 = 40 cm³", "Change in time = 50 − 10 = 40 s", "Rate = gradient = 40 ÷ 40 = 1.0 cm³/s"], answer: "The rate is the gradient of the tangent: (60 − 20) ÷ (50 − 10) = 40 ÷ 40 = 1.0 cm³/s." },
      { g: 7, marks: 3, q: "A small rise in temperature can make a reaction much faster, even though the particles only collide slightly more often. Explain why.", scheme: ["Particles move faster, so collisions are slightly more frequent", "More importantly, many more particles now have energy equal to or greater than the activation energy", "So a much greater proportion of collisions are successful"], answer: "The particles move a little faster and collide slightly more often, but the main effect is that many more particles now have at least the activation energy, so a much greater proportion of the collisions are successful." },
      { g: 7, marks: 4, q: "Describe how to investigate the effect of the concentration of sodium thiosulfate solution on the rate of its reaction with hydrochloric acid using the disappearing cross method.", scheme: ["Put a measured volume of sodium thiosulfate solution in a conical flask on a piece of paper marked with a cross", "Add a measured volume of hydrochloric acid, swirl and start a timer", "Stop the timer when the cross can no longer be seen through the solution (looking from above)", "Repeat with different concentrations (dilute with water), keeping the total volume, acid volume and concentration, and temperature the same"], answer: "Place a conical flask containing a measured volume of sodium thiosulfate solution on a cross drawn on paper. Add a measured volume of hydrochloric acid, swirl and start the timer, stopping it when the cross disappears when viewed from above. Repeat using thiosulfate diluted with water to different concentrations, keeping the total volume, the acid and the temperature the same." },
      { g: 7, marks: 3, q: "Suggest two weaknesses of timing the disappearing cross by eye and describe an improvement.", scheme: ["Deciding when the cross has disappeared is a judgement that varies between people", "Human reaction time when starting and stopping the timer", "Use a light sensor (data logger) to record when the light passing through falls to a set level"], answer: "Judging exactly when the cross disappears is subjective and differs between people, and reaction time affects starting and stopping the timer. A light sensor and data logger could measure when the light passing through the mixture falls to a set level." },
      { g: 7, marks: 3, q: "A student adds 1.0 g of copper powder to zinc and dilute sulfuric acid. Hydrogen is produced much faster than without copper. After the reaction, the copper is filtered, washed, dried and weighed: its mass is 1.0 g. Explain whether copper is acting as a catalyst.", scheme: ["Yes, copper is acting as a catalyst", "Because the rate of hydrogen production increased", "And the mass of copper is unchanged, so it was not used up"], answer: "Copper is acting as a catalyst: it increased the rate at which hydrogen was produced, and its mass was still 1.0 g afterwards, showing it was not used up in the reaction." },
      { g: 7, marks: 4, q: "Colourless dinitrogen tetroxide forms brown nitrogen dioxide in a reversible reaction: N₂O₄(g) ⇌ 2NO₂(g). The forward reaction is endothermic. Predict and explain what you would see when a sealed tube of the equilibrium mixture is placed in hot water.", scheme: ["The gas mixture becomes darker brown", "Increasing the temperature favours the endothermic direction", "The endothermic direction is the forward reaction, so the equilibrium shifts to the right", "So more brown NO₂ is formed"], answer: "The mixture turns darker brown. Raising the temperature shifts the equilibrium in the endothermic direction, which is the forward reaction, so more brown nitrogen dioxide forms." },
      { g: 7, marks: 3, q: "For the reaction H₂(g) + I₂(g) ⇌ 2HI(g), explain why changing the pressure has no effect on the position of equilibrium.", scheme: ["There are 2 molecules of gas on the left-hand side", "There are 2 molecules of gas on the right-hand side", "A pressure change shifts the equilibrium towards fewer gas molecules, but both sides have the same number, so there is no shift"], answer: "There are two gas molecules on each side of the equation. A change in pressure only shifts an equilibrium towards the side with fewer gas molecules, so with equal numbers on both sides the position does not change." },
      { g: 7, marks: 4, q: "Methanol is made by the reaction CO(g) + 2H₂(g) ⇌ CH₃OH(g). The forward reaction is exothermic. Explain what temperature and pressure would give the highest equilibrium yield of methanol.", scheme: ["A low temperature", "Because the forward reaction is exothermic, so lowering the temperature shifts the equilibrium to the right", "A high pressure", "Because there are fewer gas molecules on the right (3 on the left, 1 on the right)"], answer: "A low temperature, because the forward reaction is exothermic so lowering the temperature shifts the equilibrium towards methanol; and a high pressure, because there are 3 gas molecules on the left but only 1 on the right, so high pressure shifts the equilibrium to the right." },
      { g: 7, marks: 3, q: "Yellow chromate ions react with hydrogen ions to form orange dichromate ions: 2CrO₄²⁻ + 2H⁺ ⇌ Cr₂O₇²⁻ + H₂O. Predict and explain the colour change when acid is added to the yellow solution.", scheme: ["The solution turns orange", "Adding acid increases the concentration of H⁺ ions, a reactant", "The equilibrium shifts to the right to use up the added H⁺, forming more orange dichromate ions"], answer: "The solution turns orange. Adding acid increases the concentration of H⁺ ions, so the equilibrium shifts to the right to oppose the change, producing more orange dichromate ions." },
      { g: 7, marks: 4, q: "For a reaction, the reactants have an energy of 50 kJ and the products 20 kJ. Without a catalyst the highest energy on the reaction pathway is 170 kJ; with a catalyst it is 110 kJ. Calculate the activation energy with and without the catalyst and the overall energy change.", scheme: ["Activation energy without catalyst = 170 − 50 = 120 kJ", "Activation energy with catalyst = 110 − 50 = 60 kJ", "Overall energy change = 20 − 50 = −30 kJ (30 kJ released, exothermic)", "The overall energy change is the same with or without the catalyst"], answer: "Without the catalyst the activation energy is 170 − 50 = 120 kJ; with it, 110 − 50 = 60 kJ. The overall energy change is 20 − 50 = −30 kJ, so 30 kJ is released (exothermic) in both cases — the catalyst does not change it." },
      { g: 7, marks: 3, q: "Explain why an exothermic reaction with a very high activation energy may happen extremely slowly at room temperature.", scheme: ["Very few particles have energy equal to or greater than the activation energy", "So very few collisions are successful", "Being exothermic describes the overall energy change, not how fast the reaction goes"], answer: "With a very high activation energy, very few particles have enough energy when they collide, so very few collisions are successful. Being exothermic only tells you energy is released overall — it says nothing about how fast the reaction is." },
      { g: 7, marks: 3, q: "A spark can make fine flour dust in the air of a factory explode, but a heap of flour only burns slowly. Explain why.", scheme: ["Flour dust spread in the air has a much larger surface area than a heap", "So far more flour particles are exposed to oxygen and collisions are much more frequent", "The reaction is so fast that energy and hot gases are released almost instantly, causing an explosion"], answer: "Dust spread through air has an enormous surface area compared with a heap, so far more flour particles are in contact with oxygen and collisions are much more frequent. The combustion is so fast that energy and hot gases are released almost instantly, causing an explosion." },
      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "A flask containing marble chips and hydrochloric acid lost 1.32 g of carbon dioxide in 120 s (CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂). Calculate the mean rate of reaction in g/s and in mol/s of carbon dioxide produced. (Mr of CO₂ = 44)", scheme: ["Mean rate = 1.32 ÷ 120 = 0.011 g/s", "Moles of CO₂ = 1.32 ÷ 44 = 0.030 mol", "Mean rate = 0.030 ÷ 120", "= 2.5 × 10⁻⁴ mol/s"], answer: "Mean rate = 1.32 ÷ 120 = 0.011 g/s. Moles of CO₂ = 1.32 ÷ 44 = 0.030 mol, so mean rate = 0.030 ÷ 120 = 2.5 × 10⁻⁴ mol/s." },
      { g: 8, marks: 4, q: "A reaction produced 96 cm³ of hydrogen in the first 40 s. Calculate the mean rate of reaction in mol/s. (1 mol of any gas occupies 24 dm³ at room temperature and pressure)", scheme: ["96 cm³ = 0.096 dm³", "Moles of H₂ = 0.096 ÷ 24 = 0.004 mol", "Mean rate = 0.004 ÷ 40", "= 1.0 × 10⁻⁴ mol/s"], answer: "96 cm³ = 0.096 dm³, so moles of hydrogen = 0.096 ÷ 24 = 0.004 mol. Mean rate = 0.004 ÷ 40 = 1.0 × 10⁻⁴ mol/s." },
      { g: 8, marks: 4, q: "On a curve of volume of gas against time, the tangent at 20 s passes through (0 s, 12 cm³) and (40 s, 52 cm³), and the tangent at 60 s passes through (20 s, 50 cm³) and (100 s, 70 cm³). Calculate the rate at each time and explain the difference.", scheme: ["Rate at 20 s = (52 − 12) ÷ (40 − 0) = 1.0 cm³/s", "Rate at 60 s = (70 − 50) ÷ (100 − 20) = 0.25 cm³/s", "The rate decreases as the reaction goes on", "Because reactants are used up, so their concentration falls and collisions are less frequent"], answer: "At 20 s the rate is (52 − 12) ÷ 40 = 1.0 cm³/s; at 60 s it is (70 − 50) ÷ 80 = 0.25 cm³/s. The reaction slows down because the reactants are being used up, so there are fewer reactant particles per unit volume and collisions become less frequent." },
      { g: 8, marks: 4, q: "Two experiments use the same mass of magnesium ribbon with excess hydrochloric acid, one with 1.0 mol/dm³ acid and one with 2.0 mol/dm³ acid. Explain the differences you would expect in the rate and in the total volume of hydrogen produced.", scheme: ["The 2.0 mol/dm³ acid has more acid particles per unit volume", "So collisions are more frequent and the initial rate is faster (steeper curve)", "Magnesium is the limiting reactant and the same mass is used in both", "So the same total volume of hydrogen is produced; the faster reaction just finishes sooner"], answer: "The more concentrated acid has more particles per unit volume, so collisions are more frequent and the reaction starts faster. However, magnesium is the limiting reactant and the same mass is used, so both produce the same total volume of hydrogen — the faster reaction simply finishes sooner." },
      { g: 8, marks: 4, q: "A student repeats a reaction using the same volume of hydrochloric acid at half the concentration, with magnesium in excess. Predict and explain how both the rate and the total volume of hydrogen will change.", scheme: ["The rate decreases (less steep curve)", "There are fewer acid particles per unit volume, so collisions are less frequent", "The total volume of hydrogen halves", "Because the acid is now the limiting reactant and only half the number of moles of acid is present"], answer: "The reaction is slower, because there are half as many acid particles per unit volume so collisions are less frequent. The total volume of hydrogen also halves, because the acid is the limiting reactant and there are only half as many moles of it to react." },
      { g: 8, marks: 4, q: "Sulfur trioxide is made by 2SO₂(g) + O₂(g) ⇌ 2SO₃(g). The forward reaction is exothermic. Explain why a moderate temperature of about 450 °C is used rather than a much lower temperature.", scheme: ["A lower temperature would give a higher equilibrium yield of SO₃ because the forward reaction is exothermic", "But at a low temperature the rate of reaction would be too slow", "A higher temperature gives a faster rate but a lower equilibrium yield", "So a compromise temperature gives an acceptable yield in a reasonable time"], answer: "Because the forward reaction is exothermic, a lower temperature would shift the equilibrium to the right and give a higher yield, but the reaction would be far too slow. A higher temperature is faster but lowers the yield, so a compromise temperature is chosen to give an acceptable yield quickly enough." },
      { g: 8, marks: 4, q: "For CO(g) + 2H₂(g) ⇌ CH₃OH(g), a very high pressure would give the greatest yield of methanol. Explain why manufacturers use a lower, compromise pressure instead.", scheme: ["High pressure increases the yield (3 gas molecules → 1) and the rate", "But producing very high pressures needs a lot of energy, which is expensive", "The plant would need very strong, expensive pipes and vessels", "Very high pressures are dangerous (risk of explosion or leaks)"], answer: "A high pressure does increase both the yield, because there are fewer gas molecules on the right, and the rate. However, very high pressures need a lot of energy to produce, require very strong and expensive equipment, and increase the risk of dangerous explosions or leaks, so a compromise pressure is used." },
      { g: 8, marks: 4, q: "Explain why adding a catalyst to a reversible reaction does not change the equilibrium yield, yet is still very useful to a manufacturer.", scheme: ["A catalyst increases the rates of the forward and reverse reactions equally", "So the position of equilibrium (and the yield) does not change", "But equilibrium is reached much more quickly", "So product is made faster, or a lower temperature can be used, saving time, energy and money"], answer: "A catalyst speeds up the forward and reverse reactions equally, so the position of equilibrium and the yield are unchanged. However, equilibrium is reached much faster, so product is made more quickly or at a lower temperature, saving time, energy and money." },
      { g: 8, marks: 4, q: "Pale yellow iron(III) ions react with colourless thiocyanate ions to form deep red ions: Fe³⁺ + SCN⁻ ⇌ FeSCN²⁺. Predict and explain the colour change when (a) more thiocyanate solution is added and (b) a substance that removes Fe³⁺ ions is added.", scheme: ["(a) The mixture becomes a deeper red", "Increasing the concentration of a reactant shifts the equilibrium to the right, forming more FeSCN²⁺", "(b) The mixture becomes paler (less red)", "Removing a reactant shifts the equilibrium to the left, so FeSCN²⁺ breaks down to replace the Fe³⁺"], answer: "(a) The red colour deepens, because adding a reactant shifts the equilibrium to the right, making more FeSCN²⁺. (b) The mixture becomes paler, because removing Fe³⁺ shifts the equilibrium to the left as FeSCN²⁺ ions break down to replace it." },
      { g: 8, marks: 4, q: "Phosphorus pentachloride decomposes in a reversible reaction: PCl₅(g) ⇌ PCl₃(g) + Cl₂(g). Explain the effect of increasing the pressure on the amount of chlorine in the equilibrium mixture.", scheme: ["The amount of chlorine decreases", "Increasing the pressure shifts the equilibrium towards the side with fewer gas molecules", "There is 1 gas molecule on the left and 2 on the right", "So the equilibrium shifts to the left, forming more PCl₅"], answer: "The amount of chlorine decreases. Higher pressure shifts the equilibrium towards the side with fewer gas molecules; there is one molecule on the left and two on the right, so the equilibrium moves left, forming more PCl₅." },
      { g: 8, marks: 5, q: "Hydrogen is made by CH₄(g) + H₂O(g) ⇌ CO(g) + 3H₂(g). The forward reaction is endothermic. Explain the effect on the equilibrium yield of hydrogen of increasing the temperature and of increasing the pressure, and suggest why a catalyst is used.", scheme: ["Increasing the temperature increases the yield of hydrogen", "Because the forward reaction is endothermic, so the equilibrium shifts to the right", "Increasing the pressure decreases the yield of hydrogen", "Because the equilibrium shifts towards fewer gas molecules: 2 on the left, 4 on the right", "A catalyst increases the rate so equilibrium is reached faster (without changing the yield)"], answer: "A higher temperature increases the yield, because the forward reaction is endothermic and is favoured by heating. A higher pressure decreases the yield, because the equilibrium shifts towards the side with fewer gas molecules — 2 on the left compared with 4 on the right. A catalyst is used so that equilibrium is reached more quickly, although it does not change the yield." },
      { g: 8, marks: 4, q: "Explain, in terms of particles and energy, how a catalyst increases the rate of a reaction and why increasing the temperature increases the rate in two ways.", scheme: ["A catalyst provides an alternative pathway with a lower activation energy", "So more collisions have enough energy to react at the same temperature", "Increasing the temperature gives particles more energy, so more collisions exceed the activation energy", "Particles also move faster, so collisions are more frequent"], answer: "A catalyst provides a different pathway with a lower activation energy, so at the same temperature more collisions have enough energy to be successful. Raising the temperature gives the particles more energy, so more collisions exceed the activation energy, and also makes them move faster, so they collide more often." },
      { g: 8, marks: 4, q: "Equal masses of small and large marble chips were each reacted with the same volume and concentration of excess acid. The small chips produced 60 cm³ of gas in 30 s; the large chips produced 60 cm³ of gas in 90 s. Calculate the mean rate for each and explain the difference.", scheme: ["Small chips: 60 ÷ 30 = 2.0 cm³/s", "Large chips: 60 ÷ 90 = 0.67 cm³/s", "The reaction with small chips is 3 times faster", "Small chips have a larger total surface area, so more particles are exposed and collisions are more frequent"], answer: "Small chips: 60 ÷ 30 = 2.0 cm³/s; large chips: 60 ÷ 90 = 0.67 cm³/s, so the small chips react 3 times faster. The same mass of smaller chips has a larger total surface area, so more particles are exposed to the acid and collisions are more frequent." },
      { g: 8, marks: 4, q: "Explain why food lasts longer in a freezer, and why some foods are sealed in packets filled with nitrogen instead of air.", scheme: ["In a freezer the low temperature means particles have less energy", "So there are fewer successful collisions and the reactions that spoil food are slower", "Filling packets with nitrogen removes most of the oxygen (lowers its concentration)", "So there are fewer collisions with oxygen particles, slowing the oxidation reactions"], answer: "In a freezer the particles have much less energy, so there are fewer successful collisions and the reactions that spoil food slow right down. Replacing the air with nitrogen lowers the concentration of oxygen, so there are far fewer collisions between food molecules and oxygen, slowing oxidation." },
      { g: 8, marks: 4, q: "The time taken to make a fixed amount of product was 120 s at 20 °C, 60 s at 30 °C and 30 s at 40 °C. Calculate 1/time at each temperature, describe the pattern and explain it.", scheme: ["20 °C: 1 ÷ 120 = 0.0083 /s; 30 °C: 1 ÷ 60 = 0.017 /s", "40 °C: 1 ÷ 30 = 0.033 /s", "The rate doubles for every 10 °C rise in temperature", "Particles have more energy, so collisions are more frequent and many more have at least the activation energy"], answer: "1/time = 0.0083 /s at 20 °C, 0.017 /s at 30 °C and 0.033 /s at 40 °C, so the rate doubles for every 10 °C rise. At higher temperatures particles move faster and collide more often, and a much greater proportion of collisions have at least the activation energy." },
      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "A student reacted 0.24 g of magnesium with excess hydrochloric acid (Mg + 2HCl → MgCl₂ + H₂). The total volume of hydrogen was 0 cm³ at 0 s, 100 cm³ at 15 s, 170 cm³ at 30 s, 215 cm³ at 45 s, 240 cm³ at 60 s and 240 cm³ at 75 s. Calculate the mean rate over the first 30 s in cm³/s and in mol/s, show that the final volume matches the mass of magnesium, and explain the pattern in the results. (Ar Mg = 24; 1 mol of gas = 24 dm³)", scheme: ["Mean rate = 170 ÷ 30 = 5.7 cm³/s", "170 cm³ = 0.170 dm³; moles = 0.170 ÷ 24 = 0.0071 mol", "Mean rate = 0.0071 ÷ 30 = 2.4 × 10⁻⁴ mol/s", "Moles of Mg = 0.24 ÷ 24 = 0.010 mol, giving 0.010 mol H₂ (1:1 ratio)", "Volume = 0.010 × 24 = 0.24 dm³ = 240 cm³, matching the final reading", "The rate slows as magnesium is used up (fewer particles to collide) and stops when all the magnesium has reacted"], answer: "Over the first 30 s the mean rate is 170 ÷ 30 = 5.7 cm³/s. 170 cm³ = 0.170 dm³ = 0.170 ÷ 24 = 0.0071 mol, so the rate is 0.0071 ÷ 30 = 2.4 × 10⁻⁴ mol/s. Moles of magnesium = 0.24 ÷ 24 = 0.010 mol, which gives 0.010 mol of hydrogen, or 0.010 × 24 = 0.24 dm³ = 240 cm³ — exactly the final volume. The rate is fastest at the start and slows as the magnesium is used up, so there are fewer collisions, until it stops once all the magnesium has reacted." },
      { g: 9, marks: 6, q: "Methane can be made from carbon dioxide and hydrogen: CO₂(g) + 4H₂(g) ⇌ CH₄(g) + 2H₂O(g). The forward reaction is exothermic. Evaluate the choice of temperature, pressure and catalyst that a manufacturer should use.", scheme: ["A low temperature would increase the equilibrium yield because the forward reaction is exothermic", "But the rate would be too slow, so a compromise (moderate) temperature is needed", "A high pressure increases the yield because there are 5 gas molecules on the left and 3 on the right", "A high pressure also increases the rate because gas particles are closer, so collide more frequently", "But high pressures are expensive (energy and strong equipment) and hazardous, so a compromise pressure is used", "A catalyst increases the rate so equilibrium is reached quickly at a lower temperature without changing the yield — a justified overall conclusion"], answer: "Because the forward reaction is exothermic, a low temperature gives a higher yield, but the reaction would be too slow, so a compromise temperature is best. High pressure increases the yield, as 5 gas molecules become 3, and also speeds up the reaction, but it is expensive in energy and equipment and more dangerous, so a compromise pressure makes sense. A catalyst lets equilibrium be reached quickly at a lower temperature without affecting the yield. Overall, a moderate temperature, a fairly high but affordable pressure and a catalyst give a good yield at an acceptable rate and cost." },
      { g: 9, marks: 6, q: "Explain fully, using collision theory, how concentration, pressure, surface area, temperature and catalysts each affect the rate of a reaction, and why temperature has a larger effect than you might expect.", scheme: ["Reactions only happen when particles collide with energy at least equal to the activation energy", "Higher concentration or pressure: more particles in the same volume, so more frequent collisions", "Larger surface area: more particles exposed to the other reactant, so more frequent collisions", "Higher temperature: particles move faster, so collisions are more frequent", "Higher temperature also makes collisions more energetic, so a greater proportion are successful — the bigger effect", "Catalyst: provides a pathway with a lower activation energy, so more collisions are successful without raising the temperature"], answer: "Particles react only when they collide with at least the activation energy. Increasing concentration or pressure puts more particles in the same volume, and increasing surface area exposes more particles, so in each case collisions become more frequent. Raising the temperature makes particles move faster, so they collide more often, but it also makes the collisions more energetic, so a much greater proportion are successful — which is why temperature has such a large effect. A catalyst provides an alternative pathway with a lower activation energy, so more collisions succeed at the same temperature." },
      { g: 9, marks: 5, q: "The reaction Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S + H₂O is usually followed with the disappearing cross method. A student suggests collecting the sulfur dioxide gas in a gas syringe instead. Evaluate this suggestion.", scheme: ["Sulfur dioxide is a gas product, so its volume could in principle be measured over time", "But sulfur dioxide is very soluble in water, so much of it would dissolve and the volumes would be inaccurate", "Sulfur dioxide is toxic, so it would need to be done in a fume cupboard / sealed apparatus", "The disappearing cross method is simple but judging the end point by eye is subjective", "Justified conclusion, e.g. keep measuring cloudiness but use a light sensor rather than collecting gas"], answer: "Sulfur dioxide is produced, so in principle its volume could be measured. However, it is very soluble in water, so much would dissolve in the reaction mixture and the volumes would be too low and unreliable, and it is toxic, requiring a fume cupboard. The disappearing cross method avoids these problems but relies on judging the end point by eye. The best approach is to keep measuring the cloudiness but use a light sensor to make it more accurate." },
      { g: 9, marks: 5, q: "In the equilibrium N₂O₄(g) ⇌ 2NO₂(g) the forward reaction is endothermic, while in 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) the forward reaction is exothermic. Explain why increasing the temperature has opposite effects on the yields of NO₂ and SO₃.", scheme: ["By Le Chatelier's principle the equilibrium shifts to oppose the temperature rise, i.e. to take in energy", "An increase in temperature therefore favours the endothermic direction", "For N₂O₄ ⇌ 2NO₂ the endothermic direction is forward, so the equilibrium shifts right and more NO₂ forms", "For 2SO₂ + O₂ ⇌ 2SO₃ the endothermic direction is the reverse, so the equilibrium shifts left and less SO₃ forms", "So raising the temperature increases the yield when the forward reaction is endothermic but decreases it when the forward reaction is exothermic"], answer: "An equilibrium responds to a temperature rise by shifting in the direction that takes in energy — the endothermic direction. For N₂O₄ ⇌ 2NO₂ this is the forward reaction, so the equilibrium shifts right and the yield of NO₂ increases. For the sulfur trioxide reaction the endothermic direction is the reverse reaction, so the equilibrium shifts left and the yield of SO₃ decreases." },
      { g: 9, marks: 6, q: "Excess marble chips were reacted with 20 cm³ of hydrochloric acid at 0.10, 0.20 and 0.40 mol/dm³ (CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂). In the first 10 s the volumes of CO₂ were 6, 12 and 24 cm³, and the final volumes were 24, 48 and 96 cm³. Calculate the mean rates, show by calculation the expected final volume for the 0.10 mol/dm³ acid, and explain the patterns. (1 mol of gas = 24 dm³)", scheme: ["Mean rates: 6 ÷ 10 = 0.6, 12 ÷ 10 = 1.2 and 24 ÷ 10 = 2.4 cm³/s", "Doubling the concentration doubles the rate (rate is proportional to concentration)", "Because twice as many acid particles in the same volume give twice as many collisions per second", "Moles of HCl = 0.10 × 0.020 = 0.0020 mol, so moles of CO₂ = 0.0020 ÷ 2 = 0.0010 mol", "Volume = 0.0010 × 24 = 0.024 dm³ = 24 cm³, matching the result", "The final volume doubles with concentration because the acid is the limiting reactant (marble in excess)"], answer: "The mean rates are 6 ÷ 10 = 0.6, 12 ÷ 10 = 1.2 and 24 ÷ 10 = 2.4 cm³/s, so doubling the concentration doubles the rate, because twice as many acid particles in the same volume collide twice as often. For 0.10 mol/dm³ acid, moles of HCl = 0.10 × 0.020 = 0.0020 mol, giving 0.0010 mol of CO₂ (2:1 ratio), which is 0.0010 × 24 = 0.024 dm³ = 24 cm³. The final volume doubles as the concentration doubles because the acid is the limiting reactant, so twice the moles of acid make twice the carbon dioxide." },
      { g: 9, marks: 5, q: "Evaluate the claim: 'Increasing the pressure always increases the yield of a reversible reaction involving gases.'", scheme: ["Increasing the pressure shifts the equilibrium towards the side with fewer gas molecules", "So the yield increases only if the products have fewer gas molecules, e.g. N₂ + 3H₂ ⇌ 2NH₃ (4 → 2)", "If the products have more gas molecules the yield decreases, e.g. PCl₅ ⇌ PCl₃ + Cl₂ (1 → 2)", "If both sides have the same number, e.g. H₂ + I₂ ⇌ 2HI, the yield does not change", "Conclusion: the claim is false — it depends on the number of gas molecules on each side (although higher pressure does always increase the rate of gas reactions)"], answer: "Higher pressure shifts an equilibrium towards the side with fewer gas molecules. This increases the yield for reactions like N₂ + 3H₂ ⇌ 2NH₃, where 4 molecules become 2, but decreases it for reactions like PCl₅ ⇌ PCl₃ + Cl₂, where 1 becomes 2, and has no effect for H₂ + I₂ ⇌ 2HI, where the numbers are equal. So the claim is false: the effect depends on the numbers of gas molecules, even though higher pressure does speed up gas reactions." },
      { g: 9, marks: 6, q: "A reversible reaction is started with only reactants in a sealed container. Explain how the rates of the forward and reverse reactions change over time until dynamic equilibrium is reached, and describe the mixture at equilibrium.", scheme: ["At the start only reactants are present, so the forward rate is at its highest and the reverse rate is zero", "As reactants are used up their concentration falls, so the forward rate decreases", "As products build up their concentration rises, so the reverse rate increases", "Eventually the forward and reverse rates become equal", "The concentrations of reactants and products then stay constant (but are not necessarily equal)", "Both reactions continue (dynamic), which is only possible in a closed system where nothing escapes"], answer: "At first only reactants are present, so the forward reaction is at its fastest and the reverse reaction cannot happen. As reactants are used up the forward rate falls, while the growing amount of product makes the reverse rate rise. Eventually the two rates become equal: dynamic equilibrium. Both reactions keep going, but because they cancel out the concentrations of reactants and products stay constant — not necessarily equal — which can only happen in a closed system." },
      { g: 9, marks: 5, q: "The same volume and concentration of hydrogen peroxide was decomposed four times, timing how long it took to make 45 cm³ of oxygen: no additive, 150 s; 0.50 g of powder X, 30 s; 0.50 g of powder Y, 90 s; 0.50 g of powder Z, 20 s. Afterwards 0.50 g of X, 0.50 g of Y and 0.30 g of Z were recovered. Evaluate which substance is the best catalyst.", scheme: ["Mean rates: none 45 ÷ 150 = 0.30; X 45 ÷ 30 = 1.5; Y 45 ÷ 90 = 0.50; Z 45 ÷ 20 = 2.25 cm³/s", "X increases the rate 5 times and Y about 1.7 times", "X and Y are recovered with unchanged mass, so both are catalysts", "Z gives the fastest rate but its mass decreased, so it is being used up — it reacts and is not a catalyst", "Conclusion: X is the most effective catalyst"], answer: "The mean rates are 0.30 cm³/s with no additive, 1.5 cm³/s with X, 0.50 cm³/s with Y and 2.25 cm³/s with Z. X and Y are both catalysts because their masses are unchanged, and X makes the reaction 5 times faster compared with about 1.7 times for Y. Z gives the fastest rate, but 0.20 g of it was used up, so it is reacting rather than acting as a catalyst. X is therefore the best catalyst." },
      { g: 9, marks: 5, q: "Methane burns in an exothermic reaction, yet a gas hob needs a spark to light it. Explain why, and explain how a catalyst could affect such a reaction.", scheme: ["Bonds in the reactants must be broken before the reaction can happen, which needs the activation energy (supplied by the spark)", "Once started, the energy released by the reaction provides the activation energy for more molecules, so it continues", "It is exothermic overall because the products have less energy than the reactants (more energy released making bonds than used breaking them)", "A catalyst would provide a pathway with a lower activation energy, so the reaction could happen at a lower temperature", "A catalyst would not change the overall amount of energy released"], answer: "Methane and oxygen molecules must have their bonds broken before new ones can form, so the reaction needs the activation energy, which the spark provides. Once started, the energy released keeps supplying the activation energy for more molecules. It is exothermic overall because more energy is released making the bonds in the products than is used breaking the bonds in the reactants. A catalyst would lower the activation energy so the reaction could happen at a lower temperature, but it would not change the overall energy released." },
      { g: 9, marks: 5, q: "For the reaction 2A(g) + B(g) ⇌ 2C(g) at constant pressure, the equilibrium yield of C was 60% at 200 °C, 45% at 300 °C and 30% at 400 °C. Deduce whether the forward reaction is exothermic or endothermic, and predict the effect of increasing the pressure on the yield.", scheme: ["The yield of C decreases as the temperature increases", "Increasing the temperature favours the endothermic direction, so the reverse reaction must be endothermic", "Therefore the forward reaction is exothermic", "There are 3 gas molecules on the left and 2 on the right", "So increasing the pressure shifts the equilibrium to the right and increases the yield of C"], answer: "The yield falls as the temperature rises. A temperature increase favours the endothermic direction, so the reverse reaction must be endothermic and the forward reaction is exothermic. There are 3 gas molecules on the left and 2 on the right, so increasing the pressure would shift the equilibrium to the right and increase the yield of C." },
      { g: 9, marks: 6, q: "Plan an investigation into how temperature affects the rate of reaction between sodium thiosulfate and hydrochloric acid, explaining how you would make it a fair test and process the results.", scheme: ["Warm the sodium thiosulfate solution to a range of temperatures (e.g. 20, 30, 40, 50 °C) in a water bath, checking with a thermometer", "Place the flask on a cross, add a fixed volume of acid and start the timer", "Stop the timer when the cross can no longer be seen", "Keep the volumes and concentrations of both solutions, the flask and the cross the same", "Repeat at each temperature and calculate a mean, ignoring anomalous results", "Calculate 1/time as the rate and plot rate against temperature to find the pattern"], answer: "Heat measured volumes of sodium thiosulfate solution to set temperatures such as 20, 30, 40 and 50 °C in a water bath, checking with a thermometer. Place the flask on a cross, add a fixed volume of hydrochloric acid, start the timer and stop it when the cross disappears. Keep the volumes and concentrations of both solutions, the flask and the cross the same so only temperature changes. Repeat each temperature, calculate a mean time ignoring anomalies, then work out 1/time as the rate and plot it against temperature." },
      { g: 9, marks: 5, q: "Evaluate using a gas syringe compared with measuring the loss in mass on a balance to follow the rate of the reaction between marble chips and hydrochloric acid.", scheme: ["Gas syringe: measures the volume of CO₂ directly and can be read to about 1 cm³", "But it has a limited capacity (e.g. 100 cm³), the plunger can stick and gas may leak", "Balance: easy to take regular readings (or data-log) while gas escapes through a cotton wool plug", "But mass changes are small, so a balance reading to at least 0.01 g is needed, and the method would not work well for a very light gas like hydrogen", "Justified conclusion, e.g. both work for CO₂; mass loss is simpler, but a gas syringe is more sensitive for small amounts of gas"], answer: "A gas syringe measures the volume of carbon dioxide directly and can be read to about 1 cm³, but it only holds a limited volume, the plunger can stick and gas can leak. Measuring mass loss is simple and readings can be data-logged, but the mass changes are small, so a sensitive balance is needed, and it would be poor for a light gas like hydrogen. For carbon dioxide both methods work: mass loss is simpler, while a gas syringe is more sensitive when only small amounts of gas are made." },
      { g: 9, marks: 6, q: "Explain how changing concentrations affects a reaction at equilibrium, and use this to explain how an industrial process can convert almost all of its reactants into product even when the equilibrium yield is low.", scheme: ["Le Chatelier: when a concentration is changed, the position of equilibrium shifts to oppose the change", "Increasing the concentration of a reactant shifts the equilibrium to the right, forming more product", "Removing product (e.g. by condensing it) lowers its concentration, so the equilibrium shifts right to replace it", "So reactants keep being converted into product as it is removed", "Unreacted reactants can be separated and recycled back into the reactor", "Over many passes almost all of the reactants are converted, despite a low yield in each pass"], answer: "If the concentration of a substance at equilibrium changes, the equilibrium shifts to oppose the change: adding reactant shifts it to the right, and removing product also shifts it to the right to replace what was removed. In industry the product can be removed continuously, for example by condensing it, so more reactants keep turning into product. The unreacted gases are then recycled back into the reactor, so over many passes nearly all of the reactants are converted, even though the yield in a single pass is low." },
      { g: 9, marks: 5, q: "Evaluate the importance of catalysts in making industrial chemical processes more sustainable.", scheme: ["Catalysts increase the rate, so products are made faster", "They allow lower temperatures (and pressures) to be used, reducing energy use, fossil fuel burning and CO₂ emissions", "They are not used up, so small amounts can be reused many times", "However, some catalysts are made from rare or expensive metals, and they can stop working (be poisoned by impurities) and need replacing", "Justified conclusion, e.g. benefits in energy savings far outweigh the costs, so catalysts make processes much more sustainable"], answer: "Catalysts speed up reactions and allow them to run at lower temperatures and pressures, which saves energy, reduces the burning of fossil fuels and cuts carbon dioxide emissions. Because they are not used up, small amounts can be reused many times. However, some are made from rare or expensive metals and can be poisoned by impurities, so they need replacing. Overall the large energy savings outweigh these drawbacks, so catalysts make processes considerably more sustainable." },
    ],
    "8. Chemical analysis": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "In chemistry, what is meant by a pure substance?", scheme: ["A single element or a single compound, not mixed with any other substance"], answer: "A single element or a single compound that is not mixed with any other substance." },
      { g: 4, marks: 1, q: "What is a formulation?", scheme: ["A mixture designed as a useful product, with each component in a measured quantity"], answer: "A mixture that has been designed as a useful product, made by mixing components in carefully measured quantities." },
      { g: 4, marks: 2, q: "Give two examples of formulations.", scheme: ["Any one of: paint, medicine, fuel, cleaning agent, alloy, fertiliser, food", "A second different example from the list"], answer: "Paints and medicines (also fuels, cleaning agents, alloys, fertilisers and foods)." },
      { g: 4, marks: 2, q: "Describe the test for hydrogen gas and give the result.", scheme: ["Hold a burning (lit) splint at the open end of the test tube", "The gas burns with a (squeaky) pop"], answer: "Hold a burning splint at the open end of a test tube of the gas — hydrogen burns rapidly with a squeaky pop." },
      { g: 4, marks: 2, q: "Describe the test for oxygen gas and give the result.", scheme: ["Put a glowing splint into a test tube of the gas", "The splint relights"], answer: "Insert a glowing splint into a test tube of the gas — oxygen relights the splint." },
      { g: 4, marks: 2, q: "Name the solution used to test for carbon dioxide and state the positive result.", scheme: ["Limewater (calcium hydroxide solution)", "Turns milky / cloudy"], answer: "Limewater (calcium hydroxide solution), which turns milky (cloudy) when carbon dioxide is bubbled through it." },
      { g: 4, marks: 1, q: "What happens to damp litmus paper when it is put into chlorine gas?", scheme: ["It is bleached / turns white"], answer: "It is bleached and turns white." },
      { g: 4, marks: 1, q: "In paper chromatography, what is the stationary phase?", scheme: ["The paper"], answer: "The paper." },
      { g: 4, marks: 1, q: "In paper chromatography, what is the mobile phase?", scheme: ["The solvent"], answer: "The solvent, which moves up the paper." },
      { g: 4, marks: 1, q: "What colour flame do sodium ions produce in a flame test?", scheme: ["Yellow"], answer: "Yellow." },
      { g: 4, marks: 1, q: "What colour flame do potassium ions produce in a flame test?", scheme: ["Lilac"], answer: "Lilac." },
      { g: 4, marks: 1, q: "What colour precipitate forms when sodium hydroxide solution is added to a solution of copper(II) ions?", scheme: ["Blue"], answer: "A blue precipitate." },
      { g: 4, marks: 2, q: "Name the two solutions that are added to a sample to test for sulfate ions.", scheme: ["Dilute hydrochloric acid", "Barium chloride solution"], answer: "Dilute hydrochloric acid, followed by barium chloride solution." },
      { g: 4, marks: 1, q: "What colour precipitate do chloride ions give with silver nitrate solution acidified with dilute nitric acid?", scheme: ["White"], answer: "A white precipitate." },
      { g: 4, marks: 1, q: "Give one advantage of instrumental methods of analysis compared with simple chemical tests.", scheme: ["Any one: more accurate / more sensitive / more rapid"], answer: "They are more sensitive (they are also more accurate and more rapid)." },
      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "Explain how melting point data can be used to tell whether a solid is pure.", scheme: ["A pure substance melts at a sharp, specific temperature", "An impure substance melts over a range of temperatures (usually lower)"], answer: "A pure substance melts at a sharp, specific temperature, whereas an impure substance melts over a range of temperatures, usually lower than the pure substance's melting point." },
      { g: 5, marks: 2, q: "A carton is labelled 'pure orange juice'. Explain why a chemist would not describe the juice as pure.", scheme: ["In everyday language 'pure' means nothing has been added / it is natural", "In chemistry the juice is a mixture of many substances (e.g. water, sugars, acids), not a single element or compound"], answer: "In everyday language 'pure' means nothing has been added, but to a chemist a pure substance is a single element or compound. Orange juice is a mixture of many substances such as water, sugars and acids, so it is not pure." },
      { g: 5, marks: 2, q: "State the equation for the Rf value and explain why an Rf value can never be greater than 1.", scheme: ["Rf = distance moved by substance ÷ distance moved by solvent", "A substance cannot travel further than the solvent front"], answer: "Rf = distance moved by the substance ÷ distance moved by the solvent. The substance is carried by the solvent, so it cannot travel further than the solvent front, meaning the Rf can never be greater than 1." },
      { g: 5, marks: 2, q: "On a chromatogram a spot has moved 3.0 cm and the solvent has moved 7.5 cm. Calculate the Rf value of the spot.", scheme: ["Rf = 3.0 ÷ 7.5", "= 0.40"], answer: "Rf = 3.0 ÷ 7.5 = 0.40." },
      { g: 5, marks: 2, q: "Explain why the start line on a paper chromatogram is drawn in pencil rather than ink.", scheme: ["Pencil (graphite) is insoluble in the solvent, so it does not move", "Ink would dissolve and separate, mixing with the spots and spoiling the results"], answer: "Pencil graphite is insoluble in the solvent so the line stays put, whereas ink would dissolve and separate up the paper, mixing with the spots being tested." },
      { g: 5, marks: 2, q: "Explain why the solvent level must be below the start line in paper chromatography.", scheme: ["If the solvent covered the spots, the substances would dissolve into the solvent in the beaker", "Instead of travelling up the paper, so no chromatogram would form"], answer: "If the solvent were above the start line, the substances in the spots would dissolve into the solvent in the beaker instead of being carried up the paper, so they would not separate." },
      { g: 5, marks: 3, q: "Describe how to carry out a flame test on a solid sample.", scheme: ["Clean a nichrome (or platinum) wire loop by dipping it in hydrochloric acid and heating it until it gives no colour", "Dip the loop in acid and then into the solid sample", "Hold the loop in a hot (blue) Bunsen flame and observe the colour"], answer: "Clean a nichrome wire loop by dipping it in hydrochloric acid and holding it in the flame until it gives no colour. Dip the loop in acid and then into the solid, then hold it in a hot, blue Bunsen flame and observe the flame colour." },
      { g: 5, marks: 3, q: "State the flame test colours for lithium, calcium and copper ions.", scheme: ["Lithium: crimson", "Calcium: orange-red", "Copper: green"], answer: "Lithium gives a crimson flame, calcium gives an orange-red flame and copper gives a green flame." },
      { g: 5, marks: 3, q: "Describe how to test a sample for carbonate ions.", scheme: ["Add dilute acid (e.g. hydrochloric acid)", "Bubbles / fizzing are seen", "Bubble the gas through limewater, which turns milky (carbon dioxide)"], answer: "Add dilute acid to the sample. If carbonate ions are present it fizzes, and the gas turns limewater milky, showing it is carbon dioxide." },
      { g: 5, marks: 3, q: "Silver nitrate solution acidified with dilute nitric acid is added to solutions of halide ions. State the colour of the precipitate formed with chloride, bromide and iodide ions.", scheme: ["Chloride: white", "Bromide: cream", "Iodide: yellow"], answer: "Chloride ions give a white precipitate, bromide ions a cream precipitate and iodide ions a yellow precipitate." },
      { g: 5, marks: 2, q: "Sodium hydroxide solution is added to separate solutions of iron(II) ions and iron(III) ions. State the colour of the precipitate in each case.", scheme: ["Iron(II): green", "Iron(III): brown"], answer: "Iron(II) ions give a green precipitate and iron(III) ions give a brown precipitate." },
      { g: 5, marks: 3, q: "Name three metal ions that form a white precipitate with sodium hydroxide solution.", scheme: ["Aluminium (Al³⁺)", "Calcium (Ca²⁺)", "Magnesium (Mg²⁺)"], answer: "Aluminium (Al³⁺), calcium (Ca²⁺) and magnesium (Mg²⁺) ions." },
      { g: 5, marks: 2, q: "Explain one limitation of flame tests that flame emission spectroscopy overcomes.", scheme: ["In a mixture, the colour of one ion can mask (hide) another, e.g. yellow sodium", "Flame emission spectroscopy gives a line spectrum that can identify each ion in a mixture"], answer: "In a mixture of metal ions one flame colour can mask another, such as sodium's strong yellow hiding other colours. Flame emission spectroscopy produces a line spectrum that can identify each metal ion even in a mixture." },
      { g: 5, marks: 2, q: "Explain how a formulation differs from an ordinary mixture.", scheme: ["Each component is added in a carefully measured quantity (a fixed recipe)", "Each component has a specific purpose in the product"], answer: "A formulation is made to a precise recipe, with each component added in a measured quantity and chosen for a specific purpose, so the product has the properties it needs." },
      { g: 5, marks: 2, q: "Pure water boils at 100 °C. A sample of water boils at 102 °C. What does this tell you about the sample? Explain your answer.", scheme: ["The sample is not pure / contains dissolved substances", "Impurities raise the boiling point above that of the pure substance"], answer: "The sample is not pure — it contains dissolved substances, and impurities raise the boiling point above the 100 °C of pure water." },
      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why dilute nitric acid is added to the sample before silver nitrate solution in the test for halide ions.", scheme: ["To react with / remove any carbonate ions", "Carbonate ions would also form a precipitate with silver ions, giving a false positive"], answer: "Dilute nitric acid removes any carbonate ions, which would otherwise react with the silver ions to form a precipitate and give a false positive result." },
      { g: 6, marks: 2, q: "Explain why dilute hydrochloric acid, and not dilute sulfuric acid, is added in the test for sulfate ions.", scheme: ["Sulfuric acid contains sulfate ions, so it would give a white precipitate with barium chloride whatever the sample", "Hydrochloric acid removes carbonate ions without adding sulfate ions"], answer: "Sulfuric acid contains sulfate ions, so it would form a white precipitate with barium chloride even if the sample had none. Hydrochloric acid removes carbonate ions, which would also give a white precipitate, without adding any sulfate ions." },
      { g: 6, marks: 2, q: "Explain why dilute hydrochloric acid must not be used to acidify the sample in the test for chloride ions.", scheme: ["Hydrochloric acid contains chloride ions", "These would give a white precipitate with silver nitrate even if the sample had no chloride ions"], answer: "Hydrochloric acid contains chloride ions, which would react with silver nitrate to give a white precipitate even if the sample itself contained no chloride ions." },
      { g: 6, marks: 2, q: "A solution gives a white precipitate when a few drops of sodium hydroxide solution are added. Describe how to find out whether the solution contains aluminium ions.", scheme: ["Add excess sodium hydroxide solution", "If the precipitate dissolves (forming a colourless solution) aluminium ions are present; if not, it is calcium or magnesium"], answer: "Keep adding sodium hydroxide solution until it is in excess. If the white precipitate dissolves to form a colourless solution, aluminium ions are present; if it stays, the ions are calcium or magnesium." },
      { g: 6, marks: 3, q: "Describe how a student could distinguish between solutions of calcium chloride and magnesium chloride.", scheme: ["Sodium hydroxide cannot tell them apart: both give a white precipitate that does not dissolve in excess", "Carry out a flame test on each", "Calcium ions give an orange-red flame; magnesium ions give no flame colour"], answer: "Sodium hydroxide will not distinguish them, because both give a white precipitate that does not dissolve in excess. Instead, carry out a flame test: calcium ions give an orange-red flame, while magnesium ions give no colour." },
      { g: 6, marks: 3, q: "In a chromatography experiment the solvent front moved 8.0 cm. Spot A moved 2.4 cm and spot B moved 6.0 cm. Calculate the Rf value of each spot.", scheme: ["Rf = distance moved by spot ÷ distance moved by solvent", "Spot A: 2.4 ÷ 8.0 = 0.30", "Spot B: 6.0 ÷ 8.0 = 0.75"], answer: "Rf = distance moved by spot ÷ distance moved by solvent. Spot A: 2.4 ÷ 8.0 = 0.30. Spot B: 6.0 ÷ 8.0 = 0.75." },
      { g: 6, marks: 3, q: "A black ink produces three separate spots on a paper chromatogram. Explain what this shows and why the spots travel different distances.", scheme: ["The ink is a mixture of (at least) three different substances", "Each substance has a different attraction to the paper (stationary phase) and the solvent (mobile phase) / different solubility", "Substances more soluble in the solvent / less attracted to the paper travel further"], answer: "The ink is a mixture of at least three substances. Each substance is attracted to the paper and dissolves in the solvent to a different extent, so those that are more soluble in the solvent and less attracted to the paper travel further up the paper." },
      { g: 6, marks: 2, q: "Explain why a lid is placed on the beaker during paper chromatography.", scheme: ["To stop the solvent evaporating", "So the solvent keeps rising up the paper evenly and the Rf values are reliable"], answer: "The lid stops the solvent evaporating, so the solvent continues to rise evenly up the paper and the Rf values obtained are reliable." },
      { g: 6, marks: 2, q: "Describe the test for chlorine and explain why the litmus paper must be damp.", scheme: ["Hold damp litmus paper in the gas: it is bleached white", "Chlorine must dissolve in the water on the paper to bleach it"], answer: "Hold damp litmus paper in the gas — chlorine bleaches it white. The paper must be damp because chlorine needs to dissolve in water to bleach the paper." },
      { g: 6, marks: 3, q: "A white solid gives a yellow flame test. When dilute hydrochloric acid is added it fizzes, and the gas turns limewater milky. Identify the solid and explain your reasoning.", scheme: ["Yellow flame shows sodium ions", "Fizzing with a gas that turns limewater milky shows carbonate ions (carbon dioxide produced)", "The solid is sodium carbonate"], answer: "The yellow flame shows sodium ions are present, and the fizzing with a gas that turns limewater milky shows carbon dioxide was made, so carbonate ions are present. The solid is sodium carbonate." },
      { g: 6, marks: 2, q: "Write a balanced ionic equation, with state symbols, for the formation of the precipitate when sodium hydroxide solution is added to a solution of copper(II) ions.", scheme: ["Cu²⁺ + 2OH⁻ → Cu(OH)₂ (correct formulae and balancing)", "Correct state symbols: (aq) + (aq) → (s)"], answer: "Cu²⁺(aq) + 2OH⁻(aq) → Cu(OH)₂(s)" },
      { g: 6, marks: 3, q: "Describe how flame emission spectroscopy is used to identify the metal ion in a solution.", scheme: ["The sample is put into a flame", "The light given out is passed through a spectroscope to produce a line spectrum", "The spectrum is compared with reference spectra of known metal ions (each ion has a unique pattern of lines)"], answer: "The sample is placed in a flame and the light it gives out is passed through a spectroscope, producing a line spectrum. This is compared with reference spectra, because each metal ion gives its own unique pattern of lines." },
      { g: 6, marks: 2, q: "Instrumental methods are described as 'sensitive'. Explain what this means and why it is useful.", scheme: ["They can detect very small amounts / very low concentrations of a substance", "Useful when only a tiny sample is available or when checking for traces, e.g. pollutants in water"], answer: "It means they can detect very small amounts or very low concentrations of a substance. This is useful when only a tiny sample is available, or when looking for traces such as pollutants in drinking water." },
      { g: 6, marks: 2, q: "What is meant by the solvent front, and why should its position be marked as soon as the chromatogram is removed from the solvent?", scheme: ["The furthest point reached by the solvent up the paper", "The solvent evaporates quickly so the line would disappear, and its distance is needed to calculate Rf values"], answer: "The solvent front is the furthest point the solvent has reached on the paper. It must be marked straight away because the solvent evaporates and the line becomes invisible, and its distance is needed to calculate Rf values." },
      { g: 6, marks: 3, q: "A paint formulation contains 35% pigment by mass. Calculate the mass of pigment in a 2.0 kg tin of paint, and state the purpose of one other component of paint.", scheme: ["(35 ÷ 100) × 2.0", "= 0.70 kg (700 g)", "Binder: sticks the pigment to the surface / solvent: thins the paint so it spreads, then evaporates"], answer: "Mass of pigment = (35 ÷ 100) × 2.0 = 0.70 kg (700 g). Another component is the binder, which holds the pigment together and sticks it to the surface (or the solvent, which thins the paint so it spreads and then evaporates)." },
      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "A solution of a single compound gives a lilac flame test. When dilute nitric acid and silver nitrate solution are added, a cream precipitate forms. Identify the compound, explaining each result.", scheme: ["Lilac flame shows potassium ions (K⁺)", "Cream precipitate with acidified silver nitrate shows bromide ions (Br⁻)", "The compound is potassium bromide"], answer: "The lilac flame shows potassium ions, and the cream precipitate with acidified silver nitrate shows bromide ions, so the compound is potassium bromide." },
      { g: 7, marks: 4, q: "A solution gives a green precipitate with sodium hydroxide solution, and a white precipitate when dilute hydrochloric acid and barium chloride solution are added. Identify the compound and write an ionic equation for the reaction with sodium hydroxide.", scheme: ["Green precipitate shows iron(II) ions (Fe²⁺)", "White precipitate with acidified barium chloride shows sulfate ions (SO₄²⁻)", "The compound is iron(II) sulfate", "Fe²⁺ + 2OH⁻ → Fe(OH)₂"], answer: "The green precipitate shows iron(II) ions and the white precipitate with acidified barium chloride shows sulfate ions, so the compound is iron(II) sulfate. Fe²⁺(aq) + 2OH⁻(aq) → Fe(OH)₂(s)." },
      { g: 7, marks: 3, q: "A food colouring and three known dyes, E, F and G, are run on the same chromatogram using the same solvent. The food colouring gives spots with Rf values of 0.25 and 0.62. The Rf values of the dyes are E = 0.25, F = 0.48 and G = 0.62. State which dyes the food colouring contains and explain why the same solvent must be used for all the samples.", scheme: ["The food colouring contains dyes E and G", "It does not contain dye F (no spot at 0.48)", "Rf values depend on the solvent, so they can only be compared if the same solvent is used"], answer: "The food colouring contains dyes E and G because its spots match their Rf values of 0.25 and 0.62; it does not contain F, as there is no spot at 0.48. The same solvent must be used because a substance's Rf value depends on the solvent, so values from different solvents cannot be compared." },
      { g: 7, marks: 3, q: "Explain why the Rf value of a substance stays the same in repeat experiments with the same solvent and paper, even when the solvent is allowed to travel a different distance.", scheme: ["The substance moves as the solvent moves", "The distance moved by the substance is proportional to the distance moved by the solvent", "So the ratio (Rf) stays constant and is characteristic of that substance in that solvent"], answer: "The substance is carried along as the solvent moves, so the distance it travels is proportional to the distance the solvent travels. The ratio between the two — the Rf value — therefore stays constant and is characteristic of that substance in that solvent." },
      { g: 7, marks: 4, q: "A student writes: 'I drew the start line with a felt-tip pen, added spots of the ink, then placed the paper in the solvent so that the solvent covered the spots.' Identify the two errors and explain the effect of each.", scheme: ["Error 1: start line in felt-tip pen — it should be pencil", "The felt-tip ink would dissolve and separate, confusing the results", "Error 2: solvent covering the spots — the solvent should be below the start line", "The spots would dissolve into the solvent in the beaker instead of moving up the paper"], answer: "First, the start line should be drawn in pencil, not felt-tip, because the felt-tip ink would dissolve in the solvent and separate, mixing with the results. Second, the solvent should be below the start line; if it covers the spots they dissolve into the solvent in the beaker rather than travelling up the paper." },
      { g: 7, marks: 3, q: "Explain why hydrogen makes a squeaky pop when tested with a burning splint. Include a balanced symbol equation.", scheme: ["Hydrogen reacts (burns) very rapidly with oxygen in the air", "The rapid reaction causes a small explosion, which makes the pop sound", "2H₂ + O₂ → 2H₂O"], answer: "The flame ignites the hydrogen, which reacts very rapidly with oxygen from the air in a small explosion that makes the pop sound: 2H₂ + O₂ → 2H₂O." },
      { g: 7, marks: 3, q: "Explain why a flame test may fail to identify all the metal ions in a mixture, and how this problem can be overcome.", scheme: ["The flame colour of one ion can mask the colour of another (e.g. sodium's yellow)", "So some ions present may not be seen / the colour cannot be interpreted", "Use flame emission spectroscopy, which gives separate lines for each ion so all can be identified"], answer: "In a mixture, a strong flame colour such as sodium's yellow can mask the colours of other ions, so some ions may be missed. Flame emission spectroscopy overcomes this because each ion gives its own spectral lines, so every ion in the mixture can be identified." },
      { g: 7, marks: 3, q: "In flame emission spectroscopy, the reference spectra show lines at these wavelengths: lithium 610 nm and 671 nm; sodium 589 nm; potassium 404 nm and 766 nm (all approximate). A sample shows lines at 589 nm, 610 nm and 671 nm only. Identify which metal ions are present and explain your answer.", scheme: ["Sodium ions are present (line at 589 nm)", "Lithium ions are present (both lines at 610 nm and 671 nm)", "Potassium ions are absent because there are no lines at 404 nm or 766 nm"], answer: "The line at 589 nm matches sodium and the lines at 610 nm and 671 nm match lithium, so sodium and lithium ions are present. There are no lines at 404 nm or 766 nm, so potassium ions are absent." },
      { g: 7, marks: 3, q: "A flame emission spectrometer is calibrated with sodium ion solutions. A 2.0 mg/dm³ solution gives a reading of 30, a 4.0 mg/dm³ solution gives 60 and a 6.0 mg/dm³ solution gives 90. A sample tested under the same conditions gives a reading of 45. Determine the concentration of sodium ions in the sample.", scheme: ["Reading is directly proportional to concentration: 30 ÷ 2.0 = 15 units per 1.0 mg/dm³", "Concentration = 45 ÷ 15", "= 3.0 mg/dm³"], answer: "The reading is directly proportional to concentration, rising by 15 for every 1.0 mg/dm³ (30 ÷ 2.0 = 15). So the concentration = 45 ÷ 15 = 3.0 mg/dm³." },
      { g: 7, marks: 4, q: "A solution may contain both carbonate ions and chloride ions. Describe tests, in a suitable order, that would show both ions are present.", scheme: ["Add dilute nitric acid: fizzing, and the gas turns limewater milky, shows carbonate ions", "Keep adding nitric acid until the fizzing stops, so all the carbonate is removed", "Then add silver nitrate solution", "A white precipitate shows chloride ions"], answer: "Add dilute nitric acid: fizzing, with a gas that turns limewater milky, shows carbonate ions. Keep adding nitric acid until the fizzing stops so all the carbonate is removed, then add silver nitrate solution — a white precipitate shows chloride ions are also present." },
      { g: 7, marks: 4, q: "Write balanced ionic equations, with state symbols, for the formation of the white precipitates in the test for sulfate ions and in the test for chloride ions, and name each precipitate.", scheme: ["Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s)", "Precipitate: barium sulfate", "Ag⁺(aq) + Cl⁻(aq) → AgCl(s)", "Precipitate: silver chloride"], answer: "Sulfate test: Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s), forming barium sulfate. Chloride test: Ag⁺(aq) + Cl⁻(aq) → AgCl(s), forming silver chloride." },
      { g: 7, marks: 3, q: "A pure compound melts at 122 °C. Sample P melts at exactly 122 °C. Sample Q melts gradually between 115 °C and 119 °C. Explain which sample is pure.", scheme: ["P is pure: it melts at a sharp temperature that matches the pure compound", "Q is impure: it melts over a range of temperatures", "Q's melting point is lower than 122 °C, because impurities lower the melting point"], answer: "Sample P is pure because it melts at a sharp temperature that matches the pure compound's melting point. Sample Q is impure: it melts over a range of temperatures, and below 122 °C, because impurities lower the melting point." },
      { g: 7, marks: 4, q: "Explain how sodium hydroxide solution can be used to distinguish between solutions of aluminium sulfate and magnesium sulfate. Include an ionic equation for the precipitate formed with aluminium ions.", scheme: ["A few drops of sodium hydroxide give a white precipitate with both solutions", "Add excess sodium hydroxide solution", "The aluminium hydroxide precipitate dissolves, but the magnesium hydroxide precipitate does not", "Al³⁺ + 3OH⁻ → Al(OH)₃"], answer: "A few drops of sodium hydroxide give a white precipitate with both solutions. When excess sodium hydroxide is added, the aluminium hydroxide precipitate dissolves but the magnesium hydroxide precipitate remains. Al³⁺(aq) + 3OH⁻(aq) → Al(OH)₃(s)." },
      { g: 7, marks: 3, q: "Explain why the test for sulfate ions could give a misleading result if the sample contained carbonate ions and no hydrochloric acid was added first.", scheme: ["Barium ions also react with carbonate ions", "Forming barium carbonate, which is a white precipitate", "So a white precipitate would appear even without sulfate ions (hydrochloric acid removes carbonate as carbon dioxide)"], answer: "Barium ions react with carbonate ions to form barium carbonate, which is also a white precipitate. So without acid a white precipitate could form even if no sulfate ions were present; adding hydrochloric acid first removes the carbonate ions as carbon dioxide." },
      { g: 7, marks: 3, q: "Explain why a medicine tablet is described as a formulation and why each component must be present in a precise quantity.", scheme: ["It is a mixture of the active ingredient with other substances such as fillers, binders or coatings", "Each component has a specific purpose (e.g. the binder holds the tablet together, the active ingredient treats the illness)", "Precise quantities make sure every tablet gives the correct, safe and effective dose"], answer: "A tablet is a mixture of the active ingredient with other substances such as fillers, binders and coatings, each with a specific job — for example the binder holds the tablet together. The quantities must be precise so every tablet delivers the correct, safe and effective dose." },
      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 3, q: "An unknown substance and substance X both have an Rf value of 0.45 in water. Explain why a chemist would repeat the chromatography with a different solvent before concluding that the unknown is X.", scheme: ["Different substances can have the same Rf value in one solvent", "Rf values depend on the solvent, so different substances usually give different values in a new solvent", "If the Rf values match in two (or more) different solvents, it is much more likely the unknown is X"], answer: "Two different substances can happen to have the same Rf value in one solvent. Because Rf values depend on the solvent, running both in a second solvent is a stronger test: if the values still match, the unknown is much more likely to be X." },
      { g: 8, marks: 3, q: "A dye has an Rf value of 0.35 in a particular solvent. Calculate how far the dye moves when the solvent front travels 11.2 cm, and how far it would have moved if the paper had been removed when the solvent had travelled only 8.0 cm.", scheme: ["Distance moved by dye = Rf × distance moved by solvent", "0.35 × 11.2 = 3.92 cm", "0.35 × 8.0 = 2.8 cm"], answer: "Distance moved by dye = Rf × distance moved by solvent. With 11.2 cm: 0.35 × 11.2 = 3.92 cm. With 8.0 cm: 0.35 × 8.0 = 2.8 cm." },
      { g: 8, marks: 5, q: "Solution Z contains a single compound. It gives no flame test colour. Sodium hydroxide solution gives a white precipitate that dissolves in excess. Dilute nitric acid and silver nitrate solution give no precipitate. Dilute hydrochloric acid and barium chloride solution give a white precipitate. Identify Z, explaining each result.", scheme: ["No flame colour rules out lithium, sodium, potassium, calcium and copper ions", "White precipitate that dissolves in excess sodium hydroxide shows aluminium ions", "No precipitate with acidified silver nitrate shows no halide ions are present", "White precipitate with acidified barium chloride shows sulfate ions", "Z is aluminium sulfate"], answer: "No flame colour rules out ions such as lithium, sodium, potassium, calcium and copper. The white precipitate that dissolves in excess sodium hydroxide shows aluminium ions. No precipitate with acidified silver nitrate means there are no halide ions, and the white precipitate with acidified barium chloride shows sulfate ions. So Z is aluminium sulfate." },
      { g: 8, marks: 4, q: "Write a balanced ionic equation for the reaction of carbonate ions with hydrogen ions from an acid, and a balanced symbol equation for the reaction of the gas with limewater. Use the second equation to explain why the limewater turns milky.", scheme: ["CO₃²⁻ + 2H⁺ → CO₂ + H₂O", "Ca(OH)₂ + CO₂ → CaCO₃ + H₂O", "Calcium carbonate is insoluble", "It forms as a fine white precipitate, which makes the limewater look milky"], answer: "CO₃²⁻ + 2H⁺ → CO₂ + H₂O. The carbon dioxide reacts with limewater: Ca(OH)₂ + CO₂ → CaCO₃ + H₂O. Calcium carbonate is insoluble, so it forms as a fine white precipitate that makes the limewater look milky." },
      { g: 8, marks: 3, q: "A water company tests drinking water for traces of toxic metal ions using instrumental methods rather than precipitate tests. Explain three reasons for this choice.", scheme: ["Sensitive: they can detect the very low concentrations that may be present", "Accurate: they measure the concentration, so it can be compared with safety limits", "Rapid: many samples can be analysed quickly (often automatically)"], answer: "Instrumental methods are sensitive, so they can detect the tiny concentrations of toxic ions that might be present; accurate, so the measured concentration can be compared with safety limits; and rapid, so large numbers of samples can be tested quickly." },
      { g: 8, marks: 4, q: "Potassium ion standards give these flame emission readings: 1.0 mg/dm³ gives 12, 3.0 mg/dm³ gives 36 and 5.0 mg/dm³ gives 60. A river water sample was diluted ten times (1 part sample to 9 parts pure water) and the diluted solution gave a reading of 42. Calculate the concentration of potassium ions in the original river water.", scheme: ["Reading is proportional to concentration: 12 units per 1.0 mg/dm³", "Diluted sample: 42 ÷ 12 = 3.5 mg/dm³", "Original sample was ten times more concentrated: 3.5 × 10", "= 35 mg/dm³"], answer: "The reading rises by 12 for every 1.0 mg/dm³, so the diluted solution contains 42 ÷ 12 = 3.5 mg/dm³. The river water was diluted ten times, so its concentration is 3.5 × 10 = 35 mg/dm³." },
      { g: 8, marks: 4, q: "Explain how you could tell apart solutions of sodium chloride, sodium bromide and sodium iodide, and why a flame test would not help.", scheme: ["All three contain sodium ions, so they all give a yellow flame and cannot be distinguished by a flame test", "Add dilute nitric acid then silver nitrate solution to each", "Sodium chloride gives a white precipitate", "Sodium bromide gives a cream precipitate and sodium iodide a yellow precipitate"], answer: "A flame test would not help because all three contain sodium ions and give the same yellow flame. Instead, add dilute nitric acid and then silver nitrate solution to each: sodium chloride gives a white precipitate, sodium bromide a cream precipitate and sodium iodide a yellow precipitate." },
      { g: 8, marks: 3, q: "Write a balanced symbol equation, with state symbols, for the reaction between iron(III) chloride solution and sodium hydroxide solution, and state what would be observed.", scheme: ["FeCl₃ + NaOH → Fe(OH)₃ + NaCl (correct formulae)", "FeCl₃(aq) + 3NaOH(aq) → Fe(OH)₃(s) + 3NaCl(aq) (balanced with state symbols)", "A brown precipitate forms"], answer: "FeCl₃(aq) + 3NaOH(aq) → Fe(OH)₃(s) + 3NaCl(aq). A brown precipitate of iron(III) hydroxide is seen." },
      { g: 8, marks: 3, q: "Two liquids are heated. The temperature of liquid A stays at 78 °C the whole time it boils. Liquid B starts boiling at 80 °C and its temperature rises steadily to 95 °C as it boils. Explain which liquid is more likely to be pure and what further evidence would confirm it.", scheme: ["Pure substances boil at a fixed, specific temperature, so A is more likely to be pure", "B boils over a range of temperatures, so it is a mixture / impure", "Compare A's boiling point with the data-book value for the substance it is thought to be"], answer: "Liquid A is more likely to be pure because a pure substance boils at one fixed temperature, while B boils over a range of temperatures, showing it is a mixture. Comparing A's boiling point with the data-book value for the substance it is thought to be would help confirm its identity and purity." },
      { g: 8, marks: 4, q: "Explain, in terms of the stationary and mobile phases, why two substances in a mixture separate during paper chromatography.", scheme: ["Each substance is distributed between the mobile phase (solvent) and the stationary phase (paper)", "A substance that is more soluble in the solvent spends more time in the mobile phase and moves further", "A substance that is more strongly attracted to the paper spends more time in the stationary phase and moves less", "So the substances travel different distances and have different Rf values"], answer: "Each substance is distributed between the mobile phase (the solvent) and the stationary phase (the paper). A substance that is more soluble in the solvent spends more time in the mobile phase and travels further, while one more strongly attracted to the paper spends more time in the stationary phase and travels less. The substances therefore end up at different distances, with different Rf values." },
      { g: 8, marks: 4, q: "A chromatogram of the colouring in some sweets shows three spots: one on the start line, one with Rf 0.30 and one with Rf 0.72. A banned dye has an Rf value of 0.72 in the same solvent. Explain what the chromatogram shows about the colouring.", scheme: ["The colouring is a mixture of at least three substances", "The spot at Rf 0.72 matches the banned dye, so the sweets may contain it", "This should be confirmed using a different solvent, as another substance could have the same Rf", "The spot on the start line is a substance that is insoluble in this solvent"], answer: "The colouring is a mixture of at least three substances. The spot at Rf 0.72 matches the banned dye, so the sweets may contain it, but this should be checked with a different solvent because another substance could have the same Rf. The spot left on the start line is a substance that does not dissolve in this solvent." },
      { g: 8, marks: 5, q: "A white solid is known to be sodium carbonate, sodium sulfate or sodium chloride. Plan a sequence of tests to identify it.", scheme: ["Dissolve some of the solid in water", "Add dilute hydrochloric acid: fizzing with a gas that turns limewater milky shows sodium carbonate", "If there is no fizzing, add barium chloride solution to the acidified sample: a white precipitate shows sodium sulfate", "If there is no precipitate, test a fresh sample with dilute nitric acid and silver nitrate", "A white precipitate confirms sodium chloride (a fresh sample is needed because hydrochloric acid adds chloride ions)"], answer: "Dissolve the solid in water and add dilute hydrochloric acid: fizzing with a gas that turns limewater milky shows it is sodium carbonate. If there is no fizzing, add barium chloride to the acidified solution — a white precipitate shows sodium sulfate. If there is still no precipitate, take a fresh sample (the first contains chloride from the hydrochloric acid) and add dilute nitric acid and silver nitrate: a white precipitate confirms sodium chloride." },
      { g: 8, marks: 4, q: "During the electrolysis of sodium chloride solution, hydrogen is produced at the cathode and chlorine at the anode. Describe how you would test each gas and give the results.", scheme: ["Hydrogen: hold a burning splint at the mouth of a test tube of the gas", "Hydrogen result: squeaky pop", "Chlorine: hold damp litmus paper in the gas", "Chlorine result: the litmus paper is bleached white"], answer: "Collect each gas in a test tube. For hydrogen, hold a burning splint at the mouth of the tube: it burns with a squeaky pop. For chlorine, hold damp litmus paper in the gas: it is bleached white." },
      { g: 8, marks: 3, q: "Explain why the wire loop used in a flame test must be cleaned between samples, and why a nichrome or platinum wire is used.", scheme: ["Traces of a previous sample would contaminate the next test", "They would add their own colour, masking or changing the colour seen, giving a wrong identification", "Nichrome/platinum is unreactive and gives no flame colour of its own"], answer: "Traces left from a previous sample would add their own flame colour, masking or changing the colour of the next sample and leading to a wrong identification. Nichrome or platinum is used because it is unreactive and does not colour the flame itself." },
      { g: 8, marks: 3, q: "Substance W gives a single spot when run in solvent A, but two separate spots when run in solvent B. Explain what this shows.", scheme: ["W is not pure / is a mixture of at least two substances", "In solvent A the two substances have the same (or very similar) Rf value, so their spots overlap", "A pure substance gives a single spot in every solvent"], answer: "W is a mixture of at least two substances. In solvent A the two substances have the same Rf value, so their spots overlap and look like one, but solvent B separates them. A pure substance would give a single spot in every solvent." },
      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "An environmental scientist needs to identify the metal ions present in a sample of river water and find their concentrations. Evaluate the use of simple chemical tests (flame tests and sodium hydroxide) compared with instrumental methods such as flame emission spectroscopy for this job.", scheme: ["Chemical tests are cheap, quick to set up and need only simple equipment", "But they only show which ions are present, not their concentrations", "They are not sensitive, so ions at very low concentrations in river water may be missed", "In a mixture, flame colours mask each other and precipitate colours can be hidden", "Flame emission spectroscopy is sensitive, accurate and rapid, identifies each ion in a mixture from its line spectrum and measures concentration (using calibration)", "Conclusion: instrumental methods are more suitable here, despite the higher cost of equipment"], answer: "Simple chemical tests are cheap, quick and need little equipment, but they only show which ions are present, not how much. They are not very sensitive, so the low concentrations in river water may be missed, and in a mixture one flame colour or precipitate colour can mask another. Flame emission spectroscopy is sensitive, accurate and rapid; it identifies each ion in a mixture from its line spectrum and, with calibration, measures concentrations. So although the equipment is expensive, instrumental methods are far better for this job." },
      { g: 9, marks: 6, q: "Four unlabelled bottles contain solutions of magnesium sulfate, aluminium sulfate, calcium chloride and lithium chloride. Plan a series of tests to identify each solution, explaining how each result is used.", scheme: ["Add sodium hydroxide solution to a fresh sample of each: lithium chloride gives no precipitate (confirm with a crimson flame test)", "The other three give white precipitates; add excess sodium hydroxide", "The precipitate that dissolves in excess identifies aluminium sulfate", "Flame test the remaining two: calcium chloride gives an orange-red flame, magnesium sulfate gives no colour", "Confirm the anions: hydrochloric acid + barium chloride gives a white precipitate with the sulfates; nitric acid + silver nitrate gives a white precipitate with the chlorides", "Use a fresh sample for each test so earlier reagents do not interfere"], answer: "Add sodium hydroxide to a sample of each. Lithium chloride gives no precipitate, which a crimson flame test confirms. The other three give white precipitates; with excess sodium hydroxide the one that dissolves is aluminium sulfate. Flame test the other two: orange-red shows calcium chloride, and no colour shows magnesium sulfate. Confirm with anion tests — acidified barium chloride gives a white precipitate with the sulfates and acidified silver nitrate a white precipitate with the chlorides — using a fresh sample each time so reagents do not interfere." },
      { g: 9, marks: 5, q: "Mixture M is run on a paper chromatogram. The solvent front moves 9.0 cm and M gives spots at 1.8 cm, 4.5 cm and 7.2 cm from the start line. In the same solvent, reference substances have these Rf values: A = 0.20, B = 0.35, C = 0.50, D = 0.80. Calculate the Rf value of each spot and deduce which substances M contains.", scheme: ["Rf = distance moved by spot ÷ distance moved by solvent", "1.8 ÷ 9.0 = 0.20", "4.5 ÷ 9.0 = 0.50", "7.2 ÷ 9.0 = 0.80", "M contains A, C and D, but not B"], answer: "Rf = distance moved by spot ÷ distance moved by solvent: 1.8 ÷ 9.0 = 0.20, 4.5 ÷ 9.0 = 0.50 and 7.2 ÷ 9.0 = 0.80. These match A, C and D, so M contains A, C and D but not B (no spot at 0.35)." },
      { g: 9, marks: 6, q: "A pharmaceutical company must check that each batch of a drug is pure. Evaluate the use of melting point measurement and paper chromatography for this purpose.", scheme: ["Melting point: a pure drug melts sharply at its known temperature; impurities lower it and cause melting over a range", "Melting point is quick and simple, but does not identify the impurity, and a very small amount of impurity may cause little change", "Chromatography: a pure drug gives a single spot, and extra spots reveal impurities that can be compared with reference Rf values", "Limitation: an impurity with the same Rf may overlap, so more than one solvent is needed", "Using both methods together gives stronger evidence than either alone", "Conclusion, e.g. both are useful screening checks, but instrumental methods may be needed for very small traces"], answer: "Melting point is quick and simple: a pure drug melts sharply at its known temperature, while impurities lower the melting point and make it melt over a range. However, it does not identify the impurity and very small amounts may barely change it. Chromatography gives a single spot for a pure drug and extra spots reveal impurities, which can be compared with reference Rf values, but an impurity with the same Rf could overlap, so several solvents are needed. Using both together gives much stronger evidence, though instrumental methods may be needed to detect very small traces." },
      { g: 9, marks: 4, q: "A student adds barium chloride solution to a solution and sees a white precipitate. She concludes that the solution contains sulfate ions. Evaluate her conclusion.", scheme: ["A white precipitate is consistent with sulfate ions (barium sulfate)", "But carbonate ions also give a white precipitate with barium ions (barium carbonate)", "She did not add dilute hydrochloric acid first, so the conclusion is not valid", "Repeat with dilute hydrochloric acid added first: if a white precipitate still forms, sulfate is confirmed"], answer: "The white precipitate is consistent with sulfate ions forming barium sulfate, but carbonate ions also give a white precipitate of barium carbonate. Because she did not acidify the sample with dilute hydrochloric acid first, her conclusion is not valid. She should repeat the test with the acid added first — if a white precipitate still forms, sulfate ions are confirmed." },
      { g: 9, marks: 5, q: "Describe how flame emission spectroscopy could be used to find the concentration of lithium ions in a solution, and explain how the reliability of the result could be improved.", scheme: ["Prepare standard solutions of lithium ions of known concentrations", "Measure the intensity of a lithium spectral line for each standard", "Plot a calibration graph of intensity against concentration", "Measure the sample under the same conditions and read its concentration from the graph", "Reliability: repeat readings and use a mean, and make sure the sample's reading lies within the range of the standards (dilute if needed)"], answer: "Make up standard lithium solutions of known concentration and measure the intensity of a lithium spectral line for each, then plot a calibration graph of intensity against concentration. Measure the unknown under the same conditions and read its concentration from the graph. To improve reliability, repeat each reading and use the mean, and make sure the sample's reading falls within the range of the standards, diluting it if necessary." },
      { g: 9, marks: 5, q: "A solution of a single compound gives a green flame test, a blue precipitate with sodium hydroxide solution, no precipitate with acidified silver nitrate and a white precipitate with acidified barium chloride. Identify the compound and write ionic equations for the two precipitation reactions.", scheme: ["Green flame and blue precipitate show copper(II) ions", "White precipitate with acidified barium chloride shows sulfate ions (no halide ions, as no precipitate with silver nitrate)", "The compound is copper(II) sulfate", "Cu²⁺ + 2OH⁻ → Cu(OH)₂", "Ba²⁺ + SO₄²⁻ → BaSO₄"], answer: "The green flame and blue precipitate show copper(II) ions. No precipitate with silver nitrate rules out halide ions, and the white precipitate with acidified barium chloride shows sulfate ions, so the compound is copper(II) sulfate. Cu²⁺(aq) + 2OH⁻(aq) → Cu(OH)₂(s) and Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s)." },
      { g: 9, marks: 6, q: "Compare pure substances, mixtures and formulations, explaining how melting point and chromatography evidence can distinguish them and why formulations are important.", scheme: ["A pure substance is a single element or compound; it melts and boils at specific temperatures", "A pure substance gives a single spot on a chromatogram in all solvents", "A mixture contains substances not chemically combined; it melts over a range and gives more than one spot", "A formulation is a mixture designed as a useful product, made to a fixed recipe", "Each component is in a measured quantity with a specific purpose", "Example: paint (pigment for colour, binder to stick it on, solvent to spread it) or a medicine, fuel or alloy"], answer: "A pure substance is a single element or compound, so it melts and boils at specific temperatures and gives one spot on a chromatogram in every solvent. A mixture contains substances that are not chemically combined, so it melts over a range of temperatures and usually gives several spots. A formulation is a special kind of mixture designed as a useful product, with each component added in a measured quantity for a specific purpose — for example paint contains a pigment for colour, a binder to stick it to the surface and a solvent to help it spread. This precise recipe makes the product work reliably every time." },
      { g: 9, marks: 4, q: "Substances P and Q both have an Rf value of 0.40 in water. In ethanol, P has an Rf value of 0.65 and Q has an Rf value of 0.25. An unknown gives a single spot with Rf 0.40 in water and a single spot with Rf 0.65 in ethanol. What can be concluded about the unknown? Justify your answer.", scheme: ["Water alone cannot distinguish P from Q because they have the same Rf", "In ethanol the unknown matches P (0.65), not Q (0.25)", "So the unknown is probably P", "A single spot in both solvents suggests the unknown is a pure substance"], answer: "Water alone cannot tell P and Q apart because both have an Rf of 0.40. In ethanol, however, the unknown's Rf of 0.65 matches P and not Q, so the unknown is probably P. As it gives a single spot in both solvents, it is also likely to be a pure substance." },
      { g: 9, marks: 5, q: "Three test tubes each contain one gas: carbon dioxide, hydrogen or oxygen. A student plans to identify all three using only a burning splint. Evaluate this plan and suggest improvements.", scheme: ["The burning splint identifies hydrogen, which burns with a squeaky pop", "In oxygen the splint burns more brightly, and in carbon dioxide it goes out", "But a splint going out does not prove carbon dioxide, as other gases (e.g. nitrogen) also put it out", "Improvement: test oxygen with a glowing splint, which relights", "Improvement: test carbon dioxide with limewater, which turns milky"], answer: "The plan works for hydrogen, which burns with a squeaky pop, and the splint would burn more brightly in oxygen and go out in carbon dioxide. However, a splint going out does not prove carbon dioxide, because other gases such as nitrogen also put it out, so the plan is not reliable. The student should use the specific tests: a glowing splint relights in oxygen and limewater turns milky with carbon dioxide." },
      { g: 9, marks: 4, q: "A solution contains both chloride ions and iodide ions. Evaluate how reliable the silver nitrate test would be for showing that both ions are present.", scheme: ["Both ions form precipitates with silver ions at the same time: white silver chloride and yellow silver iodide", "The yellow colour would mask the white precipitate, so chloride ions could be missed", "Judging colours (e.g. cream against yellow) is subjective", "Conclusion: reliable for a single halide, but not for a mixture — a more sensitive or instrumental method is needed"], answer: "Both ions react with silver ions at once, forming white silver chloride and yellow silver iodide. The yellow colour would mask the white precipitate, so chloride ions could easily be missed, and judging precipitate colours is subjective anyway. The test is reliable for a single halide, but for a mixture a more sensitive or instrumental method would be needed." },
      { g: 9, marks: 6, q: "Three unlabelled beakers contain distilled water, tap water and sea water. Describe tests to identify each sample and justify how each result would be interpreted.", scheme: ["Evaporate equal volumes to dryness in weighed evaporating basins and reweigh", "Distilled water leaves no residue, tap water a small residue, sea water a large residue", "Measure boiling points: distilled water boils at exactly 100 °C because it is pure", "Sea water boils noticeably above 100 °C because dissolved salts raise the boiling point (tap water's rise is too small to measure easily, so the residue test separates it from distilled water)", "Add dilute nitric acid and silver nitrate: sea water gives a heavy white precipitate of silver chloride", "Flame test the sea water residue: a yellow flame shows sodium ions"], answer: "Evaporate equal volumes of each sample in weighed basins and reweigh: distilled water leaves no residue, tap water a small residue and sea water a large residue. Distilled water boils at exactly 100 °C because it is pure, while sea water boils noticeably higher because dissolved salts raise the boiling point; tap water's rise is too small to measure easily, so the residue test is what separates it from distilled water. Adding dilute nitric acid and silver nitrate gives a heavy white precipitate of silver chloride with sea water, and a flame test on its residue gives a yellow flame from sodium ions." },
      { g: 9, marks: 5, q: "A student's chromatogram has large, smeared spots that overlap and a sloping solvent front. Suggest and explain improvements to the method.", scheme: ["Apply small spots using a fine capillary tube, letting each dry before adding more, so the spots do not smear", "Space the spots out along the start line so they do not merge", "Hang the paper straight so it does not touch the sides of the beaker, giving a level solvent front", "Put a lid on the beaker to stop the solvent evaporating", "If spots still overlap, try a different solvent so the substances have more different Rf values"], answer: "Apply small spots with a fine capillary tube, letting each dry before adding more, and space them well apart on the start line so they do not smear or merge. Hang the paper straight without touching the sides of the beaker so the solvent front rises evenly, and cover the beaker with a lid to stop the solvent evaporating. If spots still overlap, try a different solvent in which the substances have more different Rf values." },
      { g: 9, marks: 4, q: "Evaluate the statement: 'A single spot on a paper chromatogram proves that a substance is pure.'", scheme: ["A single spot is evidence that only one substance is present", "But two substances can have the same Rf value in one solvent, so their spots overlap", "An impurity that does not dissolve in the solvent stays on the start line and may be overlooked", "Conclusion: not proof — need a single spot in several different solvents (and could check the melting point)"], answer: "A single spot suggests only one substance is present, but it is not proof. Two substances can have the same Rf in one solvent, so their spots overlap, and an impurity that does not dissolve in the solvent stays on the start line and may be overlooked. A substance can only be considered pure if it gives a single spot in several different solvents, ideally backed up by a sharp melting point." },
      { g: 9, marks: 5, q: "A sample of water from a stream may contain iron(II) ions, iron(III) ions or both. Explain how sodium hydroxide solution could be used to test the sample, and why the results might be difficult to interpret.", scheme: ["Add sodium hydroxide solution to the sample", "A green precipitate shows iron(II) ions; a brown precipitate shows iron(III) ions", "If both are present, the brown precipitate may mask the green one", "Iron(II) hydroxide is oxidised by oxygen in the air and turns brown on standing, so it must be observed immediately", "So an instrumental method would give a more reliable result"], answer: "Add sodium hydroxide solution: a green precipitate shows iron(II) ions and a brown precipitate shows iron(III) ions. Interpreting the result is tricky, because if both ions are present the brown precipitate can mask the green one, and green iron(II) hydroxide is oxidised by oxygen in the air and turns brown on standing, so it must be observed straight away. An instrumental method would give a more reliable result." },
    ],
  },
}
